/* 平成14年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h14.committeeSessions.push(...[{"id":"h14-20020415-9","meetingId":"h14-cm04","date":"2002年4月15日","dateIso":"2002-04-15","committee":"文教委員会","time":"午後１時１５分～午後４時２９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を70件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"山路委員","kind":"質問・要望","question":"そもそもの国の予算で目的といいますか、数多くの人に初期の段階でＩＴに、インターネット、ｅメールができるぐらいにとか、簡単なことだと思うんですけれども、１万１,０００人が目標で９,０９８名、予算は９,８００万円と言われましたけれども、人数的に下回っていますけれども、予算はもう使われたんですか、余っているということじゃないんですか、その辺について説明していただきたいと思います。","respondent":"上川内生涯学習課長","answer":"余った分は生涯学習課で引き受けて、平成１３年度におきましては９,０９８名という数字になったわけですが、委員おっしゃるとおり目標値で申請していますから不用額が出まして、それは東京都にお返ししております。","voiceIndex":10,"id":"exchange-001"},{"speaker":"山路委員","kind":"質問","question":"そうなりますと、今年また新しくやるということですが、それは区独自に計画しているということですか。","respondent":"上川内生涯学習課長","answer":"契約落差とか、予定に足りなかったところ、東京都は国から補助金をもらっているわけでして、それにつきましてはまた平成１４年度に申請をしてくださいということを呼びかけております。私どものほうとしましても、今申請をしています。","voiceIndex":12,"id":"exchange-002"},{"speaker":"山路委員","kind":"質問","question":"そうなりますと、平成１３年度の総括としまして、１人でも多くの人がパソコンを扱えないことがないようにという当初の目標は達成したとお考えでしょうか。","respondent":"上川内生涯学習課長","answer":"ほぼ達成できたのではないかと、ただしまだ余裕があるということで、さらにスキルアップの意味もありまして申請しています。","voiceIndex":14,"id":"exchange-003"},{"speaker":"山路委員","kind":"意見","question":"現場からの意見もいろいろ聞いたんですけれども、途中でやめたとか、学校施設を主に多く使っておりましたので、その中でＰＴＡの方に対する負担があまりにも重過ぎるということで、相当苦情もあったんです。メリット、デメリット両方の苦情もあったということで、今年は学校施設は使わないで、新たにクラスを変えてやるということですけれども、どういうことを考えていらっしゃるのか。","respondent":"上川内生涯学習課長","answer":"場所はきゅりあんを使って、ノートパソコンを備えつけてありますので、４００人を対象にきゅりあんでやる予定でおります。","voiceIndex":16,"id":"exchange-004"},{"speaker":"山路委員","kind":"提案","question":"まだ計画段階で、具体的にはまだ決まっていないということですね。この陳情の趣旨でありますけれども、「サポート体制を整備し、援助・助成をすること」ということですけれども、具体的にＩＴ講習会というのはいろんなランクがあると思うんです。お助けマンみたいなところもあればいいんじゃないかということで、昨年提案したことがあるんですけれども、その辺のサポートはどのように体制を考えられているか。","respondent":"上川内生涯学習課長","answer":"国の補助金でやるＩＴ講習会は、初歩的な基礎編のものを対象とした補助事業でございまして、平成１３年度と同じような講習内容で実施する予定です。お助けマンというのは、情報ボランティアのことをおっしゃっているのでしょうか。","voiceIndex":20,"id":"exchange-005"},{"speaker":"山路委員","kind":"意見","question":"地域ボランティアの方も含めてということで、そういうふうにはなるかと思うんですけれども、新しい方式としまして、文京区で登録で気軽にパソコン初心者のための無料練習場を開設するという情報は入っていますね。新聞にも載っておりましたので、そういう方向性のことは何か考えていらっしゃるのか。","respondent":"上川内生涯学習課長","answer":"今後平成１４年度に向けまして、生涯学習をはじめ各所管でもさまざまなパソコン、公開大学講座、高校講座、小中学校の公開講座もありますから、そういう中のパソコンの講座をご自分のレベルに合わせて、わからない方は基礎編に入っていただくとか。","voiceIndex":22,"id":"exchange-006"},{"speaker":"山路委員","kind":"意見","question":"大体、わかったような、ちょっとわからないところもあったんですけれども、要するにに昨年基礎をやっているから、今年はクラスを変えて初級対象とか、そういう方向を考えるといったわけですよね。ここの陳情の出ているのは、初心者対象をサポートしてほしいということですよね。この辺も含めて、多角的に予算を請求してやるということでよろしいわけですね。","respondent":"上川内生涯学習課長","answer":"全体で平成１４年度の各所管の予定を積み重ねますと、定員２,５８５名のパソコン講座が開かれる予定になってあります。","voiceIndex":24,"id":"exchange-007"},{"speaker":"山路委員","kind":"質問","question":"もう１点ですけれども、全国の５５０万人の目標に対して自治体の取り組みを見てみますと、外国人の方も対象になっている自治体もあるんです。そこで、予算特別委員会でお聞きした時点で時間が来ましたので聞けなかったんですが、品川区に約１万人ぐらいいらっしゃいますね。その中で参加した方は、東京都で掌握しているということでしたけれども、品川区で大体数はつかんでいらっしゃいますね。","respondent":"上川内生涯学習課長","answer":"受付の段階で、年齢と人数は把握しているんですが、基本的に日本語でやるものなので、日本語が話せる外国籍を持っている方とか、そういう分類の数は把握しておりません。","voiceIndex":26,"id":"exchange-008"},{"speaker":"山路委員","kind":"質問","question":"自国語でできる範囲はいいんですけれども、１万人もいらっしゃるんですから、日本語が話せなくて必要なことの調査をされて、外国の人だけで１教室を設けられるのだったら設ける必要があるんじゃないでしょうか。自治体で外国人を対象にＩＴ講習会をやっているところは、その部分の教材は自国から取り寄せているといいますね。東南アジアとかは日本より進んでいるじゃないですか。","respondent":"上川内生涯学習課長","answer":"外国人の方というのは、英語圏の方なのか中国語なのかいろいろあると思いますが、そういう情報は入っておりません。","voiceIndex":28,"id":"exchange-009"},{"speaker":"山路委員","kind":"意見","question":"品川区にいらっしゃる外国人ですが、大体アメリカ人とか中国人とか韓国とか大体わかっているはずでしょう、その範囲で申し上げているわけなんですけれども、ＩＴ技術は先行しているとは聞いていますので、日本人よりうまいかと思うんですけれども、必要性があったら調査をして、外国人対象のＩＴ講習会も二、三十人ぐらいいらっしゃったら持つ必要があるんじゃないかと。","respondent":"上川内生涯学習課長","answer":"日本の方と同じようにできると思いますが、ニーズというのは私のほうも具体的には伺っておりません。","voiceIndex":30,"id":"exchange-010"},{"speaker":"山路委員","kind":"提案","question":"いろんな形でやる必要がある一つとしてということで、全国の自治体はやっておりましたので、パソコンがやりずらいという方たちに非常に喜ばれているという資料を見まして、それで提案させていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":32,"id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"意見","question":"この請願の趣旨というのは、レベルアップ講座ではないんですね。区として、助成の対象ということは考えていらっしゃるのかどうか。","respondent":"上川内生涯学習課長","answer":"その人のレベルもありますし、パーソナルコンピューターですから、いろんなものが入っている機器も違う、ソフトも違う、どこで戸惑っているのか、そこが直って帰ったらまた呼ばれるとか、それから２４時間体制にならなければいけないとか、そういうふうに考えると。","voiceIndex":33,"id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問","question":"私も請願の趣旨の内容は理解するし、いいなと思っているんですけれども、ただ現実問題できないんじゃないかなと、それでお聞きしたんです。今おっしゃったように、レベルが上から下まで、専門家の方に質問しようとしたときに、受ける方が対応できない部分も出てきちゃうんじゃないかという気もしたので、やっぱりちょっと厳しいのかなと思いながらお聞きしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-013"},{"speaker":"川西委員","kind":"意見","question":"最後のほうの似たようなことですけれども、自宅に戻って初心者基礎講座を受けていろいろやっていく中で、頻繁に起こる疑問に対して、日常的に答える体制は無理だということで、平成１４年度はレベルアップ体制ということで、さっきの説明のような一定程度の策を組んだということしかないわけです。そうすると、ちょっとこの請願の趣旨からすると違うような気がしますね、その辺を。","respondent":"上川内生涯学習課長","answer":"レベルアップ分もありますし、ほとんどの部分が基礎的な講座を各所管で再度平成１４年度はやっているんです。平成１３年度に基礎編に参加した方でも、もう一度基礎編に入って復習することはできますし、講座という形で行います。","voiceIndex":36,"id":"exchange-014"},{"speaker":"川西委員","kind":"質問","question":"もう１点、平成１３年度の予算を組むときに、多少聞き違いかもしれないけれども各学校に全部設備しましたね。それから、実は私はこれに参加して、校長先生だとか教頭先生、ＰＴＡの皆さんがいらしっゃる、暑い最中に夏休み中でしたから、手当というのは全然出ないんですか。","respondent":"上川内生涯学習課長","answer":"９,８００万円をどこでやったかというと、教育施設、小中学校の５８校と５文化センター、そのほかに男女共同参画センター、心身障害者福祉会館、品川図書館、中小企業センター、きゅりあん、私立学校、いすゞシステムサービス、メイプルセンター、全部で７４カ所。","voiceIndex":38,"id":"exchange-015"},{"speaker":"川西委員","kind":"質問","question":"そうしますと、平成１４年度というのは、きゅりあんと中小企業センターと心障会館、その辺に絞りましたね。学校施設の設備というのは、とりあえず一般は使わないというお考えですか。","respondent":"上川内生涯学習課長、指田教育次長","answer":"メールとか使うので、また１年間の契約を全部の台数にしなければいけないので、やっぱり平成１３年度みたいに集中的に講座をやるわけではないので。その金額が何百万円というふうにかかってまいりますので、今現在のところではそこまでいかずに、きゅりあんだとか中小企業センターで契約した分だけで動かしていこうと考えておりますので、近場のところでは学校がいいんですけれども。","voiceIndex":43,"id":"exchange-016"},{"speaker":"桜井委員","kind":"質問","question":"別の角度で質問したいんですけれども、特に障害者あるいは高齢者とここに書いてありますね。私たちも議会に取り上げた角度として、特に障害者の皆さんへのサポート体制ということが気になっているんです。例えば、ここは教育委員会ですから福祉の分野とはちょっと違うかもしれないけれども、例えば生涯学習という角度から見ても可能かなと思うんですけれども、何か障害者のところで説明してください。","respondent":"上川内生涯学習課長","answer":"パソコンの指導支援者講習会を定員２０名で行って、ボランティアを養成していくということ。それから、しなやかネットの会員を中心としまして月２回程度、１回に２人程度の個別対応のコースをやっていくというふうに聞いております。","voiceIndex":46,"id":"exchange-017"},{"speaker":"桜井委員","kind":"質問","question":"８０名というのは、これから申込みを受けるということですね。前回やったときの実績もあるのかなと、全く新規の８０名じゃないわけですね。それから、心身障害者福祉会館でやるということは、所管的には福祉の所管で教育委員会と離れているということですか。そういう角度から、生涯学習的な発想で力を入れるとか、その辺はどうなんでしょうか。","respondent":"上川内生涯学習課長","answer":"時間も長くかかりますし、教え方も一般の方を教える指導者では馴染まないという部分がありますので、生涯学習課でも持っておりますけれども、心身障害者福祉会館で、それなりの機器でプログラムを障害者対応にしたものでやるのがベストだと考えています。","voiceIndex":48,"id":"exchange-018"},{"speaker":"桜井委員","kind":"質問・要望","question":"心身障害者福祉会館の場合は、場所的には確かに制度として活用していく上でふさわしい施策だと思っています。ただ、やはりあそこまでいくというのは、一定程度の限界もあるし、私はより制度的な意味では、実績を踏まえて生涯学習の分野でも、例えば文化センターという角度もぜひ広げていただきたいなと、これは要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-019"},{"speaker":"高星委員","kind":"質問・要望","question":"そこで考えてみたときに、私は紹介議員になっているんですけれども、こういう要望も出てきてしかりなんだろうなというふうに思います。確かに、区が直接業者と係わり合うというのは、なかなか難しいこともあるかもしれないけれども、実際上そこまで火をつけてしまったというと言葉が悪いけれども、きっかけをつくってしまったということから、できるだけ金のかからない体制を考えてできないんですか。","respondent":"上川内生涯学習課長","answer":"仲間をつくって、その中で学び合うということで、うちのほうでは自主学習グループとか支援をしていますので、そういうところから一つ一つやっていただかないと、これはちょっと無理かなと考えています。","voiceIndex":51,"id":"exchange-020"},{"speaker":"高星委員","kind":"質問","question":"私が気になっていたのは、業者にちゃんとテキストがあって、わからないところは質問してくれと書いてあるんだから、それはそれでいいんです。ただ、先ほど言っていた例えば障害を持っている人とかは、個人的にも指導しなければならないケースはあると思うんです。それから、自主学習グループ支援の事業をしていると言いましたね、それはどういうことなんですか。","respondent":"上川内生涯学習課長","answer":"生涯学習の基本的なことは、行政がこれをやりなさいとか、あれをやりなさいとかというのではなくて、自分の学びたいことを自主的に主体的にずっと学んでいただくのが原則だと考えていますので、ＩＴの勉強もいろいろな学習と同じように。","voiceIndex":53,"id":"exchange-021"},{"speaker":"高星委員","kind":"質問","question":"今の話でよくわからなかったのは、自主グループ支援というのは講習会を受けた中で、あるいは受講が終わった人に、「こういうグループをつくりなさい」という指導をしていくということですか。","respondent":"上川内生涯学習課長","answer":"社会教育登録団体の要件に合えば、文化センターと施設の優先使用、それから施設の利用料の５割減額等、それからまた自主グループになると予算の範囲内ですけれども、年に１回程度は講師派遣料を持ちますよという制度もありますので。","voiceIndex":55,"id":"exchange-022"},{"speaker":"松澤委員","kind":"質問","question":"１人ということですね。どういう方かわからないですか。","respondent":"事務局","answer":"それはわかりません。","voiceIndex":59,"id":"exchange-023"},{"speaker":"松澤委員","kind":"質問","question":"紹介議員で高星委員がいらっしゃるんですが、この方とお会いになって、どんな感じの方ですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-024"},{"speaker":"松澤委員","kind":"質問","question":"こういうときに請願者の場合は、こういう団体とか何名署名して、これだけの方が署名していますよというものが多いものですから、それで個人の方が請願をして、各党、各会派の方が署名しているので、何でかなと感じたんです。初心者に対して支援するための民間の会社を、空き店舗対策でやろうという形を取って、どこへ入れようかとやっているものですから、それらから見ると、これを始めると行政が邪魔をする。","respondent":"指田教育次長","answer":"私どももこの請願をいただきましていろいろ検討してみましたけれども、まず１点目のＩＴ講習会というのはあくまでも区ではなくて、当時してきたことを考えていただきますと、一つの景気浮揚というものもありながら、要するに情報を皆さんで培ってほしいという形で国が歩みかけて。","voiceIndex":63,"id":"exchange-025"},{"speaker":"桜井委員","kind":"質問・要望","question":"確かに私もやっていて、本当に悩むわけです。ただ、私はさっきから言っているように、ここでの趣旨というのは、確かに行政として限界はあるけれども、ＩＴへの第一歩じゃないですか。だから、さっき申し上げた障害者の講座とか、あるいは高齢者の講座とか、あるいは社会登録団体になっての補助とか、必ずしも初心者向けでなくても、一歩講習のランクがあるわけじゃないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今の話だと、最初のスタートが違ってきちゃうんです。私は個別に対応できるというふうにしか取れなかったんです。趣旨はわかるんですけれども、行政がやるんですかと聞いたのは、個人的なものじゃないかなというところからスタートして質問をしているんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-027"},{"speaker":"高星委員","kind":"確認","question":"委員会の流れの中で、委員長の仕切りで今回は継続して、それまで中身を確認しましょうと言うのであるならば、私は結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-028"},{"speaker":"桜井委員","kind":"意見","question":"それは個々に紹介議員を通してやるのか、それとも委員長が請願代表者にお会いするのか、どういうふうな……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":69,"id":"exchange-029"},{"speaker":"桜井委員","kind":"意見","question":"たまたま高星委員がこちらにいらしたけれども、それぞれ紹介議員になっているから、もしそれであればうちの上山議員を通して請願代表者に聞いてもらってもいいんだけれども、それぞれがそれぞれに聞いて違うなんていうことはないだろうね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":72,"id":"exchange-030"},{"speaker":"川西委員","kind":"質問","question":"その方に指導を受けてＩＴをいろいろやっているんですから、そのぐらいの方です。請願の趣旨に書いてあるとおりみたいですよ、「自宅に戻って復習する際に、疑問点や不明なことが頻繁に起き、どこに尋ねればよいのか途方に暮れているのが実情で」。ですから、グループだとか拠点指導方式ではなく、日常的に２４時間かどうかはわかりませんが、日常的に相談できる体制が必要だというのが趣旨だと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-031"},{"speaker":"桜井委員","kind":"意見","question":"例えば請願代表者にそれぞれの紹介議員がどうだこうだと聞くのも、議会としてあれですよね。だから、私の案ですけれども、委員長なり正副委員長のところで趣旨を聞いていただいてというのが……。私が直接電話して、それぞれ皆さんが電話しても──要するに個別にしてほしいのか、そこなんですよ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":74,"id":"exchange-032"},{"speaker":"高星委員","kind":"質問・要望","question":"私も正直なことを言えば、辻議員の引き回しで紹介議員になったんですよ、私もこれを読ませてもらって。ただ、中身として見れば、大きな流れとしは私自身は紹介議員になったんだけれども、やっぱりＩＴ全体の底上げを少しでも多くの人にしてもらいたいという願いからだけでありまして、そういうことはご理解いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-033"},{"speaker":"桜井委員","kind":"質問・要望","question":"４点ほどありますが、一つは全体の小学校学級数の４月１日現在の網かけのお話をいただいた学級維持制度は東京都の制度ですけれども、このことによって具体的にどういうふうに、例えば人の人数的なものがあるのか、クラスが増えるということですからそうかなと思うんですけれども、学校への具体的な変更を知りたいと思います。そちらで計算ができてから教えていただきたいと思います。","respondent":"谷田部学務課長","answer":"私どもは放課後児童対策につきましては、第二延山小学校で行ってありますすまいるスクール、今年度は３校追加いたしまして４校で実施しているということで、放課後対策については学校を中心として事業展開をしているというふうに考えてあります。","voiceIndex":81,"id":"exchange-034"},{"speaker":"桜井委員","kind":"質問","question":"２番目の３０人学級の関係ですけれども、そうすると２４％が逆に言えば３１人以上という理解でいいですね。それから中学校の場合も教えてください。それから、先ほどの学童保育クラブ関係は、私は具体的に滝王子学童保育クラブの関係を申し上げたんです。この辺は前回の２月のときも質問して、その後教育委員会のところで具体的にどういうふうにサポートをされているのかどうか、あれば聞きたいと思います。","respondent":"谷田部学務課長、青木指導課長","answer":"先ほどの私の説明で、小学校の３０人以下の学級数の占める割合を７２％と、３１人以上は２８％という関係になっております。それぞれの学校の状況に応じて、それぞれの学校と相談しながらサポートしていきたいというふうに考えております。","voiceIndex":83,"id":"exchange-035"},{"speaker":"桜井委員","kind":"質問・要望","question":"そのことは地域の親からも結構要望として入っているんです。ですから、そういう実態を学務課長としてお調べいただいて、実態をどういうふうに考えていくのかというのを、次回でもいいですからぜひ要望しておきたいと思います。親は非常に心配していますので、なければ「ない」ということで、もちろんそれは構いません。","respondent":"谷田部学務課長","answer":"学童保育クラブに関しましては、児童課長に私から伝えておきます。それから、２点目の予算のつけ方、学校の人数によって増減があるかないかという影響ですけれども、こさは基本的にないと思ってあります。","voiceIndex":86,"id":"exchange-036"},{"speaker":"川西委員","kind":"質問・要望","question":"単純なことで申し訳ありませんが、城南小学校の入学式に行きまして、ここにも出ておりますように３８名なんですね。職員紹介という入学式の流れがあります。そんなようなことなんですが、そのことを把握して今後のことをどうお考えになっているのか。それから、旧日本たばこはどこの学区域になるのか、その辺で地域の人がとても騒いでいるので、若い世代もおりますので聞かせていただきたいと思います。","respondent":"谷田部学務課長","answer":"１点目の３８名学級を２クラスにすることは、いわゆる４０人学級が基本ですから、２学級にはならないです。","voiceIndex":88,"id":"exchange-037"},{"speaker":"川西委員","kind":"質問","question":"保育園が飽和状態で、八潮団地にみんな橋を渡ってやむを得ず行っているにも係わらず、台場幼稚園も城南幼稚園も閉園になったということになりますと、おそらく今度ゴルフ場跡にできるものは、分譲マンションですからマンションを買いますと夫婦で働くということがありますので、事前調査をしながら、今保育園があれだけ満杯なんだから、３年、４年後には学校の就学も増えていくと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":90,"id":"exchange-038"},{"speaker":"鈴木（真）委員","kind":"質問","question":"具体的に、こっちのほうが早く出てくるんですけれども、それはどういう対応を、地域的には鮫浜小学校なんですけれども、幼稚園でいうと浜川保育園、城南幼稚園も今年は定員から１人割っていただけですから、かなり園児が増えていると思うので、その辺はどういうふうにお考えになっているのでしょうか。","respondent":"谷田部学務課長","answer":"５００戸供給して、５００戸のうち児童・生徒が発生するのは何％なのかという数式に当てはまらない部分がありますので、それは私どもも子どもがどの程度出るかというのは、購入される方がどういう層なのかということを開発担当から事前に十分な情報をいただいて。","voiceIndex":91,"id":"exchange-039"},{"speaker":"高星委員","kind":"質問・要望","question":"それを教育委員会に上げて、そこで関係する方で決めて委嘱する形になるわけですね。往々にして、ときどき気になるのは、教育委員会って、まさしくその中で学校関係者というのは、はっきり言うとまだ守りが強いというか、現場団体ではなかなか払拭仕切れないところがあるじゃないですか。だから、そのことをひとつ大丈夫かなということをお聞きしたいと思います。","respondent":"青木指導課長","answer":"ただ、学校改善に役に立つということですか、そのための評価ですので、単なる学校批判だとか、学校間のランクづけだとか、そういうような学校評価ではございませんので、それぞれの学校が少しでも改善につながっていくようにということで。","voiceIndex":97,"id":"exchange-040"},{"speaker":"高星委員","kind":"質問・要望","question":"そうでなければいけないのであって、それしか言いようがない。言い放しで全部終わっちゃうのか、全部言いたいことをああだこうだ言って、あとは中で突き合わせて整理してまとめてくれといって終わっちゃうのか、それを外部評価者がまとめ上げて、一定程度の評価を出した後もきちんとそれをチェックしてという、委嘱の期間ということも含めて、その辺の流れを教えていただきたいと思います。","respondent":"青木指導課長","answer":"そして３月の段階で、もう１回説明会を持ちます。３月の段階では、このような形で評価者の皆さんのご指摘、評価を生かしておりますというような形で、校長から外部評価者の方たちにご説明します。","voiceIndex":99,"id":"exchange-041"},{"speaker":"桜井委員","kind":"質問・要望","question":"だから、断片的に一つの面だけを切って評価というのは、非常に危険性があると思うんですけれども、そういう視点での学校を評価していく上でのお互いの意見交換というんですか、当然レクチャーというんでしょうか、評価委員の皆さんがどういうお考えを持っているかというのがあるんですけれども、ともするとそこによって運営母体というのか、実際に運営するのは学校ですけれども。","respondent":"青木指導課長","answer":"実施要綱ですが、これは現在つくってあります。２点目のスケジュールに関してですが、５８校同時かということですけれども、同じ日ということではございませんが、委嘱式は同日に行いますので、それがスタートになると考えております。","voiceIndex":101,"id":"exchange-042"},{"speaker":"桜井委員","kind":"質問・要望","question":"私は外から見て、学校施設をチェックというんでしょうか、教育委員会だけだと、こんなものかというのがあるかもしれないですけれども、やっぱり専門家から見て２１世紀の学校像というか、施設像という点では、もっといろいろ意見を聞きたいなというふうに思いますし、ぜひ教育内容だけではなくて、学校環境整備というものも項目に加えていただきたいというふうに思うんですけれども、いかがですか。","respondent":"青木指導課長","answer":"今回の学校評価がいかにつくられたのか、前にもご説明したと思います。","voiceIndex":103,"id":"exchange-043"},{"speaker":"桜井委員","kind":"質問・要望","question":"できたらいただきたいと思います。５月１３日ということは、評価委員会というのはほとんどそろっているという理解ですね。","respondent":"青木指導課長","answer":"まだです。今、学校では早速いろいろと、学校のそれぞれの形で進めている最中です。こちらのほうにそれぞれの学校の候補者がそろったところで、整理をして５月１３日を迎えたいというふうに考えております。","voiceIndex":105,"id":"exchange-044"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"３月の委員会で説明をいただいたときに、外部評価の評価者は専門的な人に学校に入ってもらうという答えがあったと思うんですが、これは学校５８校に５８人の専門家が入るということになっているんですか。それからもう１件、社会性・人間性の育成に関しての２点というのは、一般の評価者はちょっとつかみきれないんじゃないかなと、その点についてお答えいただきたいと思います。","respondent":"青木指導課長、指田教育次長","answer":"学校のほうも情報を当然提供していきますので、そうした学校の情報と授業参観とか子どもたちの様子というようなところで、学力とか社会性とかというものを見ていただくということになるかと思いますので。具体的にどういうふうにするのか、研修をやらないとなかなか難しいだろうと思っていますので、専門用語で評価者訓練と呼ばせていただきますけれども、一応研修的なものを考えているです。","voiceIndex":109,"id":"exchange-045"},{"speaker":"鈴木（真）委員","kind":"質問","question":"多分評価者になるんだろうというふうに言われている、ちょっと声がかかっている方から、その辺の質問もあったんです。直接学校の中でなくて別のケースで、「本当にわかるの」という話を。それから、専門家の方が５８人、ばらばらに１人が２校、３校を受け持つということはなくて、５８人がばらばらでやるわけですか。","respondent":"青木指導課長","answer":"ある方は２校を持つというような方も出てくるかと思いますが、そういう方たちのスケジュール的な調整もあるかと思いますので、１校ないし２校、もし「３校でもいいよ」という方がいらっしゃれば、またお願いするかもしれません。","voiceIndex":112,"id":"exchange-046"},{"speaker":"鈴木（真）委員","kind":"質問","question":"聞きにくい部分ですけれども、評価者の方に対しての実費的なものは出るような形になるんですか。","respondent":"青木指導課長","answer":"あくまでボランティアという形でお願いしますけれども、１年間終わった段階では心ばかりの形のものはお示ししたいと思います。","voiceIndex":114,"id":"exchange-047"},{"speaker":"松澤委員","kind":"意見","question":"外部評価委員会の人選ですけれども、ＰＴＡはわかるんですけれども、地域団体関係者は町会関係あるいは地域の民生委員・児童委員、保護士あたりが入るのかなと。学識経験者は今出ていますけれども、なかなかどの学識経験者というので、区の評議委員会は議員も学識経験者という形だろうという話ですが、この中で議員は選びませんという形になっているのか、優秀な議員を選んでいいというのか。","respondent":"青木指導課長","answer":"議員はこの対象には入っておりません。","voiceIndex":116,"id":"exchange-048"},{"speaker":"桜井委員","kind":"質問","question":"それで実施要綱ができていないというのは、ちょっと腑に落ちないんですけれども。ただ、報酬というのか実費というのか、手当てというのは正確ではないんですけれども、きちっとそれはすべきだと思うんです。１年間でご苦労さまでしたと、まさか商品券みたいな形となれば、それこそ評価者に失礼だし、きちっとすべきだと思うんですけれどもいかがですか、予算化していないんですか。","respondent":"指田教育次長","answer":"予算化はしていますので、今言われた話というのは、ある意味において、そんなにいっぱい高くは出ませんという意味で、ボランティアと言っただけであって、実費弁償額のお支払いは当然のことだというふうに思っております。","voiceIndex":118,"id":"exchange-049"},{"speaker":"桜井委員","kind":"質問","question":"学力向上推進協議会というのは、どういう性格を持つものでしょうか。構成メンバーとかあるいは委員というのが正確なのかわかりませんが、３年間の常設なのか、当然ながらそれぞれ保護者とか地域住民という枠がありますが、これはメンバーの中の一員というふうにしていくのか、協議会の性格と構成と内容を教えてください。","respondent":"青木指導課長","answer":"最近、道徳の公開講座ということで、地域の方たちに授業を見ていただいたり、協議会に入っていただいたりしながら、道徳教育を普及するという方法を取ってありますが、それに似たような形で保護者の方や地域の方たちにも。","voiceIndex":125,"id":"exchange-050"},{"speaker":"桜井委員","kind":"質問","question":"何かよくわからないんですけれども、私が質問したのは、要するに教育委員会側に置くのか、それとも学校の大間窪品川区と荏原第三中学校の合同でやる協力を推進していく学校のための推進協議会なのか、要するに協議会の性格なんです。それで、何をするかというと、教材開発とか指導体制とかをやっていくんですか、これはどっちかというと教師側の作業ですよね。","respondent":"青木指導課長","answer":"これから学校とも連絡を取り合って、具体的な内容は詰めていきたいというふうに考えています。","voiceIndex":127,"id":"exchange-051"},{"speaker":"桜井委員","kind":"質問","question":"依然としてわからないんですけれども、国レベルだって県レベルだって、そうすると品川区レベルであるということになると、品川区の教育委員会の中に推進協議会を置くというふうに、よくわかるように教えてください。","respondent":"若月教育長","answer":"協力校が４校あります。これはまだ校長に投げかけますから決まりではないんですが、教育委員会として考えているのは、初年度はこの４校の学校の校長と研究市民というのがそれぞれの学校におります。この研究市民で構成をする。","voiceIndex":129,"id":"exchange-052"},{"speaker":"桜井委員","kind":"質問・要望","question":"少しわかってきたんですけれども、要するに推進協議会を開くというふうに声をかけるのはどこかなということで、性格が決まるという気がするんですが、それだけもう１回教えていただきたい。今のお話だと、大臣のアピールに基づいて１月１７日でしょう。そこから予算がついていくと言えば、本当ならばこれだけの準備は１年間かけてどうやっていこうかという、そういうぐらいの規模だと思うんです。","respondent":"若月教育長","answer":"これは大変素晴らしいということで、むしろ文部科学省のほうが、それを全国に一般化できないかということで、この事業ができたというのが事実なんです。","voiceIndex":131,"id":"exchange-053"},{"speaker":"桜井委員","kind":"質問・要望","question":"ですから、そういう点では習熟度別学習の、例えば冨士見台中学校でも行ったのも拝見しましたけれども、いろんな意味で少なくとも能力度別という形を取るのではなくて、きちっと子どもの学力をつけていく、一人ひとりの力をつけていくというところと、やっぱり集団で学び合う喜びを得ていくという両面が必要だというふうに思いますし、そこのところは十分に配慮いただきたいというふうに思います。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":133,"id":"exchange-054"},{"speaker":"山路委員","kind":"質問・要望","question":"この小・中をやられたときに見に行かせていただいたんですけれども、今最も必要だなということで、私は個人的に感動して帰ってきたんです。中身につきましては、全国の教師ばかり見えていましたけれども、非常に難しかった。もちろん全体でということになるんでしょうけれども、学力の資質ということに関しては、どういう角度を置かれる予定なのか聞かせていただきたいと思います。","respondent":"青木指導課長","answer":"今、委員がおっしゃたように、大変難しい問題であるというのは、学力をどういうふうにとらえるのか、それを保護者の方たちにもどういうふうに理解していただくのかという点でも、やはりこういう場を使って学力のとらえ方ということを。","voiceIndex":134,"id":"exchange-055"},{"speaker":"山路委員","kind":"意見","question":"もう一つですけれども、中学校の入学式に参加させてもらったときに、担任の教員を一人ひとり紹介されますね。それに伴ってチーム・ティーチングの先生が紹介されたんです。ここの中にも書いてありますけれども、それとの関連性というのは、どういう研究をされてきたのか、特に算数・数学ということですね。","respondent":"青木指導課長","answer":"そのような形で、教員が１人のところを２人で見ていくことによって、個に応じた一人ひとりの子どもの能力にふさわしい学習指導を行っていくことで、当然学力もついてくるわけですけれども、基礎的なことを繰り返し行うことで基礎的な力をつけて。","voiceIndex":136,"id":"exchange-056"},{"speaker":"山路委員","kind":"質問","question":"能力の境界というんですか、チーム・ティーチングと習熟度別の補助教員をここに対応されていますね、各学校に充実していきたいんじゃないかと。それにおける個々の生徒の能力を、１４年度に入りまして全国一斉に調査されましたね。それも含めて、効果というのはもちろん上がっていると思うんですけれども、具体的にどういうふうになったというのはつかんでいらっしゃるんでしょうか。","respondent":"青木指導課長、若月教育長","answer":"この間の文部科学省のあれは部分的な抽出した形で調査したということですので、品川区の実態というのは具体的に結果として出てきているわけではございませんが、現在行われている品川区の習熟度別とか教科担任制というようなものが。やはり、そういう日頃の努力というものをこれから開発をしていく必要があると、こんなふうに考えています。","voiceIndex":138,"id":"exchange-057"},{"speaker":"山路委員","kind":"意見","question":"まさに私もそのとおりだと、悩んでいた１点なんですけれども、息子とか関係者とか友達とかにいろいろ聞きましても、基礎的学力というのは感じてこなかったんです。そういうことをどうやって解決するか、今、教育長が言われたとおりでありますけれども、学力向上フロンティア・スクールの研究によって、全体に定着してくることを期待しているものです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":141,"id":"exchange-058"},{"speaker":"高星委員","kind":"質問","question":"プラン２１の中で教育長がずっと力を入れている徹底的に基礎学力を身につけるべきだというスタイルで、今回こういうフロンティア・スクールの中で個に応じたことに相当力を入れてやっている。それで習熟度別になっている。もう一つは、基礎学力の算数を特に重点的にやっているけれども、推進協議会の中で地域住民との関係も含めたそのほかの教育、その辺はどう考えらているのかお聞きしたい。","respondent":"青木指導課長","answer":"２点目の算数・数学だけだということですけれども、算数・数学が個人の差が出やすい教科であるというところから、総体的に差を縮めて上げていくという考え方で算数や数学を取り上げておりますので。","voiceIndex":142,"id":"exchange-059"},{"speaker":"鈴木（真）委員","kind":"質問","question":"全体のレベルアップはわかるんですけれども、小・中一貫校にも絡んでくる部分もあると思うんですけれども、ほかの小学校から荏原第三中学校に入ったときに、そこでのレベルの違いが出てくることはないんでしょうか。","respondent":"青木指導課長","answer":"そういう意味での協力も成り立つわけなんですけれども、できるだけ他校から荏原第三中学校に来たときに大間窪小学校との関係が、ただそれだけではくて他校との関係でもあるんだということで。","voiceIndex":144,"id":"exchange-060"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"その辺が気になるので、やっぱりほかの学校も同じように指導を進めていってもらう形で、これは全体的にこの学校だけではなくていろんな学校に広がっていくでしょうけれども、その辺のところをなるべく意識していただきたいなという思いです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":146,"id":"exchange-061"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"だから、そういった面で全体との係わりというんですか、その中でのフロンティア・スクールの位置づけとか、そういうものも示していただかないと、本当に子どもたちはどうなっているのかというのが見えないというのが１点。５日制の問題とか、総合的な学習の問題とか、その辺も品川区の子どもがどうなっているのかというのも、今後でいいんですけれどもお示しいただきたいと思います。","respondent":"青木指導課長、若月教育長","answer":"３点目は、５日制や総合的な学習の取り組みということですけれども、そのことについても機会あるごとに教育委員会としての姿勢は当然示してまいりたいというふうに考えております。よく情報を出していると思います。これをあまり押し進め過ぎると、学校はどういう状況になるかというと、結局チーム・ティーチングをやった、習熟度をやった、こんなに育っていますということを何で示すか。","voiceIndex":147,"id":"exchange-062"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"そういった面で、すごく頑張っていらっしゃるな。だからこそ、地域の方にもその中身を知っていただきたいなと思います。その辺で参加の仕方をもっと多くの人の意見が酌み取られるような、そういうところでの理解というんですか、いろんな公募の仕方もしていると思うんだけれども、そういうコミュニケーションの中で理解されるような、その辺をもうちょっと充実していただきたいと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":150,"id":"exchange-063"},{"speaker":"桜井委員","kind":"質問","question":"転任が多いなと思うんですけれども、過去の実績からしてどうですか。例えば、去年、一昨年はどうですか。","respondent":"青木指導課長","answer":"去年は小学校で退職した方が２人でした。中学校はいらっしゃいませんでした。退職者が少ないときは、異動の数も当然少なくなります。退職者が多い場合には、先生が抜けることにおいて、いろんな形で異動の幅が広がるということになりますので、こういうような形になります。","voiceIndex":155,"id":"exchange-064"},{"speaker":"桜井委員","kind":"質問","question":"つかぬことですけれども、前館長の退職金はいかがなんでしょうか。","respondent":"上川内生涯学習課長","answer":"非常勤職員ですので、退職金はございません。","voiceIndex":162,"id":"exchange-065"},{"speaker":"桜井委員","kind":"意見","question":"ちょっと時間もあまりないところで恐縮ですけれども、次回でもいいんですが小・中一貫校について、例えばこの間公募されていた準備委員が決まったのかどうか、準備委員が開かれたのかどうか。次回でもいいんですけれども、もし時間が取れればお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":167,"id":"exchange-066"},{"speaker":"桜井委員","kind":"質問・要望","question":"要望しておきます。区民の関心も高いので、ぜひ次回にいろいろと経過はありますけれども、教育長自身も準備委員会に入っていらっしゃるわけですから、ストレートにお聞きしたいなというふうに思っていますし、質問書の話は聞いていますので、どういうご答弁だったのかというのは、文書で回答をいただいたとすれば、情報公開でいただけるんでしょうか。","respondent":"指田教育次長","answer":"質問書は情報公開の手続を取ってもらえれば、要望書・質問書は公文書ですから……。","voiceIndex":172,"id":"exchange-067"},{"speaker":"高星委員","kind":"質問・要望","question":"第二日野小学校の場合、土地が今どういうふうな状況になっているのか、それを知りたいということと、この間説明に入ったのは日野中学校と第四日野小学校だけではないですよね。行かれた学校と日にちを教えていただきたいと思います。","respondent":"指田教育次長","answer":"一番初めに２月９日に日野中学校に行き、その後大崎第一地区連合町会の役員会に行って説明をしました。１３日に第二日野小学校に行きました。","voiceIndex":176,"id":"exchange-068"},{"speaker":"高星委員","kind":"質問・要望","question":"いろいろ説明に入って、日野中学校では要望書が出て、それの回答も。それらの話は情報公開で手続を踏めば、要望書と回答書そのものはすぐ出ると。ただ、話の中身はまだ発表できないということでしたね。","respondent":"指田教育次長","answer":"何も隠すつもりは全然ありません。したがいまして、よく委員長と相談をさせていただいて、どういう形で委員会にご報告をいつできるかということを、やはり私ども教育委員会もありますので、そこのところの出方も含めながら、よく相談をさせていただければと考えています。","voiceIndex":178,"id":"exchange-069"},{"speaker":"藤田委員長","kind":"質問・要望","question":"各委員、その他はありますでしょうか。昨年の９月２６日の当委員会におきまして、海外調査団への依頼ということで、各委員の意見をお伺いしまして、その後議長あてに、このような意見がありましたという報告をいたしました。委員の皆様にも「平成１３年度品川区議会海外調査報告書」がお配りされておりますので、ご参照いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":182,"id":"exchange-070"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4434#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":48906,"voices":182}},{"id":"h14-20020415-5","meetingId":"h14-cm04","date":"2002年4月15日","dateIso":"2002-04-15","committee":"総務委員会","time":"午後１時１６分～午後３時３７分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を52件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"林（宏）委員","kind":"質問","question":"一ついいですか。事業部制を取り入れるときも、ちょっとお話があったんですけど、総務課から秘書課が独立して、秘書課長を置いて、秘書というセクションを設けたということなんだけど、依然として兼務になっているけれども、その辺の考え方だけ教えていただけますか。","respondent":"本間総務部長","answer":"事業部制が導入されたときに、この考え方等につきましては既にご説明をさせていただいているとおりですが、やはり、今般、全庁的にいろいろと定数等をいじっている中で、本来の姿とするにはまだ時期が到来していないということで、今年につきましても。","voiceIndex":22,"id":"exchange-001"}]},{"id":"topic-02","title":"の平成１４年度組織改正","agenda":"の平成１４年度組織改正","exchanges":[{"speaker":"林（宏）委員","kind":"質問","question":"ちょっとお聞きしたいんですけど、主査と係長の違いはどういうところにあるんですか。","respondent":"小野（孝）政策担当課長","answer":"要するに、担当主査は、係長の異種形態ということでございまして、組織規則によって、具体的な事務ポジションが定められていて課に設置されるという形になっているところは同等です。違いと申しますと、一応、規模による違いということが一つ言えるかと思います。","voiceIndex":28,"id":"exchange-002"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"一般企業では、あまり主査制というのはないわけですから。すぐにどうこうというわけにはいかないんで、その辺、組織の単純化、わかりやすさというなら、お考えいただきたいと、これはお願いしておきます。それから、総務部の中で、研修担当課長を、目的を達したから廃止しますという説明があったんですけれども、研修というのは、目的が達成されたんですか。その二つ。","respondent":"小野（孝）政策担当課長","answer":"もう一つ研修担当課長、それぞれ成果を上げたのかというご指摘ですけれども、研修につきましては、研修外務制度という新しい研修のシステムを、この１年間検討いたしまして、平成１４年度から実施をするということになっております。","voiceIndex":30,"id":"exchange-003"},{"speaker":"林（宏）委員","kind":"質問","question":"後のほうからいくと、では、総務課の右上の欄に書いてある説明はちょっとオーバーじゃないですか、「事業部制導入後１年が経過し、組織体制が定着したため研修担当課長を廃止する」と。にもかかわらず兼務しているわけですよ、１人の課長が二つの課を。もう一つ、その関係で言うと、担当課長の仕事がそれぞれできてきたのなら、じゃあ施設課長が今度施設担当課長になったら、１年でいくんですか。","respondent":"小野（孝）政策担当課長","answer":"１人の課長ですので、研修については、事業部制を実施するに当たりましては、人材の育成とかが非常に大切であるということで、二つの課を統合したときの初期のいろいろなことをカバーするために、研修担当課長を置いて、その部分について担当したです。","voiceIndex":32,"id":"exchange-004"},{"speaker":"林（宏）委員","kind":"質問","question":"非常に矛盾も多いし、それから、失礼な言葉だけど、説明が言い訳に聞こえる部分もある。今の施設担当のことなんかは、もう施設課長でいいじゃないですか。何か、説明するのに、組織替えをしていく変革期だからわかるんですよ。一般の人が来て、何かというときに、さっきの話も含めて、やっぱりわかりやすい組織であり、担当課長名とか、係長名としていってほしいと思うんです。何か、当座、考えがありますか。","respondent":"市岡企画財政課長","answer":"私ども、そのことと、組織運営上の秩序ということの両方かみ合わせながら、今のご指摘を考えていきたいと思うんですが、これも言い訳になってしまうかもしれないんですが、やはり、この組織の基本というのは、まず、事業部の部の段階は。","voiceIndex":34,"id":"exchange-005"},{"speaker":"北野委員","kind":"質問","question":"組織の改正で、施設課が各事業部の中に入っていって、直接発注ができるようになったというお話なんですけれども、どこまでの範囲なんでしょうか。今までは、経理のほうが金額的な問題とか、相手先を探すなど、いろいろな部分があったと思うんですけれども、どういうところに事業部制の独自性が打ち出されるようになったのか、ちょっと話していただけますか。","respondent":"片田施設担当課長","answer":"今回の組織改正につきましては、民間委託の部分をさらに広げていきたいということです。多少小規模なものであっても、一応、できるものについては民間委託を進めていきたいといったような観点で考えてあります。","voiceIndex":36,"id":"exchange-006"},{"speaker":"北野委員","kind":"意見","question":"要するに民間との設計のやり取りも含めて、それから、業者を選ぶ段階も含めて、すべて事業部に任されるのか。金額的には、いろいろな予算の立て方があるかと思うんですけれども、それは経理のほうで出すというようなやり方で、どこまでの発注が、事業部制として各事業部に任されているのかというのが、ちょっとよくわからないんです。","respondent":"片田施設担当課長、本間総務部長","answer":"逆に、計画通知等々が必要でないもの、小規模なものにつきましては、各事業部のほうが発注を行うといったような考え方です。今、課長がご説明しましたとおり、こちらに技術の職員を配置して、自前でそういう修繕等をやります。それ以外の部分につきましては、今までと同じように、今、ご紹介しました施設の担当課のほうでやる。","voiceIndex":38,"id":"exchange-007"},{"speaker":"北野委員","kind":"確認","question":"さっきいろいろ出たと思うんですが、事業部の独自性というところで、もっと踏み込んだものかなという理解が私はあったものですから、確認をさせていただいたんですが、わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-008"},{"speaker":"田中委員","kind":"質問","question":"今、区役所は電子区役所に向けてさまざまな取り組みがある中で、今回、区民生活事業部の中に設計担当係が創設されましたが、今後の組織の考え方としてなんですが、電子区役所に向けてさまざまな部分でのシステム化が進められていく今、実態で言えば、図書館の建設と職員厚生施設の予約検索システムとか、さまざまな事業の中でシステム化が進めてられているんですが、今回。","respondent":"小野（孝）政策担当課長","answer":"今回、戸籍住民課の中に戸籍電算化担当主査を設置して、これに対応するですけれども、電算化の開発については、規模だとか、内容についてさまざまです。その内容によりまして、新たに組織を設置して対応するということが必要な場合につきましては、このような対応が出てくる。","voiceIndex":42,"id":"exchange-009"},{"speaker":"田中委員","kind":"質問","question":"内容というのは、開発の規模という考え方なんでしょうか。","respondent":"小野（孝）政策担当課長","answer":"規模というのが一番大きな理由なのかと思います。","voiceIndex":44,"id":"exchange-010"},{"speaker":"田中委員","kind":"質問・要望","question":"ですから、そういうところが、また一方での懸念材料というんですか、心配なんですが、その辺は、全体で管理していくという考え方なんでしょうか。","respondent":"田中情報システム課長","answer":"開発の体制ですが、戸籍電算化担当のほうは、３年間にわたって戸籍の電算化をやります。","voiceIndex":46,"id":"exchange-011"},{"speaker":"田中委員","kind":"質問・要望","question":"組織としては、電算システムを管理する集中管理組織としたほうがいいんではないか。分散することによって、逆にそういう調整作業というものも必要になってくますし、ボリュームも、現場の要望を聞きすぎるという傾向になると思いますので、ぜひ、今後の検討課題にしていただきたいと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-012"},{"speaker":"宮崎委員","kind":"質問","question":"１点伺いたいんですけれども、企画部のところの行政評価担当主査というのが新設になっているんですけれども、その理由のところで、「行政評価事務の円滑な執行のため」ということを挙げているんですけれども、具体的にどういうことをやるんですか。","respondent":"小野（孝）政策担当課長、市岡企画財政課長","answer":"今回、行政評価担当主査を置いた具体的な理由ですけれども、平成１４年度におきまして、平成１３年度に政策として行った事務事業評価を全事業で実施をするということがあります。しかし、事務事業評価については、平成１３年度、ともかく走り出したわけですから、これを全庁の事務として定着させるためには、専任の担当主査が必要になってくるということで、より一層の業務の円滑を図るために。","voiceIndex":49,"id":"exchange-013"},{"speaker":"宮崎委員","kind":"質問","question":"そうしますと、この企画財政課の中に担当主査を置いているけれども、これは全体を見るという役割なんですか。","respondent":"市岡企画財政課長","answer":"もちろん全体を見ますけれども、特に事務事業評価というのは自己評価が原則ですから、各事業部が、まず見ます。ただ、システム的にも、それから全庁の調整という意味でも、企画部が各事業部を支援する立場ですから、全体の扇の要になるような調整事務を行うという意味です。","voiceIndex":52,"id":"exchange-014"},{"speaker":"宮崎委員","kind":"質問","question":"組織改正で、事業部制と、事務事業評価という二つの大きな改革であって、それがスタートしているんですけれども、そうすると、いわゆる事業部ごとに対等といいますか、そういう組織図のようだったんですけれども、ここでは各事業部を企画部のところで評価を誘導しているとか、そういうふうなものということではないんですか。","respondent":"榎本行財政改革担当課長","answer":"あくまでも企画部としては、各事業部を支援している形の取りまとめの部署ということで、全体的に、事業部間でどういう事業が進捗しているのかとか、どういう評価を各事業部が自己評価しているのかを取りまとめた上で。","voiceIndex":54,"id":"exchange-015"},{"speaker":"宮崎委員","kind":"意見","question":"私がちょっと疑問に思ったのは、各事業部との関係で、この役割がどういうふうな動きをするのかが、ちょっといまいち見えてないんです。それとも、やっぱり事業部は事業部で自分たちできちっとやると、そこら辺の関係がよくわからないんですけど。","respondent":"榎本行財政改革担当課長","answer":"主に企画部でやる部分につきましては、中身というよりは、事務事業評価の仕組みをどう、各事業部分にわかっていただくかということで、新たに始まった事務事業評価の仕組みですので、かなり技術的な部分で各事業部をフォローして、どういうふうに評価の事業をとらえていくのか。","voiceIndex":56,"id":"exchange-016"},{"speaker":"塚本委員","kind":"質問","question":"組織と人は関連するんですけれども、財政援助団体と出向派遣の関係の人事異動、あるいは、リタイヤ組の人たちの異動があったというふうに聞くんですけれども、そういうのがあれば教えていただけますでしょうか。","respondent":"桑村人事課長、本間総務部長","answer":"その下に新たに成年後見センターというのができまして、その関係で中川原課長ですけれども、派遣しています。それから、これまで品川総合福祉センターに出ておりました岩崎が品川区勤労者共済会派遣となっております。ということで、今、課長が説明しましたのは派遣でございまして、それ以外に退職理事者等々のそれといたしまして、品川文化振興事業団に小栗前区民生活事業部長が。","voiceIndex":58,"id":"exchange-017"},{"speaker":"宮崎委員","kind":"質問・要望","question":"目的のところで、今までは、公金管理については、「安全性と効率性を同時に求められてきたが、今後は安全性の確認を最優先し効率性も求める」というふうに変えるということなんですけれども、ちょっと言葉のところで、説明いただければと思うんです。安全性の確認を最優先するということと、効率性を求めるということの関係ですね、ここのところはどういうふうに考えておられるのか。","respondent":"小野（弘）副収入役","answer":"これからは、まずは安全性のある銀行を選びまして、その中で引合等で利率のいいところに預けていくということです。破綻ということがあり得るわけですので、まずは安全な金融機関を選択してから、その中で効率性を見ていくという考え方です。","voiceIndex":65,"id":"exchange-018"},{"speaker":"宮崎委員","kind":"質問・要望","question":"そうすると、今までは安全性、効率性を同時に求めるということだったんですね。そういう意味では、安全性と効率性を同時に求めれば、今のご説明のように、安全な中から利率のいいものを選ぶということになっていたんじゃないのかなと思うんです。ですから、今の説明ですと、ちょっと中身がどういうふうに変わったのかというのがよくわからないんです。何で、こういうふうに。","respondent":"小野（弘）副収入役","answer":"ペイオフになりましたので、金融機関が破綻するということになりまして、公金も一般の預金者と同じ扱いになるですので、より一層安全性のほうを重視していくという考え方です。","voiceIndex":67,"id":"exchange-019"},{"speaker":"宮崎委員","kind":"質問","question":"安全が土台にあってということですね。ここら辺のところは、よくわかるようにしておいたほうがいいんじゃないかなと思うんです。そうすると、ここの方針は、安全性を第一にするというのは当然だと思うんですけれども、具体的に言うと品川文化振興事業団とか、ほかに幾つかの外郭団体がありますけれども、そういうところもこの方針が徹底されるということなんでしょうか。","respondent":"小野（弘）副収入役、中尾根企画部長","answer":"こちらは、品川区公金管理運用方針ということで、区のほうの公金管理運用方針です。各外郭団体につきましても、区が行っている管理運用方針を準用するように指導していきたいと、従来から言っておりますので、そのように取り扱っていただくよう、区としても要請をしていきたいと考えています。","voiceIndex":69,"id":"exchange-020"},{"speaker":"宮崎委員","kind":"質問","question":"ぜひ、そのとおりに確実にやっていただければと思うんです。そうすると、この文言があまりあいまいに受けとられるようなものだと、やっぱり困ると思うんです。そうすると、安全性と効率性というのは、安全かつ効率的ということでいいんですか。","respondent":"市岡企画財政課長","answer":"なかなか表現が難しいところなんですが、実は、地方自治法の施行令が、ペイオフがあろうとなかろうと、「預金その他の最も確実かつ有利な方法」という言葉を変えておりませんで、そういう意味では、両方が並列的で運用されているところなんです。","voiceIndex":72,"id":"exchange-021"},{"speaker":"宮崎委員","kind":"質問","question":"そこのところは、今の説明でとめておきます。今の説明でも、安全と効率を、安全かつ効率と言えば、問題の外国債は元本保証じゃなかったわけですから、その考え方で買ったんだということになると、また同じことになっちゃうよということを、私は言っていますので、この問題はこれ以上言いませんけれども、そこのところは徹底していただくということにしていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-022"},{"speaker":"塚本委員","kind":"質問","question":"格付機関もほんとうにシビアにやらなきゃいけませんし、私ども自治体がおつき合いしている中小の機関まで、大手の取引機関がしっかり情報管理をしているかというと、そうでない可能性もかなりあるわけですから、そのときにはどうしていくかというと、やはり現実に取付け騒ぎが起きるというのは、もちろん実態が悪くなった点が見えてきて。","respondent":"小野（弘）副収入役、市岡企画財政課長","answer":"預金高を分散すると言いましても、かなりの金額がありますので、なかなかそこのところも難しいところですけれども、その中でも、安全性の高いところを的確に見極めるのがどうかということがあるんですけれども。その辺は、しっかり具体的な内容を検討して、いざとなってからではなくて、ふだんからそういう検討をしていく必要があるかもしれないです。","voiceIndex":75,"id":"exchange-023"},{"speaker":"塚本委員","kind":"質問","question":"トリガーを引かないようにということなんですけれども、ある意味では、そういうことになった場合は、公金ですから、やっぱり情けをかけずにやらなきゃいけないのかなと、私は考えていますけれども、ここのところはどちらに振るのか、数百万円ぐらいならしようがないという話し合いになるかもしれないし、６００億円からすれば。この２点、いかがですか。","respondent":"小野（弘）副収入役、中尾根企画部長","answer":"今後は、副収入役会とか収入役会がありますので、２３区でできるだけ情報を密にしながら、間違いのないような形で連携を取りながら進めてまいりたいと思います。そういう意味では、今、委員のご質問のことについては十分わかりますし、私たちの検討の中にも、そういうことは大分いろいろ入っていたという経過の中で、おくみ取りいただければと思います。","voiceIndex":78,"id":"exchange-024"},{"speaker":"中島委員","kind":"質問","question":"こういうのはすごく苦手なんで、単純な質問を、疑問に思った部分があったので、お聞きします。前回の総務委員会のときに、みずほ銀行というのはＢＢＢだとお答えいただいたような気がするんですが、これを見ますと、都市銀行でＢＢＢが３行あるから、預金はしていない形になっているんですね。そうすると、みずほ銀行というのはどこに入るんでしょうか。","respondent":"小野（弘）副収入役","answer":"まだ、どこの銀行がどこかということは申し上げないということです。","voiceIndex":81,"id":"exchange-025"},{"speaker":"中島委員","kind":"質問","question":"そうしますと、下のほうかなという想像をしてしまうんですが、こういう要注意領域になってくると、１,０００万円以上は普通預金にするというご説明がありましたが、だけれども、みずほ銀行の定期預金が５９億円されているわけですけれども、その点で、ちょっとどうなのかなという疑問があったものですから。","respondent":"小野（弘）副収入役","answer":"要注意領域には入ってございません。","voiceIndex":83,"id":"exchange-026"},{"speaker":"中島委員","kind":"質問","question":"その場合、ＢＢＢということで、要注意に入ってないとなると、優良領域になるのかなというふうに判断するしかないと思うんですが、現実に、いろいろな問題が起きていまして、かなり補償問題とか、損害が出てくると思うんです。そうしたときに、とても心配なものですから、ちょっと質問させていただきました。その辺のところをお含みおきいただければ、結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-027"},{"speaker":"宮崎委員","kind":"質問","question":"すみません、１点ちょっと、資料の５のところの国債というのは何ですか。","respondent":"小野（弘）副収入役","answer":"日本国債です。","voiceIndex":86,"id":"exchange-028"},{"speaker":"宮崎委員","kind":"質問","question":"わかりました。通常、国債と書くと日本国債ということなんですか。","respondent":"小野（弘）副収入役","answer":"通常、国債というと日本国債ととらえております。","voiceIndex":88,"id":"exchange-029"},{"speaker":"林（宏）委員","kind":"確認","question":"確認をしていきますけれども、まずペイオフというのは何なのかということを聞きますけれども、１,０００万円プラス利息だけですか。基本的な考え方は理解しています。","respondent":"小野（弘）副収入役","answer":"一応、保証されるのは１,０００万円とその利子までですけれども、その精算の後に残務金があれば、それはまたプラスで預金者に戻すということです。","voiceIndex":91,"id":"exchange-030"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"民間の人が入って、さっきの話のＢＢＢがどこですかというような話が出てくるわけで、その辺は、どうとらえるかということ。さっき、品川文化振興事業団で、あいまいだから買った、だから悪いんだという話があったけれども、そうではなくて、寄附行為に沿って外国債を買いつけなかったということで、明らかに寄附行為違反であるということを認識をしておいていただきたいけれども、それを確認しておきます。","respondent":"小野（弘）副収入役","answer":"その収集のデータに基づいて、先ほどの金融調査会、格付機関の格付けをしている方、それから、公認会計士等に、その財務状況の調査を一緒にお願いをして、状況を把握するということで考えてあります。","voiceIndex":93,"id":"exchange-031"},{"speaker":"林（宏）委員","kind":"質問","question":"区が判断することが絶対ならいいですよ。シフトして、連動しちゃって、残っちゃったら、そのときにはどうするのということになる。区の持っている情報とか、判断が１００％なら、それはそれでもちろんしなきゃいけないけれども、そうじゃない場合があるわけですよね。それで、２ページの上から４行目に、「品川区資金運用基準」というのがあるんですけれども、これはもうつくられているんですか。","respondent":"小野（弘）副収入役","answer":"はい、基準についてはできてあります。ここの中にかなり具体的なことが書いてありますので、こちらについては、一応、内部のものということで、外には出さないという形の取り扱いをしています。","voiceIndex":97,"id":"exchange-032"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、この基準というのを見ると、個々の金融機関のランクづけであるとか、そういうものが入って、もちろんそれ以外のいろいろな情報の中でランクづけがされているということなんですか。基準だから、いわゆるスタンダードじゃなくて、いろいろなケースの、個の金融機関が入っているというものなんですか。","respondent":"小野（弘）副収入役","answer":"個々の金融機関については入ってございません。取り扱いの部分の優良領域、それから、その他、領域の決め方、それからプラスアルファの部分、そういったものを盛り込んです。","voiceIndex":99,"id":"exchange-033"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、４ページの図をつくる上での基準と考えておけばいいんですか。","respondent":"小野（弘）副収入役","answer":"はい、そういうことです。それに、もう少しプラス、例えば延納金の限度額とか、そういったものも定めてあります。","voiceIndex":101,"id":"exchange-034"},{"speaker":"林（宏）委員","kind":"確認","question":"そうすると、この図の見方をもう一度確認するんですけれども、横軸に、一番上に自己資本比率と書いてありますね、左端に、監視指標と格付け。横軸に、優良領域、適格領域、要注意領域とあるのは、自己資本比率で判断してますよと。縦軸に、預託安全水準と、要注意水準と２種類あって、それについては、監視指標、格付けが重要なポイントになっていますと、そういう見方でこの表を見ていけばいいんですか。","respondent":"小野（弘）副収入役","answer":"そういうことです。格付けがないところがありますので、そういったところに関しては、監視指標という形で、危険領域なりを判断するです。","voiceIndex":103,"id":"exchange-035"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、今の話は後にしようと思ったんですけれども、格付けのないところも、しっかり基準づくりができている。だったら、格付けは要らないんじゃないですか。。さっきも言ったけど、格付けする会社の格付けというのを取ったらマイナスＣなんていうところだって出てくる。そうすると、格付けは除いちゃったほうがいいんじゃないんですかということです。格付けがないところを決めていくんでしょ、区は。","respondent":"小野（弘）副収入役、中尾根企画部長","answer":"決めていきます。それだけに、やっぱりその存在価値といいますか、格付けの意味というものはあるというふうに、私ども受け取っております。ただ、それが絶対かというと、それは当然絶対ではありません。","voiceIndex":105,"id":"exchange-036"},{"speaker":"林（宏）委員","kind":"質問","question":"３ページにある債券購入についてで、証券会社から買うということになっていくわけですね、大体。その証券会社のランクづけというか、そういうものはされるんですか。そうなってくると、証券会社の目安としては、証券会社のランクづけも必要になると思うんですけれども、やるんですか。","respondent":"市岡企画財政課長","answer":"そういう意味では、証券会社の信用性そのものが、取り引き慣行上問題がある会社があれば別ですけれども、一応、上場会社のしっかりしたところであれば、国債購入のときには等しく同じ条件で、あとは価格で差をつけていくです。","voiceIndex":108,"id":"exchange-037"},{"speaker":"林（宏）委員","kind":"質問","question":"証券会社の場合は、預金を預けるのとちょっと違うんで。最後に、万が一のときに、１ページに、金融危機対応会議というのを開かれる書いてあるんですけれども、それに区がどう対応していくということですよね。これはだれが判断していくんですか。","respondent":"中尾根企画部長","answer":"金融危機対応会議ですけれども、これは国の開くということで、内閣に新設された会議です。したがって、そこに出るメンバーを見ますと、首相、官房長官、金融庁担当省、金融庁長官、それから財務省、日銀総裁というメンバーでやるということです。","voiceIndex":110,"id":"exchange-038"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"要望だけしておきます。非常に、日々、金融情勢というのは変わるわけですね。区の場合には、外国のことを全部が全部知るあれもないんですけれども、金融業界というのは２４時間動いているわけです。金融という問題をを取り上げていくと、そういうことも視野に入れておく。そういうことも考えながら、十分な対策をとっていただきたいということをお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":112,"id":"exchange-039"},{"speaker":"三上委員","kind":"確認","question":"そういったところは、やっぱりきちっと考えて、選任ということはやっておかなきゃならない。そこらあたりの見極めというのを、どういうふうに考えて選任されていくのか、そこのところをちょっとお伺いいたします。","respondent":"小野（弘）副収入役","answer":"ただ、品川区金融機関調査会は、区の公金についての最終決定をする機関ではございませんので、区として判断をするですので、こういった場合におきましても、区が判断できると考えています。","voiceIndex":113,"id":"exchange-040"},{"speaker":"三上委員","kind":"質問","question":"最終的には、区がやるのは当たり前のことです。だけど、その人たちの意見を聞かなくても区が決定できるというと、必要ない調査会になるわけでしょ。そのために調査会というのがある、区の判断だけじゃなくて、専門家として、いわゆる公認会計士だとか、弁護士だとか。ということになれば、その意見を聞くということをやらない限り、区は決定できない話になると思うんですけど、どうなんですか。","respondent":"中尾根企画部長","answer":"委員ですけれども、今、三上委員がおっしゃったように、少なくとも出発時点では、それを確認しておりまして、ダブっていることはありません。","voiceIndex":115,"id":"exchange-041"},{"speaker":"三上委員","kind":"質問・要望","question":"そこのところは、やはりきちっと念頭に置いて、次に呼びかけがあったんだということは速やかに区のほうにも当人から報告もしてもらうということは当たり前のこととして、仮に重なって二つも、三つもかけ持ちでなんていうようなことにならないように、しっかりとやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":117,"id":"exchange-042"},{"speaker":"田中委員","kind":"質問・要望","question":"これは全般的なことに対してなんで、いいのかもしれませんが、特に指定金融機関こそ、区に対する与える影響が大きいということも含めて、毎月、この情報を得るように努力すべきだと、前回は要望として述べさせていただいたんですが、指定金融機関も同様に、３カ月ごと情報提供ということになるんでしょうか。","respondent":"小野（弘）副収入役","answer":"現在のところ、そのようになってありますけれども、指定金融機関とはかなり密接な連携を持ってありますので、今のご意見を踏まえまして、毎月というような形で要望してまいりたいと思います。","voiceIndex":118,"id":"exchange-043"},{"speaker":"田中委員","kind":"質問","question":"逆の質問なんですが、指定金融機関に指定したがゆえにリスクが出るということもある得るんでしょうか。例えば、区に対する振り込みをストップするだとか、指定金融機関がゆえにリスクを負ってしまうということは出てくるんでしょうか。","respondent":"小野（弘）副収入役、中尾根企画部長","answer":"それはそれなりの手続があって、きちんとブリッジバンクに継承して、その間、２年間なりという形での手続を行うと思いますので、そのように考えてあります。歳計現金というのは、日常に毎日入ってきますよね。これがやっぱり、多いときには何百億円と抱えるわけですから、危ないからこれをどうするかというのは、やっぱり非常に難しい問題が現実的には出るだろうなと考えています。","voiceIndex":120,"id":"exchange-044"},{"speaker":"田中委員","kind":"質問・要望","question":"これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":123,"id":"exchange-045"},{"speaker":"塚本委員","kind":"質問","question":"銀行の不具合は困ったことですけれども、先ほどのところでの関連でお聞きしますけれども、指定銀行の関係で、東京都の縁で富士銀行なんですけれども、全国的には、どういう関係、関連地域でほかの銀行が強いんでしょうか。今、こういう時期ですから、そういうことをちゃんと調べておいて、いざとなったらということも、指定されているところにもメッセージを出さなきゃいけないと思うんです。","respondent":"小野（弘）副収入役","answer":"指定銀行については、１行のみということで決まってあります。","voiceIndex":130,"id":"exchange-046"},{"speaker":"塚本委員","kind":"質問","question":"品川区独自で勉強しろというんじゃなくて、やはり１行体制を組んでいた人たちが、知恵を出し合って、こういう状況では変えられるんだということを向こう側にメッセージを出すことが、向こうに対して緊張感を与えるわけですし、他行もその準備を始めるわけですから、そういう習慣をつけなきゃいけないということを強く示しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":137,"id":"exchange-047"},{"speaker":"宮崎委員","kind":"提案","question":"４月１８日に、品川文化振興事業団の理事会と協議委員会があって、人事と財政運用の件について決められるという説明だったんですけれども、予算特別委員会のときに、理事長の表明がいろいろあったんですけれども、差し支えなければ、どういうふうな体制を提案されているのかというのがありましたら。","respondent":"濱野助役","answer":"まだ、理事の方や協議委員会の方にも通知を出していないという段階ですので、ここで申し上げるのは差し支えがありますので、申し上げることはできません。","voiceIndex":138,"id":"exchange-048"},{"speaker":"宮崎委員","kind":"意見","question":"理事長は辞任するということをおっしゃっていましたから、当然、理事長は交替ということになると思うんですけれども、今までは理事長、副理事長、幹事と、そこのところで区の４役が入っていたわけですよね。その辺のところは変わってくるということになりますか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":140,"id":"exchange-049"},{"speaker":"宮崎委員","kind":"質問","question":"ですから、もし今の質問で答えられないようだったら、それはしようがないです。","respondent":"濱野助役","answer":"先ほど申し上げたとおりです。","voiceIndex":142,"id":"exchange-050"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"さっきさんざんペイオフ対策という議論を進めてきたわけです。もう少し、シビアに銀行をとらえていただきたいなと思います。１日に入るべきお金が入らなかった、何百億円もでしょ。それで、９日に入ったら済んだ。僕は温情派ですから、非情な言葉は言いたくありませんけれども、もう少しやっぱりその辺、今回のことはシビアにとらえるべきだと思いますけれども、いかがですか。","respondent":"小野（弘）副収入役","answer":"すみません、説明不足で、言葉足らずで申しわけございませんでした。１日に引き落とし分を９日に納入するというのが契約上のことです。","voiceIndex":146,"id":"exchange-051"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"それだけでも大変な手間でしょう。余分に入ったからって喜んでいられないわけですよ。だから、もっとシビアに考えてください。これは、起きたことに対する対応なんですよ。ペイオフというのは、これから起きるかもしれないことに対する対応なんです。もう少しシビアに、さっき言ったように、担当をお考えいただきたいなと思いますので、再度、お考えをお聞かせください。","respondent":"中尾根企画部長","answer":"今回、指定金融機関だからいいということでしたわけではありませんし、特にペイオフ等についての危機管理でも、全く同じことが生じる、この本質だけはきちんとしておかなくちゃいけないという認識のもとにやったつもりですので、よろしくご理解をお願いしたいと思います。","voiceIndex":150,"id":"exchange-052"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1576#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":39350,"voices":152}},{"id":"h14-20020416-13","meetingId":"h14-cm04","date":"2002年4月16日","dateIso":"2002-04-16","committee":"清掃・リサイクル特別委員会","time":"午後１時０５分～午後４時００分","status":"正式会議録","sourceType":"formal","overview":"清掃・リサイクル特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を14件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"土井委員","kind":"意見","question":"今、二次電池ということでお話があったんですけれども、このところにも書かれておりますように、電池という形で使われているものの３割程度、トータルのごみの中から言ったら微々たるものということになるわけです。","respondent":"中山清掃リサイクル課長","answer":"将来的には品目が増えてくる可能性はあるんですけれども、いずれにしても、事業者に義務付けられるものというのは、現実にそれが対応できる体制がとれていないといけないということで、その辺を見合いながら指定していくということで。","voiceIndex":12,"id":"exchange-001"},{"speaker":"土井委員","kind":"質問","question":"その意味では、今後さらにその種のものに移行していくであろう、どんどん増えていくであろうということは理解するわけです。こういう役割分担をしっかりやっていかなければいけないと思いますので、今回もその意味では、ちょっと部分的であって、私にとっては不満だけれども、そういう流れですから、ぜひＰＲ等をしっかりやっていただくようにお願いを申し上げます。","respondent":"中山清掃リサイクル課長","answer":"委員がおっしゃったとおり、店舗まで持っていくのは、メーカーの義務と言いながら、一人ひとりの方に行動をしていただかないとごみの中に入ってしまうということですから、ここの周知の部分、実は清掃リサイクルに従事している職員の中から。","voiceIndex":14,"id":"exchange-002"},{"speaker":"中島委員","kind":"質問","question":"ちょっとついていてもそんなに気にしないでいるけれども、どこかにそれが大きくアピールされていれば、そうなんだなという意識を高める意味で、広報とか、ホームページでもう少しＰＲしておけば、このマークを区民の方に印象付けるようなものがあったらいいんじゃないかなと感じたんですが、どうでしょうか。","respondent":"中山清掃リサイクル課長","answer":"したがって、今回の電池だけでなくて、製品表示については、ある機会を捉えて、広報紙の中にリサイクルの専用のページも定期的に持ってありますから、その中で周知するとか、そういった全体のページ立てでない表示のことも含めた広報というのは考えていきたいと考えています。","voiceIndex":16,"id":"exchange-003"},{"speaker":"中島委員","kind":"質問","question":"この冊子が３,５００部ということですが、それ以上は増やさないということでしょうか。","respondent":"中山清掃リサイクル課長","answer":"したがって、新たにこれをつくるという考えはないんですけれども、もう少し簡易な形で、例えば地域に配る際には、薄いペーパーにまとめたものを周知するとかということは可能かと思いますので、この辺の内容を抽出して、先ほどの店舗の案内も織りまぜたような形での周知は。","voiceIndex":18,"id":"exchange-004"},{"speaker":"中島委員","kind":"意見","question":"確かにこれをいっぱい配っても、逆に今度これがごみになってしまってはいけないなと思います。ただ、いろいろな各関係の対応などでも、そういう部分のものが配られて、多くの人に周知されればいいかなと思いますので、どうぞよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":20,"id":"exchange-005"},{"speaker":"北野委員","kind":"質問","question":"身近なところで、これは手を挙げたところだというところでは、自主的なところではすごくいいんですけれども、区として場所をもっと拡大していくというんですか、結局、今、携帯でもＰＨＳでも機種変更とかで凄いんですよね。その辺についてお伺いします。","respondent":"中山清掃リサイクル課長","answer":"これはメーカー任せにできないということから、今後に入ったわけですけれども、まずはこれを十分周知して、どれだけこれがリサイクルに回っていくかも見て、それが本当に機能が十分でないというときには、これは品川区だけではなく。","voiceIndex":21,"id":"exchange-006"},{"speaker":"北野委員","kind":"質問・要望","question":"これは要望です。その後というのは、メーカーが電器店のところに荷物などを持ってきたときに、そのルートで回収して持っていくという形でいいんでしょうか。電気製品を扱っているお店は扱いやすいけれども、日常的に私たちが行きやすい買い物をするところ、食品とか、いろいろなものを買う部分では、結構難しいということになってしまうのか、そこのところをお伺いします。","respondent":"中山清掃リサイクル課長","answer":"そういうことで複合的な団体をつくることによってスケールメリットを出して回収をしていくという仕組みになっておりますので、基本的には我が国のメンバーはこの中に集約されていっているですから、一言で言えば、メーカー負担でやっておるということです。","voiceIndex":23,"id":"exchange-007"},{"speaker":"北野委員","kind":"質問・要望","question":"委員の方からも同じお話が出ていると思うんですけれども、ＰＲが本当に必要じゃないかなと思います。私たち自身もそういう意識を持っていかなければいけないのかなと思います。ですから、ごみ減量推進委員の方も含めてＰＲを進めていくということでしたので、地域にいらっしゃるということでは、網羅されるということでは、ぜひ進めていっていただきたいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問","question":"だから、一次電池と二次電池の違いというのが私自体ちょっと認識がなくて、電池というのは全部回収してほしいなと。だから、全体的に何とか回収できたらいいなと思ったのと、一次電池というのは、とりあえず品川区は不燃ごみで出していいということで、水銀も使われていないということですけれども、実際にこれが埋め立てに行った場合に、環境を汚染するような物質は含まれていないんでしょうか。","respondent":"中山清掃リサイクル課長","answer":"その段階でできるだけ金属関係を封じ込めをしているというふうなやり方をとっております。この辺はもう少し区民の方に周知をすべきではないかというようなご指摘であったので、これも機会を見て、その辺の仕組みをご説明していきたいと考えています。","voiceIndex":26,"id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問・要望","question":"埋め立てて、有害な重金属はないということでございましたけれども、焼却の段階での有害物の発生とか、その辺をお聞きしたい。ちょっと把握していないんですけれども、自治体によって電池を回収しているところがありますね。そこの回収の中身とか、処理の方法がもし分かったら教えていただきたいと思います。","respondent":"中山清掃リサイクル課長","answer":"ただ、今後、２３区のすべての工場は、さらに新しい法規制の基準をクリアできるように、大田第２工場においても、さらに排ガスの硝煙装置等をレベルアップさせるという工事も考えておりますが。","voiceIndex":28,"id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私自身も意識があまりなかったということでは、まず啓発のところから始まると思うし、いろいろな処理の仕方も、大勢の方の意見が聞ければ、また新しい道も開けるのではないかなと思うので、いろいろなところで検討をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-011"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"この冊子は確かに見やすいし、漫画などを入れて分かりやすいと思います。この冊子は２３区清掃協議会でつくっていただいている、この経費の負担という面では、区のほうでは負担をしているのか、それとも清掃協議会の約４,０００万円の中でこれを組んでやっていただいているのか、４,０００万円といっても、当然品川区の負担金があるわけですけれども、その辺はどっちが払われているのですか。","respondent":"中山清掃リサイクル課長","answer":"年度当初の中で、電池のリサイクルの関係というのは事業として織り込んでなかったんですが、先ほど申し上げたように、法ができていながら、なかなか理解されていないという話が２３区の中で出まして、協議会で支出するというのは。","voiceIndex":31,"id":"exchange-012"},{"speaker":"鈴木（真）副委員長","kind":"質問・要望","question":"念のため、区でなくて、協議会のほうですから、総予算はわからないと思うんですが、総予算としての単価的なものが分かれば教えていただきたいと思います。","respondent":"中山清掃リサイクル課長","answer":"申し訳ございません、総単価は今把握してございませんけれども、約９万部ということで、１部当たり１００円前後のところかなと思います。数十円というところじゃないかと思います。","voiceIndex":33,"id":"exchange-013"},{"speaker":"土井委員","kind":"意見","question":"これから個別収集等、ますます中延等をはじめとする、狭隘な道路の、２項道路みたいなところを通らないことには集められないということになりますから、軽自動車の車両が相当増えるんじゃないかと私はもともと思っていたので、それをどこかでやらなければいけないなという気がしました。ぜひこれからこの種のものを、近隣の皆さんのご理解を末永く得られるように、よろしくお願いをしておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":39,"id":"exchange-014"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5660#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=13&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":13248,"voices":41}},{"id":"h14-20020416-16","meetingId":"h14-cm04","date":"2002年4月16日","dateIso":"2002-04-16","committee":"街づくり特別委員会","time":"午後１時０７分～午後２時４９分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"上山委員","kind":"質問","question":"今回、右からしますと、ここら辺は外れていますよね。この辺の違いですか、今のご説明ですと、例えばですけれども、ソニーなどで言うと、はっきりしないという言葉はいいかどうかわからないんですが、色がかかっているので比較すると、あれっ、どうしたのかなという意味は、そこら辺どんな感じなんでしょうか。","respondent":"南雲都市開発課長","answer":"明電舎、ソニーというのは法人でございまして、基本的に開発するという行為については固まっているんですけれども、南地区の場合は、権利者の方が今７割ぐらいという感じの状況ですので、もう少し権利者の意向が固まった段階で整備計画をしようということで。","voiceIndex":15,"id":"exchange-001"},{"speaker":"上山委員","kind":"質問・要望","question":"二、三お尋ねしたいんですが、２ページにはかなりきれいな分布の絵も出ておるんですが、駅前広場の関係ですけれども、交通広場という名前で、今の大崎駅のイメージといいますか、あの近辺の感じからすると、もちろん開発の流れですから、大きく変わる部分もあるかと思うんですが、自由通路のあたりに出して、あそこから都市計画をつくるようなイメージかと思うんですが、位置的に見ると、先へでなくて。","respondent":"南雲都市開発課長","answer":"中地区の面積ですが、今後、事業を進めていく中で変更になる部分があるんですが、現在のところの計画としまして、延べ床面積で言いますと約９万４,０００m2、これは建築基準法上の容積に関係する面積としますと８万２００m2です。","voiceIndex":17,"id":"exchange-002"},{"speaker":"上山委員","kind":"質問","question":"予算特別委員会でお尋ねした人もあったんですが、そんなに変わっていないと思いますから。中地区については、こういう指定区域を決めて、事業を進めるとなってくると思うんですが、例えば業務棟などは特にかからないと思うんですが、保留床の問題で何度か質問をしたことがあったかと思うんですけれども、保留床の買い手などが決まったのかどうか、そこら辺をお尋ねしたいと思います。","respondent":"南雲都市開発課長","answer":"今回、都市計画のスケジュールが具体的になりまして、着工までのスケジュールが延びるようになってきましたので、スケジュールがはっきりしないと、買い手のほうも最終的な決断ができないという状況がありますので、今回、この都市計画の手続が具体的に動き出してきますので。","voiceIndex":19,"id":"exchange-003"},{"speaker":"上山委員","kind":"質問・要望","question":"これは要望だけにしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-004"},{"speaker":"宮崎委員","kind":"意見","question":"ここのところは具体的な中身はこれからだと思うんですけれども、平成１７年ぐらいの着工のようなお話だったんですけれども、実際はまだ絵になっていないんですけれども、どういう構想といいますか、お話しできる範囲でお願いいたします。","respondent":"南雲都市開発課長","answer":"建物の配置ですとか、機能といいますのは、いろいろなパターンを検討している段階で、まだ確定しておりません。ただ、基本的には機能としましては業務と住宅が中心になりまして、さらに保留床を対象にした商業施設が中心になるです。いろいろなパターンを検討しております。","voiceIndex":31,"id":"exchange-005"},{"speaker":"川西委員","kind":"質問","question":"今の続きになりますけれども、隣が第二日野小で、区立一貫校の計画が同時並行で進んでいく時期になりますけれども、その辺との連携はどこの機関で今後行うのか。準備組合と、区の所管課との関係はどういうふうになるのか、教えてください。","respondent":"南雲都市開発課長","answer":"今回の２棟ですけれども、再開発につきましても、再開発の都市計画で、それから空地を確保したいということで、こちらの土地開発課のほうでそういう調整を行いますので、隣接します第二日野小の計画につきましても。","voiceIndex":33,"id":"exchange-006"},{"speaker":"川西委員","kind":"質問","question":"そうしますと、平成１７年度を一応目途に置きますと、平成１４年度は準備組合を設立したばかりで準備段階ということになりますと、具体的な都市計画は平成１５年ぐらいにはでき上がってくるかなというふうには思いますが、そんな感じでいいでしょうか。","respondent":"南雲都市開発課長","answer":"これから協議ですので、はっきりしませんけれども、スムーズにいったとして、平成１５年度中ぐらいにはこの二丁目第２地区の都市計画設計ができるというふうに考えております。","voiceIndex":35,"id":"exchange-007"},{"speaker":"上山委員","kind":"意見","question":"自由通路の係わりがちょっとわからないんですけれども、大崎駅東口の駐輪場をつくっているところに階段がありましたね。あそこを最近取り払ったようですけれども、エレベーターを付けるというような話をされたのか、ちょっとそこのところをお願いします。","respondent":"南雲都市開発課長","answer":"これにつきましては、東口の地下化の部分で、前は階段があったところが、今は除去されておりますが、道路から西側の敷地の中にエレベーターと階段を設置するということで、現在その工事中です。","voiceIndex":44,"id":"exchange-008"},{"speaker":"川西委員","kind":"質問","question":"今工事を、新大崎勧業ビルディングというのを見ているんですけれども、この図面の見方としては、山手通りはどこからどこで、山手通りのほうから、跨線橋といいますか、自由通路にどういうように入るのですか。ちょっと説明をお願いいたします。","respondent":"南雲都市開発課長","answer":"この図面で言いますと、下のほうに新大崎勧業ビルディングというのがありますが、これが今のニューシテイでございまして、この上のほうの部分がありますので……。","voiceIndex":46,"id":"exchange-009"},{"speaker":"川西委員","kind":"意見","question":"簡単に言いますと、いわゆるニューシテイ側から自由通路を使う人には１本線でとても具合がいいけれども、山手通りから上がる人は階段か、ニューシテイ側のほうに行って、エレベーターに入るか、今あるエレベーターに乗って、上へ１回入って、こちらに渡るということですね。","respondent":"南雲都市開発課長","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":52,"id":"exchange-010"},{"speaker":"宮崎委員","kind":"質問","question":"この提言の中身というよりも、「はじめに」の最後のところで、「本区はもとより関係行政機関等に対し提言する」と書いてあるんですけれども、具体的に、例えばこれをまとめたら、こういうふうに提出したいとか、こういうふうな動きをしたいとかというのがあったら、お伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-011"},{"speaker":"石田委員","kind":"質問・要望","question":"４ページに、［地区計画制度・防災街区整備地区計画］というのがあるんですが、1)で、「地区計画を定めていくためには、地権者等の全員合意に相当するものが求められるので、より多くの合意を得るための」というところですが、これも我々が委員会で提唱していくとなると、議長、所管課に働かけをするという、もちろん行政の方々も受けて、いろいろな行動をしていくということになっていくと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-012"},{"speaker":"宮崎委員","kind":"質問","question":"だから、ここは、そういう意味では「全員合意」というところが、今のような表現ということになると、そこのところがかなり質的に変わってくるような気がするものですから、今の「全員合意」の内容でまとめていっていただくのがいいんじゃないかなと思います。今回は、こういう立場で「全員合意」としたほうがいいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-013"},{"speaker":"藤田委員","kind":"質問","question":"全員合意に向けての努力は必要不可欠なんですけれども、それぞれの考え方がありますので、全員合意とすると足かせになってしまうなというふうに感じています。ですから、この文面をもうちょっと不安のないように変えたほうがいいんじゃないかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-014"},{"speaker":"本田委員","kind":"質問","question":"会派の意見を出したときは、全員合意を基本としています。それに向けて努力をするということを合同会派としては出しているんです。そういう意味で、文章上の表現としていただいた。そういう意味では、私は文章上は矛盾しないと思っているんです。それはこれまでの議論を通じて出てきたことですから、私はこの文章で、含みを持たせた文章になっていていいなと受け止めているんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-015"},{"speaker":"藤田委員","kind":"質問","question":"６ページなんですけれども、「地区計画を進めるにあたり基準緩和等のメニューを増やす等合意しやすい制度にする」というふうにすれば、もっとストンといくんじゃないでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-016"},{"speaker":"藤田委員","kind":"質問・要望","question":"４ページの1)は、「全員合意に相当するものが求められるので」を切って、「地区計画を定めていくためには、地権者等のより多くの合意を得るための新たな方策と計画決定のための基準が必要である」と。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-017"},{"speaker":"宮崎委員","kind":"意見","question":"私も同じ意見になってしまうと思うんですけれども、これを進めるにあたり、軸足をどこに置くかという問題だと思うんです。どういう姿勢を持っていくのかということの問題だと思うので、私はちょっとこだわるんですけれども、「全員合意」というのを目指していくと。具体的な部分はいろいろあるにしても、この文言というのは、私としてはこだわるんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":71,"id":"exchange-018"},{"speaker":"藤田委員","kind":"質問","question":"そうすると文面の辻褄が合わなくなってしまうんですよ。一方では全員合意なんだけれども、一方ではより多くで、文面がちぐはぐなものになってしまう。ですから、すっとしたほうがスムーズにいくんじゃないかと思っているんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-019"},{"speaker":"本田委員","kind":"質問","question":"これまでの１年間の当委員会の審議の中で、「住民合意」という主張をしたと。そういうことを強く言った、言わないというのは、それぞれ基本のものが残っているわけですので、今回これをまとめるにあたって、文章をどういうふうにするかということですから、今藤田委員が言われたことについては、それはそれで構わないというふうに思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-020"},{"speaker":"石田委員","kind":"質問・要望","question":"「地区計画を定めていくためには」でも「進めるにあたり」でも、そこはお任せいたしますが、「地権者等の住民合意が求められるので、合意を得るための新たな方策と計画決定のための基準が必要である」。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-021"},{"speaker":"本間委員","kind":"意見","question":"５ページのあたりを見ているんですけれども、言葉は非常に柔らかいというか、抽象的な文になっていますけれども、それぞれの協議会の皆さんが努力されているのに対して、さまざまな面で支援の方策を考えていくということも出ていますので、よくまとめていただいなというふうに思っております。意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":94,"id":"exchange-022"},{"speaker":"藤田委員","kind":"意見","question":"前回の委員会でも、理事者のほうから、国、東京都が真剣に密集市街地についても検討を始めているということですので、的外れとは言いませんけれども、やはり国、都が考えていることをよく見定めて、それで、しかるべき段階で関係機関にもの申すのはいいと思いますけれども、もう少し成り行きを見ていかないと、いかがなものか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":101,"id":"exchange-023"},{"speaker":"上山委員","kind":"意見","question":"街づくり特別委員会が今後どうなるかはまた別な話だと思うんですけれども、１年間かけてこういう提言をつくったわけで、例えばこれを区だけでは、ちょっとどうなのかなと思います。いずれにしても、東京都なり、国のほうに、結果がどうなるかわかりませんけれども、お伝えするというのが、特別委員会としてやるべきことではないのかなと思うんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":102,"id":"exchange-024"},{"speaker":"本田委員","kind":"質問・要望","question":"そういう意味では、率直な意見という点ではいいでしょうけれども、制度とか、法律とか、そういうものの改正を求めるような面から見た場合はどうなのか。行政サイドはどう思っていますか。","respondent":"山室住宅指導担当部長","answer":"その時期と、提言の仕方をどういうふうに伝えるのかということですが、先ほど藤田委員のほうからもありましたとおり、タイミングをどういうふうに図っていくのかということをご審議いただいて、それに沿って理事者側はご用立てといいますか。","voiceIndex":103,"id":"exchange-025"},{"speaker":"本田委員","kind":"意見","question":"当委員会として国に対して提言をということで出されたと思うので、とりあえずはこれを議長を経て、区のほうに出して、次の街づくり特別委員会の中で状況を見ながら対応したらどうかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":105,"id":"exchange-026"},{"speaker":"三上委員","kind":"質問","question":"私も、もともと考え方としては、今のご意見に賛成というか、思っていたところです。表題の「提言」という言葉そのものも、果たして適当な言葉であるのかどうか。ですから、本区はもとより、関係行政機関等にということになってくると、ある意味では変なことになりかねないというふうに思っている面もあるんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":106,"id":"exchange-027"},{"speaker":"宮崎委員","kind":"意見","question":"今、皆さん方の話を聞いておりまして、逆に、動いている自治体というか、行政が実際に理解することが必要じゃないのかなというふうに思うんです。こういうとき、これからするというときに、出すというふうに、変わることではあるというふうに思います。その中で品川区議会は品川区議会の問題意識でありますから、これは動いているときに出すということが、私はいいんじゃないかなというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":107,"id":"exchange-028"},{"speaker":"横山委員","kind":"質問","question":"さっき藤田委員が言われたように、当委員会の提言ですから、提言先がなければ意味がない。その提言先をどこにするかというと、我々は区の置かれた立場でそれをずっと審議してきているところですから、行政の中にこういったものを勉強された部分で調整してほしいということでいいんだと思うんです。ただ、このまま出すには及ばないんじゃないかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-029"},{"speaker":"本間委員","kind":"質問・要望","question":"次の段階としては、一旦それに接しながらの意見のまとめを提出していく。もう一度タイトルを考えて、提言になるとは思うんですが、ついその部分を、何回もやっているうちに、どうしても提言をやらなければいけないんじゃないかみたいなふうに、自覚している時期もあったんですけれども、素直に１年間の成果をまとめて、しかるべきときにそれぞれの関係機関に要望を伝えていく。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":109,"id":"exchange-030"},{"speaker":"川西委員","kind":"意見","question":"とりあえず委員会の１年間の活動として、区の理事者側に提言を出す。そういう後に、これはどうしても区の中では解決できない、都の問題である、国の問題であるということを、時間をかけて、今の本間委員の意見も含んでいますけれども、研究した後に、委員会活動としてはそういう意見を汲み上げようということに割り切るということがいいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":110,"id":"exchange-031"},{"speaker":"三上委員","kind":"質問","question":"今までは特別委員会で１年間ずっとまとめてきたことというのがあると思うんですけれども、その中で「提言」という言葉を使った委員会の報告書というのは今までにありますか。今までだったら、大体取りまとめ的な、そういうことで終わってきていますよね。それをこの委員会だけが「提言」という言葉でやってということでよいのか、ちょっと私は感じたものですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":113,"id":"exchange-032"},{"speaker":"宮崎委員","kind":"確認","question":"これで文言を修正していこうということで確認して、その後、提言をどういうふうに扱うかということで、今のような話だったと思うんです。この提言は提言で、仕切ったものじゃないのかなというふうに思います。扱いをどうするかで意見が違うところで、後の話の部分はというのは、ちょっと話が違うんじゃないかと思いますので、そこのところは意見を言っておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":114,"id":"exchange-033"},{"speaker":"本田委員","kind":"質問","question":"１年間の当委員会の、今日ちょっと振り返って見れば、区のほうも大変苦労しながら、防災対策、まちづくりを密集市街地の改善、整備を一生懸命やってきたという、いろいろなことを我々もつぶさに見て、そしてこうしたら、ああしたらというような議論をやってきたわけですから、提言という言葉をここで仮に使っても、三上委員が言われるように、委員会報告ということも、それはそれで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":116,"id":"exchange-034"},{"speaker":"石田委員","kind":"質問・要望","question":"そういうところの実績とか、防災生活圏、１４棟などになっているけれども、地域がちょっと違うので、具体的な地区にせっかく網がかけられて、事業をやっていることについて、ずっとその勉強をしてきたわけだから、ここにいろいろな地区をやったら、この地区もこういうふうに網がかかって、こういう事業もやっているんだよというのがないなと思っていたので、もしそういう意味であれば。","respondent":"浜脇住環境整備課長","answer":"戸越一・二丁目地区も、百反通りの数字について、ちょっとあわててやったもので、落ちてしまって、それにつきましても数字を把握いたしましたので、実績の右のほうに、例えば公園・広場３カ所と書いてあるだけで、平米数が書いてないんですが。","voiceIndex":120,"id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6228#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":24004,"voices":125}},{"id":"h14-20020417-14","meetingId":"h14-cm04","date":"2002年4月17日","dateIso":"2002-04-17","committee":"行財政改革特別委員会","time":"午後１時０５分～午後２時４０分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"桜井委員","kind":"質問","question":"単独の会派からの、字句はこれで内容を一任したことですから、あえてですけれども、文章が「なお」から「意見が出された」までの全部を一つでずっと書いてあるんですね。途中で、できれば……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-001"},{"speaker":"桜井委員","kind":"質問","question":"願わくばお願いしたいと思っているのは、ちょっと文章を入れかえるんですけれども、例えばちょっと読んでみますと、「なお、単独会派から、「評価基準は、社会的弱者の立場にたち、住民の生存権を守ることを基本とし、」ここの次の行の「公的責任を明確にされたい」というのを一つ目にして、二つ目にはこの「必要性」から入るんですけれども「必要性、代替性、経済性・効率性、公平性は。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-002"},{"speaker":"桜井委員","kind":"意見","question":"ちょっと入れかえのところだけ申し上げますと、２ページのほうの「を」からいいます。「を守ることを基本姿勢とし、」その２行目の「公的責任」とありますね。「公的責任を明確にされたい。もう一遍言いますと、２番目のところ、「必要性、代替性、経済性・効率性、公平性は、コストよりも住民の必要性に対応しているかを優先基準とされたい」というふうに整理したらいかがなものかということなんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":20,"id":"exchange-003"},{"speaker":"鶴委員","kind":"質問","question":"これは、ここに書いてあるのは、単独の会派からという原案の段階で共産党からお出しになった文言をそのまま挿入して、尊重してお入れになったものじゃないですか。要するに一貫性がなかったと。直せ、直せなんて言っていて、直さないという場合には一歩も譲らないという場合もあるし、譲ってほしいという場合もあるから。だから、どうしてそういうふうにしてほしいのかということの説明がないと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-004"},{"speaker":"桜井委員","kind":"質問","question":"では説明します。それで、一つ一つ６行ぐらいの文章だったんですよね。６行ぐらいの文章だったんです。それをまとめていただいたんです。趣旨は非常に私も、お願いした、一任したわけですからいいですけれども、こういった文章になってくると何か一つの言葉として長いから、そういうふうにしたらどうかという、そういう意味です。最初の文章、お出しした文章そのものと比べてもらえばわかります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-005"},{"speaker":"松澤委員","kind":"質問","question":"私は載せなくていいという主義だったんですが、皆さん、委員長の計らいで載せることになりましたので、載せることになった以上はここのまとめた中でこういうふうにしたいという形、それは尊重してもいいんじゃないですかね。変えればいいということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-006"},{"speaker":"佐藤委員","kind":"質問","question":"正副委員長に取りまとめ、文章を一任したわけですよね。僕はいつも不思議で仕方ないのは、桜井委員の会派の委員が副委員長で入っておられるわけですよね。であるならば、当然菊地副委員長は、これを了解した上で出されているわけでしょうから、桜井委員の思いはよくわかりますけれども、やはり会派としては副委員長が目を通して行財政改革正副委員長がこれで了解していただければ一番いい形だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-007"},{"speaker":"桜井委員","kind":"提案","question":"だから、正副に一任しているわけですから、今も申し上げたように、別にこれで皆さんが絶対一字一句だめだとなれば、それはそれで今のお話は佐藤委員の言われたとおりだと思います。それで、副委員長も出ていますから、これの提案に私がそこで言うことは、筋からすればちょっといかがなものかというのはあるかもしれません。そういう正式に、さっき事務局には申し上げて、急だったものですから。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":27,"id":"exchange-008"},{"speaker":"桜井委員","kind":"質問","question":"例えばですね、今お話のあった青少年健全育成事業で、確かにこの議会でもそれは議論はしたんですけれども、こういう当初の評価の仕方あるいは説明の仕方が区民から見てどうなのかという、そういうところでの観点だったと思うんですけど、それは企画サイドの判断として、こういう事業成果活動というものを入れたんでしょうか。この計算式で４２３万というのが出たんでしょうか。それを教えてください。","respondent":"榎本行財政改革担当課長","answer":"行政水準がどういうレベルかという形で、確かに指標のとり方として教育水準ですとか、公園がどれぐらいの水準かというのはありますけれども、その辺の水準の比べ方というのは、逆に言うと自治体ランキング的な比べ方の一つの手法として考えられるわけですけれども。","voiceIndex":35,"id":"exchange-009"},{"speaker":"桜井委員","kind":"質問","question":"先に質問したような、ちょっとそういう趣旨で私は申し上げたのではないんですけれども、そういう趣旨というのは、この選び方の問題ではなくて、この最初に１月でしたか、２月でしたか、コストをいただいたのがありますよね。事業成果状況で。もう一つは、そのさっきの大崎なんですけれども、４２３万でいくと、さっき言ったコストの、これは教えてください。このコスト計算にした場合にはどういうことですか。","respondent":"榎本行財政改革担当課長","answer":"それで、この資料のまとめのときには、そのうちの事業成果指標ということで、各地区の中学生の参画した事業ということで、８事業というのを所管のセンターとしてのあらわす事業としてはこういう指標をとりたいということであったんですけれども。","voiceIndex":37,"id":"exchange-010"},{"speaker":"桜井委員","kind":"確認","question":"これで終わります。ということは、皆さんへのお手元には、この事業成果状況というのは別枠にあるという理解で、委員会に出されたのは事業成果指標のほうだという理解でいいわけですか。この成果指標だけで、コストになってくると非常にわかりにくいという点では、それは理解できます。最後にそのコストのことだけちょっと確認をしたいんですけれども、移転支出的コストというお話がありましたね。ここで。","respondent":"市岡企画財政課長","answer":"正しくという意味は漏らしてはいけないということ、フルコストで今まで目に見えない、例えば減価償却費のような建物を建てるときだけに計上していたようなコストは、これはかかっていることは計上していたけれども、実際のサービスとの関係で。","voiceIndex":39,"id":"exchange-011"},{"speaker":"辻副委員長","kind":"質問・要望","question":"これは、今の関連で、ここに書いてあるコストについての定義というのは、これは総務省とかそっちのほうの引き写しなんですか。だから、今言った温度を１度上げるとかあるじゃないですか。まさしくそういうような事業をながめるときに、あらゆる日常生活の中で見たときに、どの加点が入るのかというのは私は大きな事業評価になるんではないかなと思うんですけれども、その辺はいかがでしょうか。","respondent":"榎本行財政改革担当課長","answer":"挑戦加点評価の環境への影響ですけれども、去年１３年度を実施した段階でまだＩＳＯの取得段階の途中ということで、一応挑戦加点評価をつけた事業は４５事業ほどつけてあります。","voiceIndex":42,"id":"exchange-012"},{"speaker":"田中委員","kind":"質問・要望","question":"ほぼ同趣旨のことなので、簡潔にお尋ねいたしますが、我々の要望として、それぞれの評価を区民の方に理解しやすい意味でということで、数字をぜひ知らせていただきたいということなんですが、やはり数字をどのチャンネルにどの数字を使うかによって、そのとらえ方が違うというので、ぜひ細心の注意を払っていただきたいと思っているんですが、それから、今までは仕組みのことを中心にきたので。","respondent":"榎本行財政改革担当課長","answer":"もちろん委員ご指摘のように、その辺は十分気をつけなきゃいけない点なんですけれども、拡大する事業というその意味が、必ずしも事業が拡大なのか、それとも重点的に実施すべきなのかとか、その辺の意味合いもちょっと不明確になっているところですけれども。","voiceIndex":44,"id":"exchange-013"},{"speaker":"田中委員","kind":"意見","question":"ぜひ、それはお願いしたいと思います。一方、新年の名刺交換会は５０％の参加率でＢだと。何でというような、単純なそういう、根底にある評価は我々は知っていますから、ちょっと普通はわかるんですが、区民の方が目にする数字だけでは、また誤解を招くような理解をされてしまう可能性もあると思いますので、ぜひご検討をお願いしたいと思います。","respondent":"中尾根企画部長","answer":"いろいろ委員の方々の意見をお聞きし、発表する段階の中で修正できるものはしたいということですが、ただやってみて、さっき言った非常に難しいというのはちょっと一言どうしても言っておきたいなというところがあります。","voiceIndex":46,"id":"exchange-014"},{"speaker":"金高委員","kind":"質問・要望","question":"１点ちょっと教えていただきたいんですけれども、行政コスト計算書の中に１から４までそれぞれ各コストというのがありますけれども、１番、２番、３番まではそれぞれわかります。このその他のコストというのは具体的にどういう事例があって。それで、その最後にその他のコストに総額１９億となっていますけれども、具体的に何を示すか、それをちょっとお知らせ願えませんか。","respondent":"市岡企画財政課長","answer":"以上、四つぐらいなんですが、どうしてもその辺まで全部どこかに表示しようとするとなかなか複雑になるので、とりあえずこういうふうにしましたが、また財政分析の段階では、この比較のデータ等もお示しして、もう少し、特に行革委員会でのご審査に資するように。","voiceIndex":48,"id":"exchange-015"},{"speaker":"嶋委員","kind":"質問","question":"これはこの委員会のほうにお聞きしていいのかどうかわかりませんが、この２９ページの区民保養所、これは例えば暖景苑が載っているんですが、品川区の保養所が幾つかあるんですが、この自己評価では１次も２次もずっとＣで来ているんですが、こういう場合は区の方がここに泊り込んで見ていく部分と、これでいきますと、区民が利用しやすい施設を目指し、効率的な運営に努めるということで。","respondent":"榎本行財政改革担当課長","answer":"そこのところはちょっと細かなデータは手元にございませんが、暖景苑については委託で行っているということで、実際上はその委託業者に運営しているところが集客しやすいような形での運営の仕方ですとか、あとは実際上、それぞれ区立の保養所もそうなんですけれども。","voiceIndex":50,"id":"exchange-016"},{"speaker":"嶋委員","kind":"質問・要望","question":"女性ですから特に利用する方が多いので、食べることが満足をするというとある程度半分以上満足かなという評価があるんですが、そんなことのお料理の面とかあるんですが、これはやっぱり１回泊まってみないとにおいとかというのがわからないので、こういうのですと５０％というのはあるのかなと、ちょっと細かいことで恐縮なんですが、そういうところもこのところがあるようですので。","respondent":"中尾根企画部長","answer":"そのためには、逆に言うと、そういう細かなことも実は１０％、２０％の利用率にはね返るんだということも当然あるかと思います。それを含んで、今回についてはそういう認識で職員側はいるということでご理解をいただければと思います。","voiceIndex":52,"id":"exchange-017"},{"speaker":"松澤委員","kind":"質問","question":"大変コンパクトにうまくまとまって、ありがとうあります。アカウンタビリティーということで、一般区民にこれが届くまでの過程、各団体に郵送したりとかいろんなことがあるでしょうけれども、その辺をちょっと教えていただければと思います。","respondent":"榎本行財政改革担当課長","answer":"この今回の事務事業評価レポートの配付の件ですけれども、今回、この配付物は１万部作成しています。区内の各４１カ所の施設の窓口に置きまして、それぞれ各窓口でとれるような形での形式をとります。","voiceIndex":54,"id":"exchange-018"},{"speaker":"松澤委員","kind":"質問","question":"そうしますと、地域センターなんかに行けばパンフレットや何かが置いてあって、いただけますかというと自由にいただけるという形という理解でよろしいんですか。","respondent":"榎本行財政改革担当課長","answer":"窓口のほうで置いてありますので、区役所の区政資料コーナー等を含めて、窓口のほうで置いてあります。","voiceIndex":56,"id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5704#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":29155,"voices":60}},{"id":"h14-20020430-6","meetingId":"h14-cm04","date":"2002年4月30日","dateIso":"2002-04-30","committee":"区民委員会","time":"午前１０時０４分～午後４時３３分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2324#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":2074,"voices":5}},{"id":"h14-20020508-6","meetingId":"h14-cm05","date":"2002年5月8日","dateIso":"2002-05-08","committee":"区民委員会","time":"午後１時０４分～午後２時３４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を34件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"ちょっとお聞きしたいんですけれども、年２回訪問しておられるということですから、この間に何回か訪問されたんだと思います。それと、今回はこれ１件ですけれども、今の時点で、また新たにこういう事例が発生する可能性を持っているケースというのはあるのかどうか、その辺をちょっとお聞かせ願えればと思います。","respondent":"宮地区民課長","answer":"何回行っても連絡が取れないような場合は、訪問２回とかの回数に関係なく、極力行くようにしていますが、今後につきましては、例の賃金雇用対策のための取り決めなども活用しながら、積極的に回収に努めていきたいと考えているところです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"菊地委員","kind":"意見","question":"訪問した際に、例えば、そのときに無職であるとか、どうあがいても、年間にしても、毎月の返済はその時点で不可能である場合に、例えば就職するまで待ちましょうとか、そういう対応の仕方というのがあるのかどうか、ちょっとそこだけ。","respondent":"宮地区民課長","answer":"そのほか、例えば保証人も含めて全員が自己破産とか、そういう厳しい状況のときなどは、また免除の手続を取っていただきまして、審査会の中で決定をしていただくとかということもありますので、その厳しさの状況に応じた手段が一応取れるような形にはなっているところです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"原委員","kind":"確認","question":"一つだけ確認をしたいんですけれども、これは初めてのケースですか。","respondent":"宮地区民課長","answer":"過去にも、平成１０年に一度あります。その前もあります。私が掌握しているのは、平成１０年６月２９日に、やはり区民委員会の中でご報告しました。","voiceIndex":9,"id":"exchange-003"},{"speaker":"原委員","kind":"意見","question":"そのときの状況と今回の状況とは似たようなものなのかどうかということと、それから、基本的に、例えば滞納年数が何年とか、あるいは督促が何回とか、そういうものは決まっていて、話の上でこういう形になったのかどうなのかということなんですが。","respondent":"宮地区民課長","answer":"各月の分割を引き続き行っているところです。それから、督促の状況は、最低限ということで基本的なマニュアルはあるんですが、さらに連絡がつくまで、夜間、あるいは休日等も含めまして何回でも訪問、あるいは督促電話をしています。","voiceIndex":11,"id":"exchange-004"},{"speaker":"本田委員","kind":"質問","question":"１０年間で裁判になって、和解をして、毎月５,０００円ずつ返済を行っているということですが、何度か督促とかいろいろアプローチしても、返済しなかった。それで、裁判になって和解して、今は守っていると。裁判になって初めて驚いて、毎月５,０００円ですけれども、返済すると。その辺は、何か特徴的なことがあるんですか。","respondent":"宮地区民課長","answer":"この方は２００１年７月には在宅していたので、滞納を説明して、支払うように話はしたということの履歴を繰り返しになるわけです。その中で、いよいよ踏み切らざるを得ないという形で、こういうケースが出てくるのです。","voiceIndex":17,"id":"exchange-005"},{"speaker":"本田委員","kind":"質問・要望","question":"だから、裁判で決着して取るようになったというのは、冷たさをちょっと感じますので、よほどの理由があったんだろうとは思いますけれども、制度ですから、貸し金融業とは違いますので、すぐに訴訟を起こして取り立てるというのも決していいとは思いません。あまり役所が冷たさを感じられるようなやり方はしないほうがいいと思っているんですが、その辺、要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-006"},{"speaker":"藤原委員","kind":"質問","question":"この方が返済してくれなかった一番の理由というのは何なのか。それと、平成１４年２月からということですけれども、２、３、４月というのは、実際に返済されているのでしょうか。それと、本田委員の質問に対する課長のご答弁の中で、「債権回収のプロに」というお言葉が出たんですけれども、これは具体的にどんな人なんでしょうか。","respondent":"宮地区民課長","answer":"５月に入りましたので、早速また打合せがありますので、そこで、こうした業務になじむ人を人材センターのほうから推薦していただきまして、今度は、奨学金の回収のところで協力をしていただくように、今、計画しているところです。","voiceIndex":20,"id":"exchange-007"},{"speaker":"石田副委員長","kind":"質問・要望","question":"１点だけ教えていただきたいんですが、ここの和解内容の後に、違約金２万１,０００円というのがあるんですが、これは、何かこれといってこちらから求める基準があるのか。違約金の内容というのか、どこまで求めて、どれだけこの金額に追加になっているのか。","respondent":"宮地区民課長","answer":"今、ちょっと持ってきてないんですけれども、２万１,０００円の部分がちょうど違約金に当たるところで、１０万９,０００円が、そもそも貸し付けている奨学金の元金ということになります。","voiceIndex":22,"id":"exchange-008"},{"speaker":"石田副委員長","kind":"質問","question":"後でもいいんですけれども、教えてください。例えば、延滞金利がかかるとか、いろいろありますよね、例えば、この内容証明を送った経費まで違約金として請求するのかとか、いろいろな決め事があると思うんですが、わかれば、後で教えてください。今、資料をお持ちじゃないんでしょう。","respondent":"宮地区民課長","answer":"置いてきました。","voiceIndex":24,"id":"exchange-009"}]},{"id":"topic-02","title":"４月３０日に南多摩斎場を視察に行きまして、それを受けて、臨海部広域斎場の運営","agenda":"４月３０日に南多摩斎場を視察に行きまして、それを受けて、臨海部広域斎場の運営","exchanges":[{"speaker":"原委員","kind":"意見","question":"今、ご説明いただいたんですが、ここのオープンについて、当初の説明より若干早くなっているという話もありますので、そういった予算の関係、あるいは、今度はそれに対する我々の意見をどう持って行かれるかというところの時系列的なものを含めて、ちょっとお話を聞かせてください。","respondent":"宮地区民課長","answer":"平成１６年１月は平成１５年度ですから、平成１４年度の予算編成の時期までに、一定程度の運営についての方針が固まっておりませんと、予算に反映できないということで、そういう意味からも、かなり急ピッチで検討を進めていかなければならないという状況です。","voiceIndex":39,"id":"exchange-010"},{"speaker":"原委員","kind":"質問・要望","question":"そうすると、この委員会でどの程度まで審議ができて、次の委員会にどの程度先送りというか、送らなきゃいけないかということが出てくると思うんですよ。例えば使用料、それから職員の配置もそうですし、そういったところについては、多分、次の委員会の中で討議をいただかなきゃいけないということがあると思うんですが、その辺のところも、ちょっとあわせて決めていくというか、はっきりしていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-011"},{"speaker":"本田委員","kind":"質問","question":"議論する前にベースになる話なんですけれども、基本方針は、一部事務組合に入っている他区の議会、所管でも、同じ資料で議論をすることになっているんですか。","respondent":"宮地区民課長","answer":"はい、同じ資料を、各区の議会でも検討するということです。","voiceIndex":43,"id":"exchange-012"},{"speaker":"本田委員","kind":"質問","question":"５区の中で、例えば品川区が、ＩＳＯを取るべきだという意見を、全体として議会で一致して意見を出したけれども、他のところでは、そこまではいいんじゃないかと、3)の今後の課題にしようじゃないかというようなこともあるかもしれない、そういうところに落ち着くかもしれない。そういうふうに進んでいくわけなんですか。","respondent":"宮地区民課長","answer":"５区のことですから、それぞれ意見があろうかと思いますけれども、区としては、これで出しましたが、最終的には、その意向とは違った結論が出るかもしれませんが、一応、ご意見はご意見で出していくという形に、それぞれの区でやっています。そういうおつもりで結構です。","voiceIndex":45,"id":"exchange-013"},{"speaker":"本田委員","kind":"質問","question":"それなら、きょう、限られた時間の中でできるところまで進めて、お互いに一致できるところではどんどん意見として上げたほうがいいではないのですか。残ったら、残ったで、また次の委員会でやっていけばいいんじゃないか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-014"},{"speaker":"原委員","kind":"質問","question":"それからここでの問題は、やっぱりごみの扱いですよね。それと、ＩＳＯ関係だろうと思うんですけれども、ある意味の一体化されたような形になりますので、ごみの扱い等については、各業者が持ち帰っているのが現状になっているんですから、そういった形を続けるしかない。したがって、仕出し業者は指定した形で斎場に入れてくるわけですから、そういった中での持ち帰りという話になってくるのではないか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-015"},{"speaker":"堺委員","kind":"意見","question":"とりあえず、環境について１番から５番までのみですね。１の花環については3)、うちは認めない。２、生花については2)、式場内のみ限定で認める。３、ごみの扱いについては1)、葬儀関係は葬儀業者、自販機は設置業者、他は施設で通常処分する。４のＩＳＯについては3)、今後の検討課題とする。摘要について述べられておりますので、その辺も踏まえて3)。というふうなことで落ち着きました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":53,"id":"exchange-016"},{"speaker":"菊地委員","kind":"意見","question":"共産党は、１、２、３、それから５番目の副葬品の制限のところまでは、今の公明党のご意見と同様であります。ＩＳＯにつきましては、今のごみ等の問題も含めて、取得をしていくという方向で考えていけるのではないかと考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":54,"id":"exchange-017"},{"speaker":"本田委員","kind":"質問・要望","question":"今後の課題というのもあるんですけれども、できるだけ、そういう方向で話は進めていただいて、やはり、２３区として初めてつくる斎場ですから、そういう近代的な装いをしているということで、業者の方々とも十分協議をして、協力をいただいて対応していくことを進めていただきたいと思うんです。５番では、当然、制限はするということだろうと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-018"},{"speaker":"石田副委員長","kind":"質問","question":"式場のみじゃなくて、全部を使用許可範囲内でどこでも認めるということですか。1)ですか、2)ですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-019"},{"speaker":"本田委員","kind":"質問","question":"そういう認識なんですけど、設置を認めるのと、式場内のみの限定で認めるというのは、どう違うんですか。普通、生花というのは。","respondent":"宮地区民課長","answer":"設置を認めるというのは、もう屋外も含めてなんです。外側に飾るのがありますよね、お花で。最近のやり方で、花環にかえて生花を外に出すものもありますので、そういう意味で、外ということです。式場の中のみは2)ということです。","voiceIndex":59,"id":"exchange-020"},{"speaker":"金高委員","kind":"意見","question":"生花については、やはり2)ですね。ごみについては、やはり式場関係者が業者と一体となって処分することが一番望ましいということで、1)ということで、葬儀関係者が処分する。それから、５番目の副葬品については、制限ありということで、遺族が、故人にとっていろいろな物を入れたいということはあると思いますけれども、やはり全体的な環境問題で制限したほうがいいんじゃないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":64,"id":"exchange-021"},{"speaker":"原委員","kind":"質問","question":"今、お話を聞いていると、一つずつちゃんとした明解な答えをしていかなくちゃいけないようですので、１から９まで、私たちのお話をします。寝具は有償にする。他区の場合は、ほとんど協定葬儀をしてないのが多いわけですから、一応、私たちとしては、とにかく現状の品川区でやっているものが可能かどうか持って行ってほしいということです。〔「実施するのですか」と呼ぶ者あり〕実施するです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-022"},{"speaker":"石田副委員長","kind":"質問・要望","question":"さっきの４対１の話になるかもしれないので、実施をしていただくという形で訴えていただきたいんですが、４対１ということもあって、しないという方向性であっても、品川区民の方は、せっかく、今、なぎさ会館でやっているわけですから、それは品川区独自であったとしても、組合とは別でもいいから、品川区独自の協定葬儀をやっていただきたいというのが希望であります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-023"},{"speaker":"堺委員","kind":"質問・要望","question":"５番目の仮泊については1)、６の協定葬儀については1)、これも先ほど、前段で申し上げましたように、真ん中の葬儀料の軽減ということを前提にとらえた場合に、そうなるのであるならば、ぜひそういう方向で取り組んでいただきたい。ですから、あえて、もう一言申し上げると、全く同じなんですが、組織市民についての火葬料については無料。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-024"},{"speaker":"菊地委員","kind":"質問","question":"共産党のほうですけれども、開業日については、これもいろいろ論議をしたんですけれども、桐ケ谷斎場が今後休んでいるということもありまして、せっかく行政でやるものですから、年始外は開業する方向が一番望ましいのではないかと考えます。人体の一部火葬については1)。それから、式場の備付品については1)。仮泊についても1)。協定葬儀についても1)。飲料類販売についても、同様です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-025"},{"speaker":"本田委員","kind":"質問・要望","question":"負担をできるだけ安くという考え方で、サービスのところは見たんですけれども、１番のところは、今、もう桐ケ谷斎場は１週間ぐらい待っている状況ですから、そういう点では、これまでの慣習にとらわれないやり方で、友引でも構わないという考え方が結構多いですから、そういうふうにしてもおかしな状況ではないと思いますね。１番は2)。それから、５番の仮泊は、当然認めていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-026"},{"speaker":"金高委員","kind":"質問・要望","question":"協定葬儀も、1)として、実施していただきたいと思います。そういう面では、葬儀をする家がどちらを選ぶかということが必要ですので、安い費用で行うのが一番いいわけですから、ぱっと見ても、今の葬儀費用は３００万円ぐらいかかってしまいますので、なるべく安い方法であれば、仕出しについても、相当な量が人によっては出てくると思いますから、2)、3)を適応した形での方向づけが望ましいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-027"},{"speaker":"原委員","kind":"質問・要望","question":"交通アクセスなんですけれども、これは非常に大変難しい課題で、ここに書かれている路線バスの本数を増やしたり、あるいは、いろいろな形で交渉をしなければならないと思うんですが、問題は、他区もここを利用するということになると、そこからの関連もあるわけですから、その辺の調整を十分にとられて、タクシー会社と協定をもし結べるならば、その辺の折衝もしていただき。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-028"},{"speaker":"堺委員","kind":"質問・要望","question":"基本的には、その考え方でいくべきだと考えております。３番目の売店喫茶業務についても2)。それから、１２番目の交通アクセスについては、今も原委員がタクシー会社と協議とおっしゃっておられましたけれども、この件については、前回、各委員からいろいろな意見が出ておりましたけれども、最寄りの駅からの交通アクセスについては、十分検討していただきたいと思います。そういうふうに要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-029"},{"speaker":"菊地委員","kind":"質問","question":"１番の職員配置については、これは当然、組合の中で進めていくのが大事だろうと思います。これはどちらがいいのかというのは、いろいろ私どもも論議をしたんですけれども、先日、南多摩斎場に伺ったときに、火葬業務の大変さという裏話が出ておりました。骨壺販売については、1)、2)を混ぜて、自由に考えるべきものではないかと思います。それから、６番の清掃については委託をしていく。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-030"},{"speaker":"本田委員","kind":"質問・要望","question":"夜間の受付もぜひ実施していただきたい、２４時間体制でやってもらいたい。ですから、品川区から行くのは、現状では、公共機関を使ったときには大変不便なんですね。モノレールで大井競馬場のところか、流通センターのところからになるわけですから。犯罪などが起きないことを願っておりますが、そういう場所ですから、十分安全の確保というのは検討していただきたいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-031"},{"speaker":"金高委員","kind":"質問・要望","question":"湯茶のサービスですけれども、これもやはり2)の売店業務等にあわせて委託するということです。それから、受付業務ですけれども、これは日中ですから、当然、組合のほうで行うのが望ましいのかなという感じがいたします。そういうことで、交通アクセスについては、そこに行かれる方が一番便利で安全な方法がとれるように、ぜひ、いろいろな角度から検討していただきたいです。","respondent":"南委員長","answer":"皆さんからそれぞれ意見を出していただきまして、ありがとうございました。ここは言い残したとか、こういうふうにもう１回考えたいとか、ご意見、補足がもしありましたら、出してください。","voiceIndex":82,"id":"exchange-032"},{"speaker":"原委員","kind":"質問","question":"この間も、ちょっと問題になりましたが、初七日の話です。要するにお釜の問題と、それから控室と問題等々がいろいろあって、時間が取れるか、取れないかというのを含めて考えなきゃいけない話なんだろうと思うんです。ただ、効率から考えて、この間も、それをやることによって、時間がかなり難しいという話にもなっているわけですから、その辺は十分、お考えいただければと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-033"},{"speaker":"石田副委員長","kind":"質問・要望","question":"今の段階では、白タクみたいな形で許されないと思うけれども、そういうことも含めて折衝するという考え方も持っていただきたい。ただ、法律でだめというのではなくて、そういう考え方も持てるのかどうか、法的なことも含めて調べていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-034"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2326#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":26098,"voices":96}},{"id":"h14-20020508-7","meetingId":"h14-cm05","date":"2002年5月8日","dateIso":"2002-05-08","committee":"厚生委員会","time":"午後１時６分～午後３時４８分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"船波委員","kind":"質問","question":"障害者ホームヘルプサービスについて、まずお伺いしたいと思います。「品川区の福祉」の障害者ホームヘルプ派遣事業のところを見ますと、平成１０年度から実績の数が減ってきているんですが、どうして減ってきてしまっているのでしょうか。","respondent":"日下部障害者福祉課長","answer":"これは平成１２年度から介護保険制度が導入されましたので、基本的には６５歳以上の方については介護保険のほうに移行いたしましたので、かなり対象者が急減したです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"船波委員","kind":"質問","question":"東京都の政策の見直しに伴っての変更というご報告ですけれども、２・３・４段階の方々の無料の部分を廃止するというのも、東京都がやめてしまうから仕方なくやめるということなんですか。","respondent":"日下部障害者福祉課長","answer":"東京都がやめるから仕方なくと、品川区としては必ずしもそういうことではなくて、先ほども説明の中で触れましたけれども、もともと品川区としても実施にあたっては要綱のもとに実施しております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"船波委員","kind":"質問","question":"そうしますと、週３回９時間を無料にする分の費用的な負担というのは、東京都がすべて担っているわけですか。","respondent":"日下部障害者福祉課長","answer":"ここに週３回９時間とありますけれども、実は東京都の制度では週２回６時間、これに品川区が加算をして週３回９時間まで無料ということで対応してまいりました。","voiceIndex":9,"id":"exchange-003"},{"speaker":"船波委員","kind":"質問","question":"１番に関しては、東京都が減らしても品川区が事業の重要性を認めて継続していくという考え方であるのに対して、２番の障害者ホームヘルプサービス事業は東京都が減らすから品川区も減らすという、１番と２番の考え方の違いはどこから出てくるんでしょうか。","respondent":"日下部障害者福祉課長","answer":"ただ、先ほども申し上げましたけれども、９０％の、一定の収入しかない方については、利用者負担についてはいただかない。ただ、相応の収入のある方については、収入に応じまして一定のご負担をいただくという考え方をきちんと生かしてまいりたいということです。","voiceIndex":11,"id":"exchange-004"},{"speaker":"船波委員","kind":"質問","question":"ですから、収入に応じた負担をしてもらうという考え方も一方では理解できるものの、無料を継続したところで品川区側が非常に大きな経済的な負担を強いられるわけでもないので、これぐらいだったら継続してはどうかと思うんですけれども、そういう検討はされなかったんでしょうか。","respondent":"日下部障害者福祉課長","answer":"トータルの金額でいけば、それほどではないではないかと、それは確かに１１世帯について利用実績と掛け合わせても、確かに金額としてそんなに大きいものではありませんけれども、やはり先ほども申し上げましたけれども。","voiceIndex":13,"id":"exchange-005"},{"speaker":"船波委員","kind":"質問","question":"わかりました。この方々がどれぐらいこのサービスを利用しているかお伺いしたいんですけれども、「品川区の福祉」によりますと、回数をどれぐらい利用するかは当事者の状況に応じて決定されるということですけれども、今までは無料で利用できていたものが有料になってしまうという方々の場合、その人が全体で利用している時間のうち週３回９時間というのはどれぐらいの割合のものだったんですか。","respondent":"日下部障害者福祉課長","answer":"そういうことを比べて勘案してみますと、あくまでも障害の程度に応じて派遣の時間とか回数については品川区で決めするということですけれども、必ずしも今後負担があるから利用を抑制されてしまうという結果にはなってこないのではないかと考えております。","voiceIndex":15,"id":"exchange-006"},{"speaker":"船波委員","kind":"質問","question":"１番のほうと２番の障害のある方に対するサービスですけれども、平成１５年度以降に新規制度ということになった場合、どういうふうに変化していくものなんでしょうか。","respondent":"日下部障害者福祉課長","answer":"ホームヘルプサービスというのは、支援費制度に措置制度から移行することになります。ただ、これは以前の委員会でもご説明させていただきました。","voiceIndex":17,"id":"exchange-007"},{"speaker":"船波委員","kind":"質問","question":"３番のほうですけれども、指定廃止をされてしまう二つの病気に関しては、どうして廃止されてしまうのでしょうか。","respondent":"日下部障害者福祉課長","answer":"私のほうでご説明させていただいて、もしそれ以上の話になれば、専門家のほうから補足をさせていただきたいというふうに思います。","voiceIndex":19,"id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１点目のところからお聞きしたいんですが、今度改正になるところで小規模と中規模となっているんですが、小規模と中規模の違いについて教えていただきたい。２点目の障害者ホームヘルプサービス事業についてですが、II、III、IV段階の所得階層について無料制度をなくすということなんですが、１１名でどれぐらいの予算になっているのか教えていただきたいと思います。","respondent":"日下部障害者福祉課長","answer":"人数ですけれども、全体でどのぐらいかということであたってみましたら、最大で２００世帯ぐらいいくのではないかというふうに見込んでおります。ですから、全体の３分の１ぐらい、かなりの方が対象になっております。","voiceIndex":21,"id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１番については、今までは玄関は４９万円までしか使えなかったのが、かかった分はかなり使えるということになってよかったなと思うんです。２番目についてですが、１１人で７８３万円ということなんですが、これが実際に利用者負担額が生じて、本人がこれだけ負担するとなると、品川区が少なくて済む額というのはどれぐらいになるのか、そのことについて教えていただきたい。","respondent":"日下部障害者福祉課長","answer":"ですから、これはそういう意味ではかなり負担のＩ階層も含めるとかなり低いということになります。ただ、Ｉ階層分を除くと大体１８％ぐらいの負担ということになってくるわけです。ですから、確かに介護保険の１割より若干高めにはなってまいります。","voiceIndex":23,"id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そんな中で３０４万５,０００円以上所得があると無料のホームヘルプサービスが受けられないというのは、本当に大変じゃないかなと思うんですけれども、この辺の３０４万５,０００円という考え方というか、しかも生計中心者というところではどういうふうに考えられているのでしょうか。","respondent":"日下部障害者福祉課長","answer":"そういう形で、必要な対応というのを品川区として実施をしていく責任があると思います。そこで生み出された財源も含めて、新たな福祉サービスの拡充に充てていくと、それが品川区としての基本的な考え方でありますので、その辺は十分にご理解をいただきたいと思います。","voiceIndex":25,"id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"Ｃ型肝炎にしても、輸血とか血液製剤によって感染が広がったというところで大きな問題になって、新聞紙上でも話題になっているところですけれども、そういうところでは厚生労働省がきちんとした対応をされなかったためにＣ型肝炎になって、そして慢性肝炎になって治療せざるを得ないという状況になっていると思うんですけれども、そういうところで治療がきちんと、しかも外来の中で完了していきながら。","respondent":"日下部障害者福祉課長","answer":"そういった点では、品川区としても今回の経過措置で医療費助成と手当の支給は別問題ですけれども、品川区は品川区なりに経過措置という形で、おそらくほかの区でもこの辺の実現は難しいところはあろうかと思いますが、少なくとも平成１５年３月までは現行を継続する。","voiceIndex":27,"id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう方が早期発見したら治療に結びついて、そして適正な治療をきちんと続けていくためにも、東京都の先駆けた施策がすごく大事な役割を果たしてきたんじゃないかと思うんですけれども、そういう点ではぜひ東京都に対して難病指定から外すなというところを、品川区からも言っていただきたいなという思いがするんですけれども、その点に関してはいかがでしょうか。","respondent":"日下部障害者福祉課長","answer":"これは専門の委員会の答申を受けて、そのような判断をしたということでありますので、私どもとしましてはその辺の専門的な考え方も含めて、なかなかそれについてものを申すというのは非常に難しい立場にあります。","voiceIndex":29,"id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その中で適切な治療ということに結びついていくというところで、ぜひ品川区からもそういうふうに言っていただきたいということと、あわせて認定というところはそういう形でこれからもできるということであれば、せめて医療費助成が打ち切られ、その上に手当が打ち切られといったら、本当に二重の大変さになるわけですから。","respondent":"小林品川区保健所保健サービス課長、日下部障害者福祉課長","answer":"医療費助成についての申請の経由窓口として、保健所は今まで仕事をしておりましたけれども、患者に対しての療養上の支援については、今までと何ら変わらなく対応してまいりますし。手当の関係ですけれども、先ほどから再三ご説明していますように、おそらくこういう形での経過措置というのは、２３区の中でも非常に一番手厚い形で対応する中身だと思います。","voiceIndex":31,"id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今、保健サービス課長からお話がありましたけれども、Ｃ型肝炎、慢性肝炎の通院治療の必要性というところについてはいかがでしょうか、その辺のところが一番大事なところかなと思うんですけれども、その辺について専門家としてご意見をお聞かせいただきたいと思うんです。","respondent":"小林品川区保健所保健サービス課長","answer":"もちろん治療の必要性ということについては、私どもも十分認識しております。","voiceIndex":34,"id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そしてまた、通院の中で高額なお金がかかるというところでは、それに対しての治療の医療費助成を打ち切るということは、本当に大変な事態になるなと思っているので、ぜひこのことについてはさらに実態を見ながら考えていただいて、品川区としても対応していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-016"},{"speaker":"嶋委員","kind":"質問","question":"そういう中で、所得制限もあるということでお聞きしたいのは、これを使わせていただく場合、障害の程度が進んでいく場合もありますので、特に台所は足の悪い方は車いすで、手も不自由の方もいっぱいいらっしゃいますけれども、何とか家事をやりたいという方がいらっしゃるんですが、こういう場合は限度が超えた部分はお金がかかる場合、もちろん利用者が負担をするんですが。","respondent":"日下部障害者福祉課長","answer":"私もそういうお話を今回初めて伺いましたので、その辺のやり方が、実際の制度の運用上も含めて可能なのかどうかということについては検討をさせていただきたい。できるだけ前向きにその辺が解決できればというふうに思います。","voiceIndex":37,"id":"exchange-017"},{"speaker":"嶋委員","kind":"質問・要望","question":"確かに「肝炎の希望者に関しては検査をします」というのが広報であったと思うんですが、ウイルス性という形ではどんどん増えている状況があるので、区民健診での啓発が広報紙以外にどのようにされているのか、もしわかったら教えていただきたい。それから２番目の新規難病指定の６疾病のことなんですが、６疾病がわかりましたら教えていただきたいと思います。","respondent":"田中健康課長","answer":"もともとＣ型肝炎のお話というのは、昨年の６月に当時の厚生労働省が緊急に検査をということで、保健所等でＨＩＶ検査の中に取り込みまして、昨年１０月まで実施をいたしました。","voiceIndex":39,"id":"exchange-018"},{"speaker":"嶋委員","kind":"意見","question":"これは後で勉強したいと考えています。これは患者出現率から推計して、５０名ということなんですが、これから新しくスタートするということで、これから状況がわかるということなので、これだけ新しい病気が難病指定になったということは、それだけのスピードでこういう方たちがいらっしゃるということを私たちも認識していきたいと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":41,"id":"exchange-019"},{"speaker":"須藤委員","kind":"意見","question":"１点だけお願いします。ここまで書いてあるならば、国から来ているからそれを利用するということではなくて、品川区の姿勢としてそういうことがあるならば、その辺はどうなのかなということ。それから、介護保険との兼ね合いというのはどういうふうに絡んでくるのかなと、２点お願いします。","respondent":"日下部障害者福祉課長","answer":"ただ、これ以外にも１級の方、歩行が全くできなくて、最重度の方については屋内移動設備の取り付けということで、屋内に一種のリフトみたいなものをはわせまして、そこで住宅の中を移動ができるように、これはかなり大規模なものですけれども。","voiceIndex":42,"id":"exchange-020"},{"speaker":"鶴副委員長","kind":"質問","question":"そこで、一、二点、障害者福祉サービスの改正についてお伺いをしたいのでありますけれども、給付の今回の変更にあたっては２種目に小規模、中規模というふうに改修できるようにあるんですが、給付を受けたいと思う人は事前に設計図とか、そういうものを当該課に申請して、そして当該課が職員を派遣するなり審査を行って給付の額を決定するということになるのでしょうか、そうではないのでしょうか。","respondent":"日下部障害者福祉課長","answer":"それをもとにそれぞれ利用者の方がお考えになっているような改修の内容とか、経費の問題とかいろいろ付け合わせをさせていただいて、正式にご申請をいただくという形で手続を進めていくという形になっております。","voiceIndex":44,"id":"exchange-021"},{"speaker":"鶴副委員長","kind":"質問","question":"従来、介護保険制度がスタートする前にありました高齢者等を対象にいたしました住宅改修リフォームについて、いろいろな助成制度がありました。段差解消とかお風呂の改修だとか、手すりの改修だとか、もろもろが入って上限が決められておりましたが、その比較においては遜色のあるものですか、ないものですか、詳しく説明していただけませんか。","respondent":"日下部障害者福祉課長","answer":"障害者の住宅改造についても、かなりそれなりの歴史が長い経過をたどっておりまして、高齢者の住宅改修のほうと全く同一ではありませんけれども、大体中身としましては同じような中身を基本にして制度を運用してまいりましたので。","voiceIndex":46,"id":"exchange-022"},{"speaker":"鶴副委員長","kind":"質問","question":"今回大きくわけて三つのサービスの改正につきましての当該受益者がそういう事業の対象となるであろうと思われる障害者の方々に対する説明というか、改正の徹底というのはどういう方法でなされるわけでしょうか。","respondent":"日下部障害者福祉課長","answer":"やはりこれについてはケースワーカーがそれぞれの障害者の方の状況を一番把握しておりますので、ケースワーカーがしっかりとそれぞれの方について、対象となるような方については、その辺の内容を十分に個別にも周知をしていくと。","voiceIndex":48,"id":"exchange-023"},{"speaker":"鶴副委員長","kind":"質問","question":"要するに、しかるべき措置をとっているという、他と違った施策の展開をやっているわけですから、そういうことも含めてしっかりと、広報「しながわ」にはスペースの関係があります。アンケート調査を取るということは大変ですので、ホームページに「意見があるならどんどんご意見を述べてください」というようなことを載せていたほうがいいのではないかというふうに思うんですが、いかがでしょうか。","respondent":"日下部障害者福祉課長","answer":"委員の冒頭のご指摘の中に、説明責任ということがございました。品川区としましては、確かに制度を改正するわけですから、そういった意味では議会に対しての説明をしっかりと説明責任を果たす。それと同時に、やはり区民の皆さん方に対しても説明責任をしっかりと果たすと。","voiceIndex":50,"id":"exchange-024"},{"speaker":"伊藤委員","kind":"質問・要望","question":"説明、ご苦労さまでございました。何点かになろうかと思うんですけれども、一つ大きなことで、この提言が出た後、保険者としての品川区はこのことに対してどういうふうに取り組んでいくかということの大きな方向性を教えていただきたいのが一つ。だから、これをただ提言だけに終わらせるのではなくて、何かしら品川区としてやっていく必要があるのではないでしょうかということをお聞かせください。","respondent":"新美保健高齢事業部長","answer":"もう１点目が、第１期の２年間、介護保険導入準備段階を入れて３年が過ぎまして、ケアマネジメントは品川区の場合、何とか区民の方には９割以上の方におおむねご信頼はできているかと思うんですが、今後のことを考えますと、さらに今後成熟期といいますか。","voiceIndex":56,"id":"exchange-025"},{"speaker":"伊藤委員","kind":"質問・要望","question":"実際、提供しているサービスがどうなっているかということをフィードバックするシステムが今のところないというわけですから、これはおそらく業者も初めてのことでしょうから、いろいろ戸惑いながらやられていたんでしょうけれども、それをまたフィードバックしていいサービスがつくられていく仕組みをつくっていくことのほうが、はるかにこれからの傾向となっていくと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"９ページに在宅介護支援センター別抽出結果というところで、ケアプラン作成数が出ているんですけれども、ケアマネージャー６３名のセンター別の数を教えていただきたいと思います。この報告書を見て、現場のケアマネージャーの方々が本当に大変な中で、悩みながら利用者の方との信頼関係をつくるというところで、本当に努力をしながら頑張っていて大変だなというのが実感したわけなんです。","respondent":"新美保健高齢事業部長","answer":"３点のお尋ねがあったんですが、長期基本計画の中でサービス評価につきましては、基本的なサービスについてサービス向上の仕組み、つまり手法の開発・実施ということを含めて、３年間で仕組みづくりをしようということで考えておりまして、３年目が今年度ですが。","voiceIndex":59,"id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そんな中で、ここのケアマネージャーの方々の質問項目の中で、「できている」「できていない」というのがあって、「できていない」の割合が相談時間が取れていないとか、情報収集、課題分析というところで３割とか５割を超える項目もたくさんあるわけなんですけれども、この結果に対しては品川区としてどういうふうに考えられているのかお聞かせいただきたいと思います。","respondent":"高橋介護保険担当課長、新美保健高齢事業部長","answer":"最後のケアマネージャーの研修について、福祉カレッジだけであるかという部分ですが、年が明けますとそれぞれの在宅介護支援センターに呼びかけて、新人を含めた研修を４日間ぐらいやってあります。訪問看護について、サービス評価の対象にするかどうかは、今年度が３年目で来年度以降どうするか品川区介護サービス向上委員会での検討の時期ですので、品川区介護サービス向上委員会の中で検討をしていきたい。","voiceIndex":61,"id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本当にこれだけ大変な声というのが出されて、やっぱり私も本当に大変だったなというのを改めて思ったわけですけれども、こんな中で一つは先ほど言われたように、研修や情報交換、悩み、それからカンファレンスとか、そういう形のものを充実させるというところと、やっぱり体制をきちんと取っていくということが求められているんじゃないかと思うんです。","respondent":"新美保健高齢事業部長","answer":"まさにここにつきましては、今年度介護保険事業計画の改定を含めて、第二期へ在宅も含めてどういう課題設定をしていくか、体制を敷いていくか、今年度の検討事項ですので、その中でこの提言も受けて十分ご意見もいただきながら、実態も見ながら。","voiceIndex":64,"id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこのところなんですが、ずっと民間の居宅介護支援事業者の方に対しても説明会をしてほしいということで、今年の２月にされたと思うんですが、その中でどのような民間の居宅介護支援事業者の方からの意見が出されたのかお聞かせいただきたいんですけれども。","respondent":"早津高齢福祉課長","answer":"２月に行った民間居宅事業者との話し合いですが、大きなテーマは東京都が実施した利用料軽減についてどう扱うかということを説明しつつ、いろいろなご意見をお伺いいたしました。こういった会を開催してほしいというような意見等、さまざま出ておりました。","voiceIndex":66,"id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"やはり、こういうところでは今回はケアマネジメントに関するサービス評価というところで、在宅介護支援センターだけでしたけれども、ケアマネジメントを行っているところは在宅介護支援センターだけではなくて、品川区の中では１割弱の区民が実際にケアプランをつくられている介護支援事業者があるわけですので、やはりそういうところも本当に一生懸命やっていると思いますので。","respondent":"早津高齢福祉課長","answer":"事業者の場合も、非常に少ない方もありますので、その場合に一人、二人というような方のご意見を聞いたのが、事業者の評価につながるのか、いいか悪いかというようなさまざまな問題もあります。介護サービス向上委員会の中で検討をしていきたいというふうに考えてあります。","voiceIndex":68,"id":"exchange-031"},{"speaker":"嶋委員","kind":"質問","question":"そういう意味では、いろんな意味で尊重していただく部分もあると思いますが、品川区として部課長クラスが１７在宅介護支援センターへの激励といいますか、「頑張っているね」という声とか、背中を押すというのがどのぐらいのペースで１７カ所を回っていらっしゃるのか、この１点だけお聞きをしたいと思います。","respondent":"早津高齢福祉課長","answer":"例えば、特別養護老人ホームと併設の在宅介護支援センターですと、特別養護老人ホームへ行く回数が、それ以外のところと比べると多いので、そのときに行くとかということで、在宅介護支援センターによってばらつきが出ているのは事実なんですが。","voiceIndex":70,"id":"exchange-032"},{"speaker":"須藤委員","kind":"質問","question":"平成１４年３月に答申が出されたんですけれども、答申が出された時期は介護保険制度が始まってどのくらいの期間が経ったんでしょうか。","respondent":"早津高齢福祉課長","answer":"３月ですので、約２年ということになります。","voiceIndex":72,"id":"exchange-033"},{"speaker":"須藤委員","kind":"意見","question":"去年の４月ならこの表現でいいんだけれども、１４年３月に出てきたときに、「まもなく２年を迎えよう」という表現で答申書を出してきてしまうと、ちょっとあれっという思いがあるんだけれども、カウントの仕方が私が違うのかな。","respondent":"新美保健高齢事業部長","answer":"確かに、よくご記憶をいただいております。昨年は確かに「まもなく１年を迎えよう」という形で最初のページが始まっておりました。","voiceIndex":74,"id":"exchange-034"},{"speaker":"須藤委員","kind":"質問","question":"「まもなく丸２年を迎える」とかという表現ならそれで済むけれども、「２年を迎える」というのは、「これから丸３年を迎えよう」という表現ならいいと思うんです。昨年もあったので、直るかなと思ったら直っていないので。もう１点、利用者の回答率が５８％、そのときの介護度については１１ページに載っているんだけれども、返答のない４２％の人の介護度というのはわかりますか。","respondent":"新美保健高齢事業部長","answer":"今回、抽出を全数ではなくて、全体の３分の１程度を無作為で抽出したので、介護度別にバランスを取るというのはなかなか難しくて、結果どういう要介護度かしか、ここではわかりません。","voiceIndex":76,"id":"exchange-035"},{"speaker":"須藤委員","kind":"質問・要望","question":"回答した中で１割も３割を回答していないというと、本当の回答者というのは、そのことに対しては逆に言うと３割、４割というような数値の回答しかないというふうに考えられると思うんですけれども、そうした場合と全部１００％回答しましたよという事業者、管理者、そういうところの回答者と同列に比較をして統計上の分析の仕方がいいのかどうか、その辺はいかがでしょうか。","respondent":"新美保健高齢事業部長","answer":"ただ、ここにも見ておりますように、ホームヘルプと比べまして、確かに無回答の率が１０ポイントほど全体に高くなっておりますので、ケアマネジメントといったときのわかりにくさというのが、どうしても無回答の回答が多くなる傾向は受け止めざるを得ないので。","voiceIndex":78,"id":"exchange-036"},{"speaker":"須藤委員","kind":"質問","question":"先ほど質問したのは、無回答のところが多いのが３割なんぼ、少ないのは１割ちょっとあるわけです。そうすると、５８％ぐらいの回答率で４２％は回答しないという中で、まだ無回答がありますよといったパーセンテージと、それから１００％回答してきた事業者とか管理者と比較をそのまま同一にしちゃって、統計上それがきちんと見られるのかどうか、それでこの分析を最後に書いてあるわけです。","respondent":"新美保健高齢事業部長","answer":"やはり、数も３分の１やっておりますので、６割の回収率であれば大筋の傾向を見るべきものという認識でおります。３６ページの評価も、今申し上げた程度の、ただ全体の傾向としては、どうしても同じ局面に対してケアマネージャー側が厳しく評価している。","voiceIndex":80,"id":"exchange-037"},{"speaker":"須藤委員","kind":"質問","question":"半分以下の回答率でそれを評価しちゃうというと、違った方向に走っちゃう可能性も考えられてくるので、アンケートを取るときにその辺のところも今後考慮されて、先ほど言った返事がなかったのはどういう人たちなんだという、それは介護度がきついからできなかったんだとか、いろんな状況があろうかと思うので、そういうことをきちんとつかんでいただかないと。","respondent":"新美保健高齢事業部長","answer":"今回、初めてこういう形でやりましたので、ご意見あるいは今後の状況と、また何年かに１回ずつ繰り返しやっていく形を取っていきたいと現時点では考えておりますので、そういったところにもう１回工夫をしていきたいというふうに考えます。","voiceIndex":82,"id":"exchange-038"},{"speaker":"鶴副委員長","kind":"質問・要望","question":"事業者がやるのか、あるいはやっぱり品川区が主体的となって、そういう場をつくって心の状況というか、サービスの職員としての心構えというか、つらいけれどもお年寄りのために、あるいは障害を持っている人たちのために使命と誇りを持って、困難を乗り越えてお世話することに喜びを感じていくというような、サービスを受ける側にとって安心を与えていくという。","respondent":"新美保健高齢事業部長","answer":"大変難しい課題についてのご質問ですが、ただ私どもも介護ということは、単に個々のサービスを提供すればいいというだけでは、なかなか在宅介護を全体的にサポートしていくことにはならないという認識は持っておりまして、そういう意味では今度の報告書も１ページ、２ページ。","voiceIndex":86,"id":"exchange-039"},{"speaker":"鶴副委員長","kind":"質問","question":"そこで働いている福祉職員といいましょうか、その人たちの処遇というのは一体どうなっているのか。それはあまり望ましいことではない、あるいは愚痴なのかもしれないけれども、一体どうなっているんだろうと思うんです。何かわかれば、わからなければわからないでいいんですが、どうなっているんだろうというものがありますので、わかれば教えていただけませんか。","respondent":"新美保健高齢事業部長","answer":"ただ、社会福祉法人については、今までどうしても措置時代の東京都としての一定の水準とかルールとかありましたので、それを踏まえておりますが、介護保険になりまして、やはり今後どうしていくのか、それぞれの法人ごとで独自に工夫をし。","voiceIndex":88,"id":"exchange-040"},{"speaker":"高木委員","kind":"質問・要望","question":"今の副委員長のご意見に私も感ずるところはいっぱいございまして、特に鶴委員とは同じ期間少し長めになったかどうかやらしてもらっているものですから、よく副委員長は手の届きすぎるような、そしてこれは表現がしにくいんですが、関心して聞いていたんですが、私も最初は介護事業という、とにかく大変な命題に向かって大層ご努力されているということは、私はもうまちの中へいっても一生懸命言うんです。","respondent":"新美保健高齢事業部長","answer":"今後は特別養護老人ホームは入所者の声をどういうふうにしていくかという、これにつきましてはなかなか単純にはいきませんけれども、今ご意見があったような利用者本人をどういうふうに声を把握するか、その辺を工夫していきたいというふうに考えております。","voiceIndex":90,"id":"exchange-041"},{"speaker":"高木委員","kind":"意見","question":"今年から保険料の通知が来まして、ぎょっとしました。私は１年間分６万５,０００円ぐらいかな、これは深刻になりましたね、１年間まとめて納めるとするとですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":92,"id":"exchange-042"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"３３ページのところに質問１４「モニタリング情報の収集（事業者より）」というところで６８.３％が「できていない」、それから質問１７「必要に応じた再アセスメントの実施」というところで５５％が「できていない」という回答をしているんですが、この辺のところの実態についてと、本来あるべきモニタリングがどうなっているのかお聞かせください。","respondent":"早津高齢福祉課長","answer":"ただ、中には残念ながら行ききれていないのもあることは事実です。なるべくこのようなことのないように、私どものほうでもモニタリングを継続的に行うようにということをお願いしています。","voiceIndex":93,"id":"exchange-043"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"本来であれば、１カ月に一度くらいは利用者のところにケアマネージャーがお伺いして、実態を見るということが必要だというところなんでしょうか。","respondent":"新美保健高齢事業部長","answer":"どの程度の頻度ですべてということになりますけれども、今のケアマネジメントの実態と介護報酬における体制の取り方からいいますと、すべてを１カ月に１回行くというのはなかなか難しいかと思いますし、それが本当に必要かどうかということにもなるかと思います。","voiceIndex":95,"id":"exchange-044"},{"speaker":"林（和）委員長","kind":"質問・要望","question":"その他に移ります。私のほうからご案内を申し上げます。継続となっておりました、平成１３年請願第１２号、新たな大気汚染公害被害者の救済を求める意見書に関する請願につきましては、次期の委員会に申し送りたいと思いますが、よろしゅうありますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-045"},{"speaker":"鶴副委員長","kind":"質問","question":"この１年、各委員の熱心な、かつ活発な質問、提言等をはじめ、各理事者の真剣かつ適切な各事業に対する事項の説明および造詣の深い答弁により、今年度の厚生委員会も多くの成果をおさめることができたのではないかと思うのは私ばかりではないのではないかというふうに、今ご推察をしています。この１年、本当にありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":102,"id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3016#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":44793,"voices":103}},{"id":"h14-20020508-8","meetingId":"h14-cm05","date":"2002年5月8日","dateIso":"2002-05-08","committee":"建設委員会","time":"午後１時０５分～午後３時１０分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成１３年請願第５号、住友不動産による「仮称 大崎５丁目マンション」超高層、高さ１００ｍ、３０階建てに対する請願","agenda":"平成１３年請願第５号、住友不動産による「仮称 大崎５丁目マンション」超高層、高さ１００ｍ、３０階建てに対する請願","exchanges":[{"speaker":"上山委員","kind":"質問・要望","question":"ちょっとお尋ねなんですけど、４月２０日に守る会、地元の方々と本協定を結ばれたという話を伺ったんですが、あわせて、今その関係じゃないんですが、それとの係わり、今ご説明の中で、都の建築審査会ですか、住民が総合設計の取り消しですか、一言で言えば、それを出しているという話が、今説明あったかと思うんですが、現場のほうは工事が始まっているような状況のようなんですけれども。","respondent":"浜脇住環境整備課長","answer":"前回もお話ししましたけども、工事自身は２月１日から着工しているというふうになっておりまして、着工する前に、本来ならば工事協定書を結ぶというふうになっておったわけですけども、結べなかったので、やっと４月２０日の日に結んだから。","voiceIndex":5,"id":"exchange-001"},{"speaker":"築舘委員","kind":"質問","question":"この本工事協定を結んだ守る会というのは、この請願書を出している大崎および品川の環境を守る会ということでよろしいんですか。","respondent":"浜脇住環境整備課長","answer":"はい、冒頭にありましたでしょうけども、大崎および品川の環境を守る会ということで、請願代表者以下1,９６６名という方々だと思われます。しかし、そのうちの何名かがそういうことで、会じゃなくして、個人的な形で出されているというふうに聞いております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"辻委員","kind":"質問・要望","question":"継続していただきたい。私も前から言っているように、４番目の違う部分、４番目は難しいなというのはわかります。ただ、個々の問題についてはちょっと大きい問題ですから、その部分、その分野分野、地域地域によって、このマンションではこれは日照の問題、こっちについては風害の問題とかというふうな交渉に入ったよということですね。継続で、できればお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-003"},{"speaker":"沢田委員","kind":"質問","question":"できることなら、紹介議員の方に、一部の方がそう出て反対するというのは、これは請願者とまた違うものですから、ある程度これで目的を達したんならば、じゃあ今まで継続して時間を持ったことで議会としての役割を終えたという評価をしていただけるんだったら、取り下げてもらうのが一番いいかなという気がするんですけど、そういう可能性があるかということでしたら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-004"},{"speaker":"本間委員","kind":"意見","question":"大変難しいことになってしまいましたですね。ただ、今、辻委員のお話、知らなかったんですが、そういう部分をどういうふうにして配慮していくか、ここで結論を出すことによって、その皆さんに対して、逆の意味での、それを出したことによっておかしくなるのであれば困るということは確かにあります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":13,"id":"exchange-005"},{"speaker":"辻委員","kind":"質問","question":"今の項目は、大崎および品川の環境を守る会が交渉してきたわけですよね、こういうのをやってくれないかというふうな、日照被害のこともやってきたと思う。それで、それが多少手直しができた、ですから、沢田委員が話したように、どういう扱いをするか、不採択で願意に沿いがたいというのもおかしな話だ。ですから、こういう状態になっているんですよということをもう一回請願代表者にちょっと話してみたら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-006"},{"speaker":"沢田委員","kind":"意見","question":"それで、いつも悩んでいて、議会側として、それをその話し合いのさなかに採択するということは果たして妥当なのかどうなのかということもあって、継続をしながら調査したり審査して、ある程度当事者間の話し合いの進行を見届けるというか、それで、不満があっても協定できて解決をして、そこでやるんですけど、そのときの、一つはそうしたやり方でずっと来ていますよね、全体としては。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":17,"id":"exchange-007"}]},{"id":"topic-02","title":"平成１３年請願第６号、石井ビル建築計画に関する請願","agenda":"平成１３年請願第６号、石井ビル建築計画に関する請願","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"そうすると、これは誓約書を提出して着工したということは、基本点では合意に達したということなんですか。","respondent":"浜脇住環境整備課長","answer":"合意に、実は項目がたくさんあった、１２項目ぐらいあって、半分ぐらいしかその項目に対して誠意といいますか、変更できなかったという事情があったようでございまして、１００％のいわば言い分ですね、住民側の言い分を聞いたわけじゃございませんので。","voiceIndex":32,"id":"exchange-008"},{"speaker":"沢田委員","kind":"質問","question":"この問題についても請願者、区議会議員を通じて特に取り下げることはしないと。そのまま出してくださいということなんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-009"},{"speaker":"沢田委員","kind":"質問","question":"これは請願項目としては三つ挙げていて、中層棟の設計変更というのと、それから安全な工事を十分説明するようにというのと、みんなアンダーラインしてあるところがメインですよね。建築業者と十分話し合いできるようにと言っているんで、さっきの趣旨採択とのバランス上、こっちはだめだというふうにいかないから、この程度であれば趣旨採択としていいんじゃないでしょうかね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-010"},{"speaker":"築舘委員","kind":"意見","question":"一番いいのは工事が進んでいるので、取り下げてもらえばいいかなというふうには思うんですけど、それが難しいというさっきの委員長のお話なので、大分進んでいて、そんなに、そういう意味では趣旨に関しての採択をしても、別にその後の影響がなければ趣旨採択ということでいいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":51,"id":"exchange-011"},{"speaker":"辻委員","kind":"意見","question":"こういうの、ＣＰのやるの。区民にもうちょっとアピールして、やっていることを知らしたほうがいいと思うんですよ。そうすれば安心感もあるだろうし。だから、ギャラリーがどうこうというのは別として。やっぱり、そういうＰＲをして関心を持たせたほうがいいんじゃないかな。","respondent":"中谷まちづくり事業部長","answer":"本件につきましては、広報等につきましても連携いたしまして、パブリシティー等お願いするということになっておりまして、また、デジタルビデオ等で撮影いたしますので、そういうものでＣＡＴＶ等で周知できる余裕があれば、そちらにお願いするということにしていく予定です。","voiceIndex":60,"id":"exchange-012"},{"speaker":"辻委員","kind":"質問","question":"このデータを出したときに、沿線の住民に対しては、どういう形でバックするんですか。","respondent":"中谷まちづくり事業部長","answer":"将来的にはＣＡＴＶ等に放映するということも考えられますし、今年、事実ＣＡＴＶで情報等を提供するように今ちょっと検討しておりますが、それとあわせてやることも将来的には考えられますし、運用についてはちょっとしばらく思考させていただきたいというふうに考えております。","voiceIndex":66,"id":"exchange-013"},{"speaker":"辻委員","kind":"意見","question":"今度短い幹線の中で、その辺をどうやって知らせるか、地域の人との連携を十分その辺をやっていかないと、特に立会川も既に動いているようですけど、要するにどの辺まで知らせていいかというのも難しい。サイレンが鳴ったらどういうふうになるのか。クイックプランとしての全体的なそういうものをリアルタイムですることは非常にいいことで、ただそれをどう使うかということを要するに住民がどうすればいいか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":68,"id":"exchange-014"},{"speaker":"沢田委員","kind":"質問","question":"これは四角になっているけど、下水管の中の水位ですよね。そうすると、形は丸と。ちょっと初歩的な質問で。","respondent":"中谷まちづくり事業部長","answer":"普通下水管というと管が、円形管が多いわけですが、ここは戸越幹線と立会川幹線については矩形渠ということで、四角い断面になっておりまして、四角い断面の中に、真ん中のところに少し常時水が流れる。","voiceIndex":69,"id":"exchange-015"},{"speaker":"沢田委員","kind":"質問","question":"光ファイバーケーブルなんですけれども、東京都なんかは下水管に光ファイバーを通して、これを売って一もうけするみたいな、前にそんな報道があったと思うんですが、基本的には全部入っているものなんですか。","respondent":"中谷まちづくり事業部長","answer":"ただ、従来から、１０年近く前から都庁周辺では光ファイバーを試験的に敷設して、それで試験をやっていたということもありますし、今回についてはこれはあくまでいわゆる管の管理、下水道施設の管理、それを都民に役立てるという観点で、これを品川区にも提供するということで。","voiceIndex":71,"id":"exchange-016"},{"speaker":"横山委員","kind":"質問","question":"ですから、それはやっぱり逐一ブザーかなんか、目視じゃなくてブザーかなんかで知らせてくれるんだと思うんだけども、そこら辺がどうなっているのか１点と、今の防災無線、要するに防災無線が品川全域に対して面というか、地域で何系統ぐらいに分かれているのか、こちらのほうで、要するに機械操作で品川区１方面、２方面、３方面という、そういう分布のもとで。","respondent":"中谷まちづくり事業部長","answer":"それから目黒川流域だけ知らせるもの、立会川流域だけのもの、それから戸越幹線流域だけでもできるようになっているということで、これは先般にいじくった際に、そのような形で変更しておりますので、今回ですから、このシステムが確立されれば。","voiceIndex":73,"id":"exchange-017"},{"speaker":"横山委員","kind":"質問","question":"今、確かに幹線ごとにそういった防災無線系統ができているというのはよかったです。それとあわせて、品川全体、一つですかね、それとも荏原地区、大崎地区、品川とか、そういう分け方はされてなかったですかね。ちょっとその系統図、どういう系統、今言う河川はわかったんだけど、品川区全体じゃなくて、地域的に分割されていると思ったけど、その辺のちょっと内容を知りたい。","respondent":"中谷まちづくり事業部長","answer":"ちょっと防災課の所管で、私どももどの程度分割できるかという話、細かくは聞いておりませんが、あれはいずれにしても手を加えればできるというふうには聞いておりますが、どの程度細かくなるのかというのは、ちょっとそこまでは承知しておりませんので、もしよろしければ。","voiceIndex":75,"id":"exchange-018"},{"speaker":"横山委員","kind":"質問","question":"片方でお家へ帰ろうと行っているのに、片方じゃほかのやつで、同じ５時にポーンと鳴り出すんだね。ですから、そういった地域には系統を外してほかのものをやるとか、何かやっぱりそういった配慮が必要かなと、そう思ったものだから、今これに引っかけて聞かせてもらったんだけど、そのあいだにいると、ほんとうにうるさく聞こえるというか、何を言われているかわからない。参考までに。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-019"},{"speaker":"辻委員","kind":"質問","question":"月見橋の雨水対策工事でしょう。ですから、月見橋まで雨水下水管を引っ張ってくるの。立会川のあいているところはどうなるの。","respondent":"中谷まちづくり事業部長","answer":"前のとき、図面でこちらで下水道課長がこの図面の大きい図面ですが、これで説明させていただきましたが、月見橋までシールド工事で立会川幹線の放流橋ですが、これを内径3,２００mmの管を月見橋まで抜きまして、到達立坑をつくりまして。","voiceIndex":82,"id":"exchange-020"},{"speaker":"築舘委員","kind":"質問・要望","question":"立坑用地の整備ということで、樹木の撤去ということが書いてありますけど、前に桜があって、それを松にしたかな、本間委員からのご指摘があったんですけど、そういうことがありまして、だから、今回松が植わっているんですけど、それをどういうふうにして、どういうふうに今度持っていくか、ちょっと教えていただきたい。","respondent":"中谷まちづくり事業部長、佐藤委員長、中島街路事業担当課長","answer":"以前、大変私ども行き届かなくて失礼を差し上げたわけですけど、今回につきましては、これについては、撤去というのは概要の言葉で書いてありますが。ほかに。なければ、本件の質疑を終了いたします。先般、４月１５日の本委員会におきまして、４月２７日に用地説明会をするということでご報告させていただきましたけれども。","voiceIndex":84,"id":"exchange-021"},{"speaker":"上山委員","kind":"質問","question":"ちょっと、前にも聞いたかもわかりませんが、今回測量の説明会、用地の説明会を同日でやられているかと思うんですが、今これでまだ説明会は２７日ですから、連休を挟んでいるから、あるかと思うんですが、例えば、買収の話ですよね。","respondent":"中島街路事業担当課長","answer":"今のご質問は成立したということですか。","voiceIndex":90,"id":"exchange-022"},{"speaker":"上山委員","kind":"質問・要望","question":"ちょっとその関係で、私、さっき土地収容暫定補償の話がちょっと出ていたかと思うんですけれども、いろいろな形態だとか、いろんな状況でいろんなものが出るかと思うんですけれど、ちょっとわかりませんが、一般の話で恐縮なんですけれども、中にはこういう形で、例えば形状が小さくなって、買ってくれればいいんだけど、うまく折り合いがつかなくて、それは困ると、わかりませんけどね、もし。","respondent":"中島街路事業担当課長","answer":"そういった部分では、いろんな形で残地ということが生じる可能性があるわけですけれども、そういった不動産業者の方と連携を密にしながら、情報交換しながら残地について、うまく、いわゆる民民での売買可能な形にできればというふうに判断しております。","voiceIndex":94,"id":"exchange-023"},{"speaker":"沢田委員","kind":"質問","question":"その問題で、買収を進めていくという問題は、どうとらえたらいいんでしょうか。","respondent":"中島街路事業担当課長","answer":"それでもう一つ、例えば残り１軒とか２軒とかという場合、先ほどこちらの補償の説明の最後のほうにあるんですけれども、私ども、とにかく収容部分につきましての事業なもんで、実際そういうことのないようにということで進めていくわけですけれども、伝家の宝刀というんですか。","voiceIndex":96,"id":"exchange-024"},{"speaker":"沢田委員","kind":"質問","question":"成田だってそうですよね。ちょっと説明をお願いしたい。それから、再開発と街路事業としての用地買収というのは、再開発というのは、どっちかというと権利変換じゃないですか。例えば、用地買収して、うちは例えば再開発を希望するから売らないよと言った場合に、どう処理を、とりあえず買いましょうみたいな形でやるのか、そこらがもう一つ見えないんですけど。","respondent":"中島街路事業担当課長","answer":"最初にちょっと再開発との関係ですけれども、私どもが道路用地として買収する蓄積といいますかね、そこは再開発の区域とは違うところです。","voiceIndex":98,"id":"exchange-025"},{"speaker":"辻委員","kind":"質問","question":"要するに真ん中の新築でもいいわけですけれども、民民の境界をやっていくというのは慎重にうまくやっていかないと、真ん中に挟まれている人なんていうのは、要するにどこかで真ん中というのがよくあるんですよね。その辺の心配というのは非常にある。その辺の折衝なんていうのはまさしく課長のほうでやっていくんですか。","respondent":"中島街路事業担当課長","answer":"ですから、先ほどの資料ですけど、２ページ目にＡさんの土地とありますけど、すべての点を決めるのに、すべての線を決めるのに、こちらに隣接している人すべての合意を得られないと、要するに境界が確定していかないわけですので、そういった面で。","voiceIndex":106,"id":"exchange-026"},{"speaker":"辻委員","kind":"質問","question":"ぜひ慎重に、７７人という人しか来てないようですけど、もっともっと該当する人もいるでしょうし、そういう意味では、背後地にも関係するわけですから、慎重に、ここでボタンをかけ違っちゃうと、それこそ先ほど沢田委員から話が出たように、感情のもつれが出たって、それじゃどうしようもないと思いますので、ぜひお願いしたいと思います。","respondent":"佐藤委員長、田村住宅課長","answer":"ほかに。ほかになければ、本件を終了いたします。区民住宅の空き家入居者予定登録募集についてご報告申し上げます。１、募集内容ですが、１４年６月の区民住宅（空き家）の入居予定者の登録募集です。内容は家族用、単身用です。","voiceIndex":108,"id":"exchange-027"},{"speaker":"沢田委員","kind":"質問","question":"宅建管理センターに委託をしたというのは、どういう委託をしたのかというのと、株式会社宅建組合が会社を設立したんだと思うんですけれども、さっきの話だと、抽選もここに任せるんですか。ちょっとよく聞き取れなかったんで教えてほしいんですが。","respondent":"田村住宅課長","answer":"厳密に言いますと、品川都市整備公社と宅建との契約ということになりますが、３社で区のほうも入って、宅建品川支部と、そんなに前から、やはり既存の区民住宅、ご存じのとおり、かなり地域に分散しているというような状況がございまして。","voiceIndex":115,"id":"exchange-028"},{"speaker":"沢田委員","kind":"質問","question":"そうすると、宅建管理センターに委託した委託内容というのは何と何なんですか。","respondent":"田村住宅課長","answer":"入居者管理というのは、具体的には使用料の徴収あるいは滞納、短期滞納者の対応、あるいは苦情があった場合の対応、よく中で水をこぼしちゃったとか、そういうような苦情があったときの対応、それと、建物の維持管理、大きく入居者管理と建物の維持。","voiceIndex":117,"id":"exchange-029"},{"speaker":"沢田委員","kind":"質問","question":"荏原青果の跡の区民住宅の管理を、あれはどこでしたっけ。大手にという話がありましたよね。それとこれとの関係はどうなんですか。","respondent":"田村住宅課長","answer":"Ｃ棟のほうは複合棟ですので、まだ具体的にどこに委託管理するかは決まっておりません。今後調整して検討していくという形になります。","voiceIndex":119,"id":"exchange-030"},{"speaker":"築舘委員","kind":"質問・要望","question":"さっきは都市計画道路事業により移転する方に対して品川区では区民住宅、区営住宅のあっせんする制度があるということが書いてありましたけど、あけておかなきゃいけないといいますか、区民住宅であけなきゃいけない部屋というんですか、そういうのはどの程度の間隔でとってあるのかということと、それからあと、空き家の２０団地というのが多いのか少ないのか、ちょっと今の時代わからないんですけど。","respondent":"田村住宅課長","answer":"今回の事業に基づく……。","voiceIndex":121,"id":"exchange-031"},{"speaker":"辻委員","kind":"質問","question":"その場合、資格審査は区がやるの、それとも、委託先ですか。","respondent":"田村住宅課長","answer":"やはり、入居決定そのものは区がやらなきゃだめ。先ほど自治法でやらなきゃならないとなっておりますので、最終的に区のほうでチェックして、抽選という形になります。","voiceIndex":125,"id":"exchange-032"},{"speaker":"沢田委員","kind":"質問","question":"２回目になってすみません。区民住宅ができてから１０年たちますか。だんだん前の家賃を引き上げていくということになっていますよね。そうすると、早く建ったものの家賃は、古いは、家賃が高くなるはというんで、だんだん空きが大きくなる傾向はないですか。","respondent":"田村住宅課長","answer":"一概に、確かに一番古いのですと、平成４年度の借り上げが一番古いですから、既に１０年経過ということで、ご存じのとおり２０年の傾斜家賃になっていますので、やはりかなり金額的な、最初の設置当時から比べると、金額的な面では上がっていますが、必ずしも立地条件だとか。","voiceIndex":127,"id":"exchange-033"},{"speaker":"沢田委員","kind":"質問","question":"最初、たしか５％ずつ上がりましたよね。それで、今３％になったんだけど、３％で２０年だと６割ですよね、上がるのが。上がっていくとなれば、早晩空きが出てくることを、埋まらないということを想定しておかないとまずいんじゃないかなと思うんですけど、それはないんですか。","respondent":"田村住宅課長、山室住宅指導担当部長","answer":"収入により家賃が異なりますので、支払いの、そうすると、やはり、例えば沢田委員がおっしゃっているように、収入部位が一番高いですから、そうすると、ほとんど補助金がつかない、本来規定の家賃に近い家賃だと。ですから、空き家がその時点で発生するかどうかというのは、民間の賃貸住宅市場の動向によるわけですが、基本的にその間、２０年たてば我々のほうの家賃補助といいますか、公的な住宅としての性格は今度借上型の場合は手を離れて。","voiceIndex":129,"id":"exchange-034"},{"speaker":"沢田委員","kind":"質問","question":"１０年前というと、バブル崩壊して２年ぐらいたったときで、家賃はまだグーンと今より高くて、そこから地価がグーッと落ち込んでいるわけですね。品川が持ち出せばいいけど、そんなのはやっぱり制度としてはあり得ないことですから、どうも私は不安でしようがないんですけど、ここで言ってもしようがないですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":132,"id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3718#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":34171,"voices":135}},{"id":"h14-20020508-9","meetingId":"h14-cm05","date":"2002年5月8日","dateIso":"2002-05-08","committee":"文教委員会","time":"午後１時０３分～午後２時５５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"川西委員","kind":"質問","question":"ですから、一貫校の第二日野小学校が目指して、平成１８年開校のモデルとして、既存の小・中学校はすぐ一貫校にはならないですね。意見です。それで、多少は説明の中でおっしゃっていたけれども、平成１８年開校までの施設計画というのは、組織づくりはできているんですか。それから、ここにあります準備委員会の開催の計画というのは、例えば月に一遍やるとか、二遍やるとか、その辺を教えてください。","respondent":"富田教育改革担当課長","answer":"小中一貫校準備委員会の開催計画につきましては、昨日第２回目を開催したところですけれども、当面、月に２回ペースで開催していきたいと考えておりまして、施設計画検討部会につきましては月１回程度。","voiceIndex":8,"id":"exchange-001"},{"speaker":"川西委員","kind":"質問","question":"もう１点、施設計画検討部会の庁内のスタッフというのはもう大体固まったんですか。何課がどういうふうに参加するか。","respondent":"富田教育改革担当課長","answer":"施設計画検討部会のメンバーですが、予定校の第二日野小学校長、日野中学校長、第二日野小学校ＰＴＡの代表、日野中学校ＰＴＡの代表、地域の代表といたしまして、大崎第一地区町会自治会連合会の代表、建築専門家といたしまして国立教育政策研究所の総括研究官、若月教育長。","voiceIndex":10,"id":"exchange-002"},{"speaker":"川西委員","kind":"質問","question":"今のはよく分かりました。体育館の複合化とか、お考えが多少ありますよね。それは区も含めてのことだと思いますが、その辺はいかがですか。","respondent":"鷹倉庶務課長","answer":"それの外側にといいますか、体育館のほうの検討委員会というのを大きく立ち上げていきたい。準備をすでに始めてありますけれども、それと、施設計画検討部会とのパイプをつなぎながら、建物全体の形を形づくっていきたい、こういう考えを持ってあります。","voiceIndex":12,"id":"exchange-003"},{"speaker":"桜井委員","kind":"質問・要望","question":"小中一貫校検討準備委員会のメンバーの氏名をもう一度教えていただきたいと思います。二つ目には、説明会の関係ですけれども、この回数やられて、参加者が大体１２３名ですね。これで説明会は終わりだというつもりなのかどうなのか。とりあえず今の、例えば第一日野小学校から第四日野小学校までの生徒数は８６０名ですね。自分たちの問題としては、どういうニーズなのか。最初に教えてください。","respondent":"富田教育改革担当課長、鷹倉庶務課長","answer":"小学校ＰＴＡ連合会会長代理、中学校ＰＴＡ連合会会長、小学校校長会会長代理、中学校校長会会長、公募区民として２名、学識経験者といたしまして、帝京大学名誉教授、同じく学識経験者といたしまして、東京学芸大学教授。小中一貫校検討準備委員会とか部会があるわけですけれども、本来、ここを経てプラン２１推進委員会、教育委員会、あるいは文教委員会、こう説明をしながら、本来地元に入っていくのが筋かなと思っているんですけれども。","voiceIndex":16,"id":"exchange-004"},{"speaker":"桜井委員","kind":"提案","question":"漢字とかわからないので教えてください。だから、そういう点では、もちろん関係者もそうでしょうし、それから、今お話のあったＰＴＡ全体もそうだし、これから上がろうとしている、町会の回覧で回すということにとどめないで、以前、公聴会というところの設定をして、いろいろ広く意見を聞くということを提案したことがあるんですけれども、その辺についてはどうなんですか。","respondent":"鷹倉庶務課長","answer":"公聴会という部分については、今のところ考えてございません。いろいろお知らせする手だては考えていかなければいけないと考えていますけれども、今のところ委員ご提案のことについては考えてございません。","voiceIndex":19,"id":"exchange-005"},{"speaker":"桜井委員","kind":"質問","question":"それは何か理由があるんでしょうか。後で質問もしたいと思うんですけれども、もともと教育というのは基本的には親の願い、子どもの願いというか、地域の願いに沿ったものになるわけですね。だから、そういうことで、いろいろな意見を聞いて、あるいはこういう点についてはどうだとかと聞くというのが基本だと思うんですけれども、公聴会を避けるというのはどういうことなんでしょうか。","respondent":"鷹倉庶務課長","answer":"避けるということでなくて、意見を聞く場というのは、いろいろな機会があるわけです。我々はシステムを説明しているとおり、いろいろなところで意見を集約された形で固まったものでなくて、案という形でお示ししていって、話を聞くという形で、まさに聞く場を設けております。","voiceIndex":21,"id":"exchange-006"},{"speaker":"桜井委員","kind":"質問","question":"今の学生というか、学校教育法に基づいて、１年生、２年生、３年生は何歳で行くという形ですね。これを「年齢主義」という学問的な言い方というのはあるんですか。そのことをすごく問題にしているんでしょうか。６歳で１年生に上がるということを問題にしているんでしょうか。それは当然ですよね。だから、振り返って、何によってこういう分析をしたのか、何かデータがあるのかどうか、そこが知りたいんです。","respondent":"青木指導課長","answer":"そうした社会的な背景の捉え方というのが客観的な内容になっているかというふうに考えております。","voiceIndex":23,"id":"exchange-007"},{"speaker":"桜井委員","kind":"質問","question":"データはないというふうに言っていいんでしょうか。カリキュラムだって変えてやるわけですから、全然別のものでしょう。というのは、小中一貫というのは、基本的にはその学校だけですから、学校選択というのは、どこでもいいからというので自由でしょう。だから、私は小中一貫の言われる、親たちの願いとか、教師の願いの、何か具体的なデータがあるんですかという質問をしたんです。","respondent":"青木指導課長","answer":"小中連携の一つの一体化型の一貫校ということで、その連携の中でのノウハウというのは当然生きてきますし、また逆に、一体化された一貫校での成果もそこに戻されます。そういう意味で、先ほどの連携については、そのように考えていただきたいと思います。","voiceIndex":25,"id":"exchange-008"},{"speaker":"桜井委員","kind":"質問・要望","question":"そういう声があったら、次回に具体的に示していただきたいと思います。もしそういう声があるとしたら、日野中学校のＰＴＡ会長から要望書が出ておりますよね。前回も幾つか紹介されたんですけれども、ここに書いてある要望書というのは、まさに突然学校の小中が決められた。拘束されないでやるということは、これは文部科学省の研究開発校だからなんですか。そこだけちょっと確認しておきたいんです。","respondent":"青木指導課長","answer":"学習指導要領そのものに対して、今もすでに、委員もご存じのように、複数学年によって目標なども示されておりますので、学習指導要領自身が極めて弾力的になってきておりますけれども。","voiceIndex":27,"id":"exchange-009"},{"speaker":"桜井委員","kind":"確認","question":"ほかの学校でもこういう考え方でいいという理解でしょうか。品川区のほかの小・中学校でも弾力的にやっていくということでいいのかどうか。この地域というのは東五反田二丁目ですよね。どこまで説明するかどうかは別としても、全体像といったものがないという、その捉え方というのがよくわからないんですけれども、それはそれで説明されたならばいいですけれども、それだけ確認します。","respondent":"鷹倉庶務課長、青木指導課長","answer":"これが東五反田地区のところの核的な役割を担えばいいな、担いたいなと、こういうような話をしたところです。他校においては、基本的には一定程度の拘束性というのはありますけれども、それにしましても弾力的な取り組みというのは今後検討していくことになるというふうに思います。","voiceIndex":29,"id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"確認","question":"先に確認的なところですけれども、小中一貫校が第二日野小学校と日野中学校で進めていきますが、今後の品川区内の展開としてどういうふうに考えていらっしゃるのかという点。それから、先ほど小中連携校７校と言いましたが、その実績的なもの、どのように取り組まれて、その制度の進み方はどうなっているかという点を教えてください。説明会の開催経緯の中で、参加者が少ないと思ったんです。","respondent":"鷹倉庶務課長、青木指導課長","answer":"説明会の開催の人数が少ない、あるいは時間の問題云々ということですが、これは当初、プレス発表された中身をお知らせするですので、役員の方にお知らせしたいという形でお話し申し上げました。今までの考え方からいけば、第二日野小学校と日野中学校の教員がどのような形で人事異動していくのかというようなことになるかと思いますけれども、これも一つの課題として今後検討してまいりたいと思います。","voiceIndex":32,"id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"一番最後のほうから確認させていただきたいんですけれども、当然東京都の人事権という問題だと思いますけれども、せっかく品川区でこれだけの認識を持ってやっていただく、その中でもうちょっと強く出せないのかなと感じるんです。もっと強くやってもらいたいなという希望を持っています。その中で支援をしていっていただきたい。それに対してどんなふうにお考えか、お答えをお願いします。","respondent":"青木指導課長、富田教育改革担当課長","answer":"１点目の教員の配置につきましては、強く希望されるということで、私たちもそれを受けて進めてまいりたいと思います。それぞれの方が自分に合った学校を選んでいくように、それぞれ選ばれる側として頑張っていけるような近隣の小・中学校となるように、特色づくりの部分でも教育委員会としては支援をしていきたいというふうに考えております。","voiceIndex":35,"id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"これだけすばらしい体制をとっている学校だという意識があるところに、普遍性をどう考えるのかを、選びやすいと同時に、選ばない方も当然出てくると思うので、そこら辺をよく考えておいていただきたいなという意識もあります。それは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-013"},{"speaker":"松澤委員","kind":"質問","question":"小中一貫校については、これだけ説明会を開いていただいているということが分かりました。説明材料もよくできているので、今後とも、話し合いをしていけば、理解者は出てくるのかなという気がいたします。でも、できた学校は小中一貫校ですからという中で、どのように地元に説明していけばいいのかというのはなかなか難しい問題なんだけれども、その辺をどう考えているのか。","respondent":"鷹倉庶務課長","answer":"それも説明をしながら、ご理解を得ていきたいなと考えています。なくなるわけではございません。こちらに移転するだけだという理解を懇切丁寧にしていきたなと考えています。","voiceIndex":39,"id":"exchange-014"},{"speaker":"松澤委員","kind":"質問","question":"第五日野小学校と一緒になったりした過程がありますからね。そういうのがまたなくなってしまうわけですね。幾ら日野中学校が移転したんだよと言っても、同窓会そのものは、今度は小中一貫校の第１回の卒業生が出て、そこから同窓会が始まっていくわけですから、今までの日野中学校の同窓会、第二日野小学校の同窓会そのものの居場所がなくなってしまいますよね。まちではそうなんです。","respondent":"指田教育次長","answer":"当然のことながら、移転ですから、従来培ってきた日野中学校なら日野中学校の伝統というものをドッキングさせながら新しいスタートを切っていきます。したがって、それが平成１８年４月１日から全く新しい学校になるなどということはゆめゆめ考えていません。","voiceIndex":41,"id":"exchange-015"},{"speaker":"松澤委員","kind":"質問","question":"理屈から言えばそうかもしれないですけれども、現実、第二日野小学校の周年行事かに出たときに、第五日野小学校の同窓会があるんですね。そういう人たちはどういうところを根拠に、どういうところを居場所にしているのかなと思ったものですから、そういうような中で、一つは語られる場というものを、今度小中一貫校につくる。ということなんです。","respondent":"指田教育次長","answer":"当然心の中で持つ部分もあるでしょうし、ハード的にもしそういうふうな部屋が必要であるならば、これはＰＴＡ室というのが大抵どこの学校でも設けますから、そういう中において、同窓会の方々がお集まりになる、あるいはふだんでも入ってこれるような。","voiceIndex":43,"id":"exchange-016"},{"speaker":"高星委員","kind":"質問","question":"全体で何回の説明会をやったのかわからないですけれども、それぞれ関係する学校のＰＴＡの役員や地元町会の役員に説明会をしているようですけれども、全体を通じてどういうイメージを持つのか、先ほど来の話だと、これからもご理解いただく場で説明会をやっていくんだという方向だから、一人ずつにご理解をいただいているという中身でないんだろうというふうに思うんだけれども。","respondent":"鷹倉庶務課長","answer":"しかし、我々はお話し申し上げているとおり、検討をこういう形でしていくのが筋だと考えていますし、教育委員会、あるいは議会に報告する中で、我々にできるのは精いっぱい、今日報告申し上げているとおり、途中経過ですよというものを、こういう場でお話ししつつ。","voiceIndex":45,"id":"exchange-017"},{"speaker":"高星委員","kind":"質問・要望","question":"それは、ここに掲げられているお題目は大変立派なものだと思うけれども、これからそういう声が沸き上がってくるだろうというふうに思うので、その辺のところは十分にクリアしてもらうように、そのことだけは確認させてもらうというか、どういうふうにやっていくかということを、先ほど桜井委員の話にも出てきたんですけれども、もう一度そのところをきちっと話をお聞きしたい。","respondent":"指田教育次長","answer":"何回も繰り返しになるかもわかりませんけれども、２月９日から４月１６日までの説明会というのは、冒頭申し上げましたように、小中一貫校のプレス発表資料の域までしか出ていない中での説明でございましたので。","voiceIndex":47,"id":"exchange-018"},{"speaker":"松澤委員","kind":"質問","question":"今、高星委員に答弁していただいた、たとえばですけれども、有楽街を通って来るのは第三日野小学校の子どもだという、これは基本的に選択制の中では、第三日野小学校の子どもが、あそこに行きなさいというわけではないんですから、最初に第三日野小学校を選んでいただいて、中学校のときに中学校を選択していただければいいのであって、それは全く誤解ではないんですか。そういう点はどうなんですか。","respondent":"指田教育次長","answer":"ただ、高星委員から今お話のあった、有楽街を抱えているというふうなところで、地域の方々の中にもそういうふうに言っている方もいらっしゃいますから、したがって、そういうことのないような安全面に配慮した、例えば通学ルートについてはきちんと立てるとか。","voiceIndex":49,"id":"exchange-019"},{"speaker":"飯沼副委員長","kind":"質問","question":"質問のところには、「文教施設を設置することで、これがまちづくりの核となっていってほしいと考えている」と書かれてありますけれども、まちづくりというのはこれから大きなところで検討をしていくと思うんですけれども、教育委員会としてはこういうふうなまちづくりにしていきたいんだという意向がとても大事だと思うんです。そこをどういう部分で出していかれるのかということ。二つお伺いします。","respondent":"鷹倉庶務課長、青木指導課長","answer":"やはり我々は、説明会に行ったときも、どちらかというと、ニュートラルな発言を心がけるようにしております。一貫校におけるカリキュラム開発とか、指導法の研究の中で、当然現状の小学校、中学校で生かされるものというのはあるかと思いますので、そういう意味で、まず一貫校で行うカリキュラム開発や。","voiceIndex":51,"id":"exchange-020"},{"speaker":"飯沼副委員長","kind":"質問","question":"今の子どもたちのいろいろ問題点が書いてあるんですけれども、こういう問題ももちろんあると思うんですけれども、小学校へ入った段階から子どもたちの受験のストレスというか、競争の教育の中でのストレスをすごく感じて育っているなという意味では、子どもたちの意見を、これからの子どもたちもそうですけれども、特に高校受験を終わった後の子どもたちの意見なども。","respondent":"鷹倉庶務課長、青木指導課長","answer":"１点目の、学校づくりの進め方という形でのお話かと思います。教師のほうも子どもの声に耳を傾けていくという、そういう子どもと教師の関係というのは今以上に強いものにしていきたいし、９年間にわたっての子どもの理解ということになりますと。","voiceIndex":54,"id":"exchange-021"},{"speaker":"桜井委員","kind":"意見","question":"小中一貫校準備委員会で検討する課題の案の中に、「実現に向けて考えられる課題」とありますね。教育課程、施設計画、学校経営、その他とありますけれども、もう一度整理して言っていただけますか。","respondent":"富田教育改革担当課長","answer":"両部会のほうから上がってきた課題検討の結果等々もこの準備委員会で報告を受けながら、プラン２１の推進委員会のほうに上げていくというような構成で考えているところです。","voiceIndex":57,"id":"exchange-022"},{"speaker":"桜井委員","kind":"質問","question":"少しイメージが違っていたんですけれども、今のお話はかなり事務的なことですよね。私はむしろ準備委員会の、今日文教委員会にお出しいただいた、こういう資料は大変ありがたいと思うんです。小・中学校はどういう目的を持って、どういう学校をつくっていくのかという、理念の部分が多いと思うんですけれども、こういうところをもう少し論議をしていくことかなと思ったんですが、そうではないんですか。","respondent":"富田教育改革担当課長、藤田委員長、上川内生涯学習課長","answer":"先ほど申し上げましたのは、個別の検討課題ということでございまして、それぞれの課題検討の前提といたしまして。ほかにございませんでしたら、以上で、本件を終了いたします。続きまして、報告事項の２番、平成１４年度情報通信技術（ＩＴ）講習事業の実施について、ご説明をお願いします。予算につきましては、補正予算を計上する予定ですが、６月３日から実施する予定ですので。","voiceIndex":59,"id":"exchange-023"},{"speaker":"山路委員","kind":"質問・要望","question":"それに関連して品川区はどういうふうな支援をしていくのか、その辺も決まっていたら教えていただきたい。テキスト１,０００円というのがありますね。できたら、こういう時代ですから、地元の商店の活性化のために、そういうところを通じて地元の書店で買えるとか、そういう形のものを利用していただいたらと思うんですが、その２点をお聞きいたします。","respondent":"上川内生涯学習課長","answer":"障害者のパソコンにつきましては、生涯学習課のほうではなくて、障害者福祉課のほうでトータルで扱っておりますので、今年度は私どももまだ細かいこれ以上の計画は立てていないように、ほかのところも立てていないようで、詳細は分かりかねますが、昨年度と同様ということで。","voiceIndex":65,"id":"exchange-024"},{"speaker":"山路委員","kind":"質問","question":"直接でなく、関連性において何か情報があったらということを聞きたかっただけなんです。もう１点は、クラスを変えてやるという計画がありますね。この内容だと、基本操作ですね。それはどういう形でやるんでしょうか。","respondent":"上川内生涯学習課長","answer":"このほかに生涯学習課、ほかのところでもパソコンの講習会、教室等は今までどおり、また、平成１４年度新たに組まれていると思いますが、生涯学習課ではシルバー大学とか、パソコン教室、通常の講座の中で、ほかの講座と同じような形で入れてはあります。","voiceIndex":69,"id":"exchange-025"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今の関連でお聞きしたかったんですけれども、レベルアップ講座を、前回の委員会で説明があったと思うんですが、これとはまた別個だということは分かりますけれども、そちらに対してはどのような形をとっているのか、もう一度お願いいたします。","respondent":"上川内生涯学習課長","answer":"基礎の部分だけではつまらないというお話もありましたので、通常の講座の中に、平成１４年度はレベルアップ講座を一講座入れておりまして、基礎講座で習った復習と、それから、もう少し上級の、レベルアップ分の学習もしていく講座を組んでおります。","voiceIndex":71,"id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ちょっと疑問だったのは、前回の請願のことに絡んできてしまうのですけれども、レベルアップ講座を一講座というのもちょっともったいないなと。今度の基礎講座の予算は分かりますけれども、区としてレベルアップぐらいまでは、あまり強調したところは言わないですけれども、一講座というのは少ないんじゃないかなという思いでお聞きしました。","respondent":"上川内生涯学習課長","answer":"一講座と言いましても、２０人で、２０回。４００人分の講座を、平成１３年度の基礎講座を引き継いで復習の講座として設けました。いつやるかという細かいことはまだです。","voiceIndex":73,"id":"exchange-027"},{"speaker":"鈴木（真）委員","kind":"確認","question":"確認ですけれども、２０人で２０回、４００人は受けられるということですか。","respondent":"上川内生涯学習課長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-028"},{"speaker":"高星委員","kind":"意見","question":"３０回ということで、平成１３年度と同様の内容ということですが、随分金をかけてやるのかなと思ったら、「違うんですよ。規模は５００人ですよ」という話で、講習の内容が、成人（２０歳以上の都民）になっているけれども、その辺はどういう内容なのか。","respondent":"上川内生涯学習課長","answer":"すみません、分かりにくくて。二つのものが別にあるんです。今日の報告というのは、平成１３年度に国全体でやったＩＴ講習会の平成１３年度の延長事業なんです。","voiceIndex":79,"id":"exchange-029"},{"speaker":"飯沼副委員長","kind":"意見","question":"振り返ると、教科書の採択の問題とか、ＩＴ講習会もありましたし、すまいるスクールもできまして、学校の安全管理の問題とか、小中一貫校とか、たくさんあって、あっという間の１年間であったなと思います。議会の役割の重要性と、議員の力量がすごく問われると痛感をした１年でありました。委員の皆様と、理事者の皆様のご協力に感謝いたしたいと思います。どうもありがとうございました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":85,"id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4436#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":34728,"voices":86}},{"id":"h14-20020508-5","meetingId":"h14-cm05","date":"2002年5月8日","dateIso":"2002-05-08","committee":"総務委員会","time":"午後１時０５分～午後２時５２分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を34件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の財団法人品川文化振興事業団の財産運用","agenda":"の財団法人品川文化振興事業団の財産運用","exchanges":[{"speaker":"宮崎委員","kind":"質問・要望","question":"目的のところで、地方公共団体の公金管理については、安全性と効率を同時に求められてきたが、今後は安全性の確認を最優先し、効率性も求めるというような、そういうふうに書いてある。この表現は基本財産も運用財産も同じなんですけれども、品川区の公金管理のこの方針とちょっと考え方が違うんじゃないかと私は思うんですけれども、そこら辺の見解というか、どういうふうに変わるのか、まずお聞きしたい。","respondent":"中尾根企画部長","answer":"私がご説明しました区に準じたというところは、運用要綱の運用指針、第２条の中の金融機関等の情勢分析だとか社会経済状況をよく適確にとらえなさい、この規程のところはペイオフ解禁等の絡みもあり、ここの部分は公金に準じた扱いだと言ったことでございまして。","voiceIndex":5,"id":"exchange-001"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ちょっとそれで質問なんですけれどもね。今回のやっぱり一番の反省点というのは、危ないものを買っちゃったということだと思うんですよね。そこで今までの、例えば前回の品川区の公金管理運用の方針、ここで言いますと、今までは安全性と効率を同時に求める。そういう規程だった。前提が安全確実という品川区の公金管理運用方針とはちょっと考え方が違うというふうに思うんですけれども、どうですか。","respondent":"中尾根企画部長","answer":"ここでそういう表現のもとに運用するということについては、今回少なくとも品川文化振興事業団についてはそういう運用方針はとらないということで、今回のように安全かつ運用益が得られるということ、ここは大きな変更点です。","voiceIndex":7,"id":"exchange-002"},{"speaker":"宮崎委員","kind":"質問","question":"ちょっと私が聞いたのは、品川区の公金管理運用方針の考え方と、この品川文化振興事業団の資産管理運用規程、ここのところの考え方というのはちょっと違うんじゃないですかということを聞いているんです。","respondent":"中尾根企画部長","answer":"それは何回もそのようにご説明しているつもりですので、よろしくお願いします。","voiceIndex":9,"id":"exchange-003"},{"speaker":"宮崎委員","kind":"意見","question":"そのことで、同じことをちょっと言っているんですけれども、私が言っているのは、一番の反省点がここにどういうふうに生かされているかというところが、やっぱり問題だと思うんですね。その点では、前回も総務委員会で説明された、品川区のほうは、私はこれは当然だと思うんですよ。は安全だと。前提が確実ですという言葉にならないでしょうということを言っているわけです。","respondent":"濱野助役","answer":"「かつ」というのは、ＡかつＢというと、Ａであり、なおかつＢだということですね。ＡまたはＢというと、ＡかＢかということになってきます。図にしますと、Ａという丸とＢという丸が重なっている部分がＡかつＢです。したがって、安全かつ確実なんです。","voiceIndex":11,"id":"exchange-004"},{"speaker":"宮崎委員","kind":"質問","question":"私がだから聞いたのは、品川区の公金管理運用と、この品川文化振興事業団の考え方が違うんですねと、ここはさっきから聞いているんだけれども、部長は法人があって人格が違うんだから違うんだと。私はそれは当然だと思うんですよ。私はそのことを言っているんじゃなくて、考え方が違うんじゃないですかと。","respondent":"濱野助役","answer":"委員のご質問は二つあるようですので、まず前半の、区の公金管理等の文章と、これと同一かどうかというお話ですけれども、同一ではございません。ただ、考え方というのは当然共通の部分もあるし、あるいは違う部分もある。全く同じであることはない。考え方は同じ。","voiceIndex":13,"id":"exchange-005"},{"speaker":"宮崎委員","kind":"意見","question":"じゃあ、私は意見だけ言っておきます。これは、私が言ったのは、この表現が今までと同じなんです。国の指導との関係で。なんだけれども、これは規程ということになると、この文言で、表現でちょっと不十分だ。今後のところでちゃんと歯どめをかけておくには、ちゃんと文言のところもきちっと安全、確実がまず大前提という表現にしておく必要があるというふうに意見で言っておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":15,"id":"exchange-006"},{"speaker":"林（宏）委員","kind":"質問","question":"文言の話が出たので、文言の話でいくと、規程のほうの１ページの第５条の１の「ただし」というところから、「ただし、緊急な場合または、理事会を開催する暇がないとき」、こういう書き方って。〔「いとまと言う」と呼ぶ者あり〕いとま。だけど、決め事にこういう表現はあるんですか。","respondent":"中尾根企画部長","answer":"暇がないときに専決処分する、こういう表現です。","voiceIndex":16,"id":"exchange-007"},{"speaker":"林（宏）委員","kind":"質問","question":"じゃあ、文言としては例えばどういうことですか。これは職務怠慢につながらないんですか。だって、重要なことを決めていこうというときに、それは何なんですか。専従じゃないからこういうことが起きるということなんですか。例えば品川区の企画部というところでこういう表現は使われますか。","respondent":"中尾根企画部長","answer":"私どもは、議会の関係の中で専決処分を、こういう似たようなことがありますけれども、議会は議会として開くだけの余裕ないしは何日前に通知してどうということはありますから、そういうことの暇がないときには専決処分をするというようなことでやってありますので、ただ。","voiceIndex":18,"id":"exchange-008"},{"speaker":"林（宏）委員","kind":"質問","question":"まさに今の話は、助役のインタビューで、理事会って年２回しか開けないんですよとしゃべったことがあるでしょう。始めから理事会はもう年２回しかやらないよという考えでこういう文言をうたっていると、僕はこれをそうとった。こういうふうに抜け道をつくっておくと、理事会は年２回でいい。だから僕は理事会の機能をもう少し持たすほうがいいような気がするんだけど、そうじゃないですか。","respondent":"濱野助役","answer":"したがって、寄附行為そのものを変えることはできないんでしょうかということを東京都の間でしました。しかし、東京都としては寄附行為を変えることはまかりならんと、やっぱり理事会で決めるということにすべきだ。","voiceIndex":20,"id":"exchange-009"},{"speaker":"林（宏）委員","kind":"質問","question":"とすると、やっぱり機能的に起きないようにしておくべきだと思う。個々の人は能力があり、そういう人が役につかれているというのは十分わかっているんだけれども、１人の判断でどうしても突っ走っちゃうときって、これに限らずいろんなところであるんじゃないですか。その辺はやっぱりきちんと今回のミスを繰り返さないような体制というか、運営をやっていくべきだと思いますので、よろしくお願いします。","respondent":"濱野助役","answer":"今、林委員が言われたことを規制しようということで、こういう規程をつくりましたので、そのご意見については十分に体して運用していくということをやってまいります。","voiceIndex":22,"id":"exchange-010"},{"speaker":"塚本委員","kind":"質問・要望","question":"ということで前回の事件が起きたと思うんですね。それはすべて我々が組織文化みたいなものを否定していくんではないと思いますけれども、せっかく高い授業料を払ったんですから、そこを直すということについて、その一環として、まず手近なところから、運用規程みたいなのをつくる、これは結構なことだと思うんですけれども。向こうさんの言うものが見えてくるのかどうかちょっと教えてほしいんですけれども。","respondent":"濱野助役","answer":"たまたま今回保有しているものが比較的長期のものですから、今のところ、その満期が来るまで理事会を開く予定はありません。ただ、この債券に何かの異変があれば、当然それをつけかえる必要が出てくれば、理事会を開いて対応していく必要があるということです。","voiceIndex":24,"id":"exchange-011"},{"speaker":"塚本委員","kind":"質問・要望","question":"特に金融財産の管理については、事故に遭うのは当たり前という時代に入ってきたわけですから、そういうことを踏まえて、委員会をしっかり意思決定ができる背景ができるような組織にしていっていただきたいと、これは要望を伝えておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-012"},{"speaker":"三上委員","kind":"質問・要望","question":"お願いしておきたいと思うんですけれども。それからもう一つは、基本財産と運用財産について、先ほど一応４億円と１億円とかという、そういうふうなおっしゃり方をしましたけれども、特別、基本財産というのはこのすべての財産の中の何割とか、そういう決め方というのはあるんでしょうか。とってもらうことはできないということになりがちになってしまう。","respondent":"濱野助役","answer":"そういう意味では、まず役所の充て職と言って、出ない理事を減らしたということがあります。今後またそれぞれの理事の任期満了の機会には、承ったような意見を踏まえて対応していきたいと考えています。","voiceIndex":27,"id":"exchange-013"},{"speaker":"三上委員","kind":"質問・要望","question":"そこらあたりを、動かせないならないなりの、理事だけ、それから一部の人だけが知っているということではなくて、この部分についてはきちっと、こういうことは盾になっていますという、これは外部の方が知ろうとしても十分知れるような形の表現というものを使って、ある意味では公表していっていただきたい、こうお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-014"},{"speaker":"林（宏）委員","kind":"確認","question":"ちょっと一つだけ確認させてくれますか。さっきの５条のところなんだけれども、真ん中あたりに、理事長は、理事会で別に定めた「資産管理運用要綱」に基づき資産運用することができる。この一言だけ読むと、すべて理事長の判断が要るというふうにとれるんだけれども、そう理解していいですか。","respondent":"中尾根企画部長","answer":"それ以外の財産ないしはそういう運用の部分については、これは処務規程の中の権限の中で実際上は分割する。ただ、最後の責任はやっぱり理事長であるのは、もうこれは間違いのないことです。そういうことです。","voiceIndex":30,"id":"exchange-015"},{"speaker":"中島委員","kind":"質問","question":"直近というのは、先ほど年に２回ではないと言いながらも、ちょっと期間があってもそれは直近の理事会だというふうにとられてしまう。ですから、やっぱり理事長の考え、考えというか、緊急性があって資産運用をしたときには、ただちに理事会を開催するという義務づけを私はここに入れておいたほうがいいんじゃないかなと思うんですけれども。","respondent":"中尾根企画部長","answer":"したがいまして運用の中でいくということで、先ほど副理事長が言いましたように、定款上は２回ということになっていますが、臨時で必要のあるときは積極的に、そのように持っていきたいという意向を示されたんですので、そのようにご理解いただきたいと思います。","voiceIndex":32,"id":"exchange-016"},{"speaker":"北野委員","kind":"質問","question":"ちょっと細かいことでお伺いしたいんですが、運用指針の部分で、理事長や理事の皆さんは専従じゃないですよね。それで、こういうことの情報把握とか、帳簿とか、常に管理するという方は、常駐として品川文化振興事業団の中でいらっしゃるのですか。","respondent":"中尾根企画部長","answer":"こういう関係で、区と財団との中では補助金を出している関係、ないしは基本財産を出している区でありますから、そういう関係で持っていきたい、そういう具体的な運用を考えているです。","voiceIndex":34,"id":"exchange-017"},{"speaker":"北野委員","kind":"質問","question":"そういうところをちょっとお伺いしたいんです。","respondent":"濱野助役","answer":"ただ、そういうような運用をするようなことになれば、やはり毎月なり何なりお送りする必要があるかと思いますが、現行の基本財産の中身を考えますと、何年か先まで変更する予定はありませんので。","voiceIndex":36,"id":"exchange-018"},{"speaker":"北野委員","kind":"質問・要望","question":"理事長の責任上というのがあって、いろいろ理事長には報告されるけれども、やはりほかの理事の方にどこまでの情報公開がされるのかなというのが一つあると思うんですね。やはりそういう中で、ある程度のそういう形にされて、決定へ持っていくということがすごく必要だと思うので、そういうところでは、やはり新たにつくった運用規程をしっかり有意義な形で実践していただきたいなと思います。","respondent":"中尾根企画部長","answer":"今回、それに新たに先ほど言いました債券に関する帳簿を載せたということ、これらについて、必ず備えつけしなくちゃいけないという規定と、要するに、ですから理事等がそのことについて見たいということがあれば、いつでも提供するという。","voiceIndex":38,"id":"exchange-019"},{"speaker":"林（宏）委員","kind":"確認","question":"一番直近が４月２３日の部長会ということで、(3)の都市計画決定の手続は、江東区が行うことで再確認というふうに書かれているんだけれども、やるということですか。それとも確認をしたということなんですか。","respondent":"小野（孝）政策担当課長、中尾根企画部長","answer":"江東区が都市計画決定の手続を進めるということについては、１月１７日の区長会の中で確認をされております。前提が崩れたら話し合いができないじゃないかということになる。","voiceIndex":44,"id":"exchange-020"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"帰属は５区だけと言っていいのか、いいでしょうね。５区で、うちだ、うちだとやっている。１７年度末の。都市計画決定が。ということから、非常に時間がないんですよね。帰属はまだ埋め立てが始まっていない部分も含めて帰属の問題をやっているんだから、その帰属はちょっと時間がかかっても別だけれども、施設建設については、非常に逼迫した時期に来ているというのを認識しておいていただきたい。","respondent":"中尾根企画部長","answer":"ただ、認識は、委員の指摘しているとおり私どももそういう危機意識を持って、これを、帰属の問題のおとりだとか、そういうことに使ってはならないはずだ、そういうふうには主張しております。","voiceIndex":47,"id":"exchange-021"},{"speaker":"塚本委員","kind":"質問","question":"このまま行くと、品川区に何のメリットも、領土が来るという可能性は薄いわけですから、品川区の利害を中心に考えると、ペンディングにしておいて、何らかの２４区目ができてもいいわけですし、あるいは再配分の中で違ったところになってもいいわけですけれども、そういうもっとフレキシブルな考え方もとれるのかどうかということを聞きたいんですが。","respondent":"中尾根企画部長","answer":"今委員がおっしゃったようなことは、実は品川区としてどう主張するかという点のときの検討の材料でもありましたし、検討もしてはきております。","voiceIndex":49,"id":"exchange-022"},{"speaker":"塚本委員","kind":"質問","question":"例えば建物をつくって、これは必ず灰溶融炉の方に属していなきゃいけないという縛りがほんとうにきついのかどうかというようなことだって考えられるわけですから、そういう意味から言うと、１００年というのを都市問題を考えていけば、ここが江東区だ、大田区だ、品川区だとやるよりも、そういうふうに悪い言葉で言えば先送り、だけれども、ある余裕を持たせておく判断。","respondent":"中尾根企画部長","answer":"大所高所からのそういうことについては私もいろいろ検討もしておりますし、例えば東京都の直轄地にそのまましておいて、そして何の不自然があって、ないしは都市計画決定がそれではまずいのかということのそういう法的な検証も十分してはおりますが、そういう背景がありますので。","voiceIndex":51,"id":"exchange-023"},{"speaker":"三上委員","kind":"質問・要望","question":"一つだけちょっと発言をさせていただきたいので。臨海トンネルの開通式のときに出席させていただいて、そのときに感じたのは、やっぱり議会も含めて、職員の皆さん、江東区と大田区が大挙して出席していたんですよね。議長と私もあれっと思ったのは、そういった情報をいち早く自分たちの領土戦争にもう取り組んでいるという実態が感じられたんです。ちょっと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-024"},{"speaker":"林（宏）委員","kind":"意見","question":"モニターの方々の品川区に住んでいる年数とか、そういう情報等はつかんでいらっしゃいますか。今回来た人はこれからいろいろ仕事をしていく上でわかるんだけれども、例えば昨年度のモニターの人たちが品川区にどのくらい住んでいるだとか、そういうような在籍というのかな、そういうものはわかりますか。","respondent":"山田広報広聴課長","answer":"実を言いますと、そちらの年数について入れてあるんですけれども、今回の資料の中ではお出しできておりませんけれども、応募していただく段階で在住何年というところを記入をしていただく欄がありますので、把握はしています。","voiceIndex":59,"id":"exchange-025"},{"speaker":"林（宏）委員","kind":"意見","question":"ちなみに平均で何年ぐらいで、古い人は何十年という人はいる、例えば比較的新しい人だと１年とか２年とかいう人がいらっしゃるのかどうか、その辺、簡単でいいですけれども。","respondent":"山田広報広聴課長","answer":"特に男性の方が転勤をしていて、やはり品川に戻ってきて、退職をして、やっぱり品川区をもう１回見つめ直したい、それで自分がやれることが何があるのか参加してみたいということで応募される方ですから、平均すると大体４０年近い年数が出てくるというふうに考えております。","voiceIndex":61,"id":"exchange-026"},{"speaker":"林（宏）委員","kind":"意見","question":"区でいろいろな方々、区民の人たちへのサービスというのを、今日もシルバー大学がありましたけれども、そういうような区がイニシアチブというか、リードをしながら住んでいる人たちへのサービスをいろいろ考えていく。品川区のそういうサービスというか、そういう人たちとモニターの人たちとのつながりというのはどういうところに、何かありますか。","respondent":"山田広報広聴課長","answer":"託児については私ども託児制度を持っておりますので、若いお母さまはご参加くださいということで、いつも託児をやっているんですけれども、そういう方々が初めて区政にかかわってくるというような感じの、ある意味では二極分化しているのかなです。","voiceIndex":63,"id":"exchange-027"},{"speaker":"林（宏）委員","kind":"質問","question":"そういう人たちを原則として１年でかわっていかれるということだから、そういう人たちに、言葉はいけないけれども、お役人の天下りだとか、そういうところにはたくさん力を入れるんだけれども、こういう人たちに街の中に、ばらまくという言葉はいけないけれども、散らばってもらって、いろんなかかわってもらうということは考えないんですか。","respondent":"山田広報広聴課長","answer":"あくまでも区の制度というこの制度の中にのっとってモニター活動をなさるというところで参加をしていただいております。ただ、現実的には１年やってみて、自分たちなりにもう少し違った形でできないか、それを継続してできないかというのが昨年の離任式のときにお話がありました。","voiceIndex":65,"id":"exchange-028"},{"speaker":"林（宏）委員","kind":"質問","question":"最後にします。おっしゃるとおり、最後に言われたとおりなんです。特にモニターに手を挙げる人なんかは、そういうものに関心を持っている人たちですから、ぜひそういうところのきっかけづくりも、お忙しいでしょうけれども、広報広聴のこういう仕事を通してやっていただければ。関心の高い人だから、ぜひそういうことで、街の中に出てきてほしいなというふうに思うので、ひとつよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-029"},{"speaker":"北野委員","kind":"質問","question":"モニターのＥメールのほうなんですけれども、こちらはなかなか区のところに参加できないからということもあってＥメールモニターをというのがあるんですけれども、お願いするものというのは、Ｅメールの方もモニターの方も同じようなことをお願いするんでしょうか。ちょっとそこのところを。まだ、ホームページについて聞いてもらいたいんですけれども。","respondent":"山田広報広聴課長","answer":"例えば品川の教育改革ということで、集会モニターの場合であれば、指導課長が品川の教育プランというのはこういうものですよ、こういうふうに進めておりますよというので、あとはご意見をいただくというような形をとるわけですね。","voiceIndex":68,"id":"exchange-030"},{"speaker":"北野委員","kind":"質問・要望","question":"それと、昨年された区政モニターのご意見で、出産一時保育の予約が１カ月前から３カ月前になったとか、区民公園を、月曜日がお休みだったのが無休に近い状況になった、これは区政のモニターの方の意見の反映ということなんですが、一般の私たち利用したい側の区民に対しては、区政モニターの結果としてではなく。","respondent":"山田広報広聴課長、本多委員長、西島経理課長","answer":"事業部ホームページの中で、例えば公園の利用の仕方でありますとか、先ほどの制度の問題、これは出産一時保育という制度ですから。本件を終了いたします。入札予定価格の事前公表につきましては、平成１０年１２月から３,０００万円以上の建設工事について実施をしてまいったところです。","voiceIndex":70,"id":"exchange-031"},{"speaker":"林（宏）委員","kind":"確認","question":"ちょっと確認だけ。試行がされていて、高どまりではなかったよということなんだけれども、ちなみに、パーセントを教えてください。","respondent":"西島経理課長","answer":"正直なところ、もう少し下げていただければと、所管課としては思ってありますが、先ほどのよそで言うような高どまり傾向というのは見られなかったというふうには考えております。","voiceIndex":76,"id":"exchange-032"},{"speaker":"林（宏）委員","kind":"意見","question":"９５％、９６％が、両方が平均すると９６％ぐらい。やっぱり９４％、できれば９２％、９３％ぐらいのパーセンテージに行ってほしいなというのが、発注側とすれば、そのぐらいの競争が行われるのが適正じゃないのかなと、予定の価格に対してなんだから。９５％をオーバーしている。１,０００万円まで下げてどういう数字がまた出てくるかというのもありますので、そのときにまた聞かせてください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":78,"id":"exchange-033"},{"speaker":"塚本委員","kind":"意見","question":"各区が事前公表をどの程度導入しているのかということと、今のパーセンテージ、他区がもっと低くなっているよという、制度がみんな同じかどうかわかりませんので難しいところですけれども、そういう声が聞こえてくるんですが、その辺のところは。","respondent":"西島経理課長","answer":"他区の状況ですけれども、品川区が一番先に事前公表を開始いたしまして、始めたときは他区は事後公表でしたので、それが現在見ますと１１区が事前公表に移ってきております。","voiceIndex":79,"id":"exchange-034"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1578#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":34562,"voices":82}},{"id":"h14-20020515-13","meetingId":"h14-cm05","date":"2002年5月15日","dateIso":"2002-05-15","committee":"清掃・リサイクル特別委員会","time":"午後１時０９分～午後３時２７分","status":"正式会議録","sourceType":"formal","overview":"清掃・リサイクル特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を57件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"須藤委員","kind":"意見","question":"このリサイクル率というのが仮の定義という説明で、これはどのあたりまで使われているのか、品川区だけの考え方か、一般に他の自治体でもこういう数値でカウントすることができるのかどうか。","respondent":"中山清掃リサイクル課長","answer":"例えば管路収集というのも、これは実は臨海副都心の事業系ごみを有明港へ管で経由しておるんですが、事業者としては別のリサイクルをやっていたり、要は事業系のリサイクルの把握ができないものですから、今回区で収集しているものということを中心に。","voiceIndex":5,"id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"それで、私はやはり拠点回収だとか、集団回収だとか、店頭回収も含めて、また私たちが自分の住んでいる住まいのそばで可燃ごみ、不燃ごみでいろいろ努力して意識啓発の効果もあって、随分出す側の意識も深まってきている、一定程度の影響や頑張りが見られるのではないかというふうに思っているんですが、そういう点で微増ではあっても増えているここのところをどうとらえたらいいのかなという。","respondent":"中山清掃リサイクル課長","answer":"廃棄物という大きな定義で言えば微増だということで、従来リサイクルは望ましいことですから、できるだけリサイクルに出してくださいという周知をし、このリサイクル量が増えること自体が望ましいというふうな、区としてもそういう認識を持っておったところですが。","voiceIndex":7,"id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"今回はできなかったわけですから、そこまでちょっと手を広げるということがなかなかできなかったので、その辺の当委員会の役割として位置づけていきたいなというふうに思っておりますので、もう少し早い時期に発言し、運動的に行動できればよかったんですけれども、この時期に来ておりますけれども、ちょっとそのことを思っておりますので。","respondent":"中山清掃リサイクル課長","answer":"それで、こういう発生抑制になりますと、区民だけではなく、事業者、それぞれいろいろなところでの役割ということもあろうかと思うんですが、これも区でできるチャンネルの中では、働きかけというのは常にいろんな場面の中で、２３区で一体であったり。","voiceIndex":9,"id":"exchange-003"},{"speaker":"南委員","kind":"質問","question":"さっきちょっと当初に言っておけばよかったんですけれども、ここは区で収集している量の数字の推移だけを示していただきましたが、事業系のごみというのはどの程度かというのは、もしわかっている範囲で推移がわかれば、これと比較して、私がちょっと質問したかったところもはっきり受け取れないのかなと思うので、もしわかったら教えてください。","respondent":"中山清掃リサイクル課長","answer":"実は、いわゆる事業系ごみの把握というものが、ちょっと区に清掃事業が移管されておりながら、区内のほんとうの事業系のごみはどうなっているかが明確に把握できないというのが一つの区の清掃事業の課題だという認識は持っております。","voiceIndex":11,"id":"exchange-004"},{"speaker":"北野委員","kind":"質問","question":"この不燃ごみなんですけれども、最終的には不燃ごみを京浜島のところで、今のお話の中だと一部分けられるものは分けているということですけれども、大体どういうものが主に分けられるのかというのと、これは全体だから、２３区全体の量的な割合になってしまうと思うんですけれども、不燃ごみの中から資源ですとかそれぞれの量というんですか、大体２３区全体で。そういう割合というのは出ているんですか。","respondent":"中山清掃リサイクル課長","answer":"アルミについては結構単価が上がっている。そのほか、瓶も機械的に色によって選別できるようになっていますから、これもリサイクルに回るようにやっております。ちょっと量は申しわけございません、別途お示ししたいと思います。","voiceIndex":13,"id":"exchange-005"},{"speaker":"北野委員","kind":"質問","question":"やっぱり燃えないごみは、トレーもあれば、ペットボトルも入ってしまう。私たちがどういう形でリサイクルをしてきたら、ほんとうに身近なところから。だから、資源回収が増えて、店頭回収が増えて、その分総体的には税金もかかっていく。もう一つの四つもあるんですよということをどこかで知らせていくべきじゃないかなと思うんですけれども、そういう考えはいかがですか。","respondent":"中山清掃リサイクル課長","answer":"むしろリデュース、発生抑制の中に、もともとごみになるものを断るということも概念としてあるんではないかということなんですが、具体的にどうやればいいのかということをお示しするという中に。","voiceIndex":15,"id":"exchange-006"},{"speaker":"北野委員","kind":"意見","question":"いつも四つ目のＲということで、この中で発言させていただいていますけれども、ほんとうにそれが行政もそうですし、私たち自身も考えていかなくちゃいけないことだというのは重々わかっていますので、ぜひよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":17,"id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ここにはリサイクル率ということで書いているんですけれども、例えば資源回収されるペットボトルだとかいろいろありますけれども、その中で、そういう資源回収のものが実際にどれくらい回収されているかという回収率みたいなものは区としては出せるんでしょうか。","respondent":"中山清掃リサイクル課長","answer":"ただ、もちろんこれは１％でも上げ、ごみにしないのが原則だという認識は持っております。","voiceIndex":18,"id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう中で、品川区もこれからさらにごみを減らしていくということから考えると、私なんかもいつもごみを捨てるときに、いろんな容器包装リサイクル、そこら辺のところがもうちょっと徹底されたら、ごみはかなり減るんじゃないかなというふうなものを常々感じているんですけれども、名古屋なんかでは、そのプラスチックにしても、それから、紙製にしても。","respondent":"中山清掃リサイクル課長","answer":"品目については、そういった意味で検討は、今後どういうことができるかということは考えてまいります。","voiceIndex":20,"id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それとあと、前に、この間の予算特別委員会のときに飯沼委員のほうから、１人当たりのごみの量ということで、１日１人当たり８００グラムということでご答弁いただいていますけれども、この８００グラムの中なんですけれども、これは事業系とか、それから家庭内のごみとか全部合わせてということなのか、そこら辺のちょっと内訳について、どういう状況なのかをお聞かせいただきたいんですけれども。","respondent":"中山清掃リサイクル課長","answer":"１人当たりの廃棄物の量が約８００グラムというのは、区で収集しているものからしか把握ができませんものですから、基本的には家庭系のものだというふうにお考えいただいて結構です。","voiceIndex":22,"id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ということは、家庭と小規模の事業者の合計を人口で割ったというようなことでとらえていいかと思うんですね。そうすると、それが８００グラムということで、あとは事業系としてはどれぐらいかというのは数字として出ているんでしょうか。","respondent":"中山清掃リサイクル課長","answer":"事業系のごみの１人当たりどうかという計算すること自体がどれだけの意味があるかということはありますが、そういう統計はとってございませんが、さっき申し上げた２３区で清掃工場に持ち込まれているような、そういった一般廃棄物で言いますと。","voiceIndex":24,"id":"exchange-011"},{"speaker":"堺委員","kind":"質問","question":"先ほどのご説明の中であったのかもしれませんが、参考までに。２番目の資源の回収量の中の拠点の回収等については年々回収量が減っていますが、これはその分店頭回収とか集団回収が増えてきたので拠点の回収が減ってきた、こういう理解ですか。あるいは拠点の回収の場所、形が減ってきたのか。この辺の関連を参考までに教えていただければと思います。","respondent":"中山清掃リサイクル課長","answer":"これもちょっと拠点回収等の等のところに幾つかあるということが説明が抜けておるんですが、一番典型的なものは、空き瓶ポストというものを従来設置しておりまして、大規模集合住宅、あるいは八潮地区等に設置しておったんですが。","voiceIndex":26,"id":"exchange-012"},{"speaker":"南委員","kind":"質問","question":"原価がどのくらいかかるかというところは関心のあるところでありますが、ここの時期に至ったというのを、ちょっとその背景というのかしら、担当課長会のところでそういう方向で計算しようよという共通の認識があって、こういう資料が提示されてきたのか、今何かその辺のところがちょっと私は十分理解、受けとめ切れなかったので、資料として提供してくださった、その背景を品川区段階の問題だけでなくて。","respondent":"中山清掃リサイクル課長","answer":"これは２３区の中で、区になったら全体像がわからないということではいけないんじゃないかということで始めようということを方針を決めた上で、そもそも今回の実績というか、実施自体がコストも含めて各区の執行になりますから、どこまでが清掃の経費であるのか、人件費も含めて。","voiceIndex":33,"id":"exchange-013"},{"speaker":"土井委員","kind":"質問・要望","question":"それから資源ごみにしても集め方が違うわけですね。集め方というか、やり方が。それも個別の車を使って別なルートで集めるというようなやり方ですから、コストが当然かかっているだろうと思えますね。そういうものが基準、当然それらも含めてこれは２３区ですから平均値という形で出てきたんだと、平均というか、トータルの形で出てきたんだろうな、こういうふうに理解しました。","respondent":"中山清掃リサイクル課長、松本環境清掃事業部長","answer":"そういった意味で、年度によって経常的なものというだけではなくて、例えばダイオキシン対策によっていろいろな排ガスに伴う工事を行う、こういったものを平成１２年度の中で行ったものは平成１２年度の中に入ってきておるですので。投資的経費のうち、減価償却と利子、これについては別途算定の形で入っています。土地については、これは控除をしています。","voiceIndex":35,"id":"exchange-014"},{"speaker":"土井委員","kind":"意見","question":"そこの算出によっては、一喜一憂していても何の意味もない中身にもなりかねない場合もあるわけで、要するに、先に工場を建てるということは、これから使っていくのに建てるわけですね。そうすると、その年にだけどかーんと経費が乗っかっちゃうというスタイルになるわけでして、今の状態がそうなっているということで理解してよろしいんですね。","respondent":"松本環境清掃事業部長","answer":"別途算入するというのは、年割に減価償却がきちんと計算をし直して、その年に算入をさせていただこうと。ですから、そのときにかかったものをそっくりそのまま計上しているのではなくて、いわゆる民間と同じような減価償却の計算方法を用いて、実際のコストを策定をしているです。","voiceIndex":38,"id":"exchange-015"},{"speaker":"土井委員","kind":"質問・要望","question":"そういうのがどれが適切なのか、どれがコストが安くて一番いいのか、コストの面ではこれがいいけれども、実態の面ではこちらがいいよとか、そういうメリット、デメリットも含めた啓蒙等も、このコストという面だけからでもやっぱり必要になってくるんじゃないかな、こんなふうに思うのですが、ここの中からそれは読み取れませんし、またそう簡単にデータが出るものではないと思いますので。","respondent":"中山清掃リサイクル課長","answer":"清掃工場等の件については、例えば新しい工場の建設等がまた平成１３年度等出てきますと、こういった部分も出てくるということで、どうしてもトータルの中でのコストにそういったものが反映されてくるという要素があるかと思いますので、品川区としては、今収集。","voiceIndex":40,"id":"exchange-016"},{"speaker":"須藤委員","kind":"質問","question":"単純なあれで。処理経費、ごみが少なくなってきているんだけれども、トータルとすると少し上がっていますよということはどういうことなんですか。","respondent":"中山清掃リサイクル課長","answer":"表をご覧いただきますと、処理量が平成１２年度に比べますと、収集運搬量で言いますと１８万２,０００トンと減っていますということですが、それに見合って、処理経費もそれぞれ収集運搬部門で、この表ですけれども３４億余、それから処理処分が５７億余、合計９１億。","voiceIndex":42,"id":"exchange-017"},{"speaker":"須藤委員","kind":"意見","question":"その辺なんですよね。結局処理量よりも経費が上回っているよということはどういうことなのか。経費がそんなにかかっている。これはもう落とし切れないことなのかどうなのかということです。その辺にまだ工夫のあれがあるのかないのかという。こっちは落っこってきて、それでごみ量の減ったぐあいに対して落ちてこないということは、何なんだろうと言っている。","respondent":"中山清掃リサイクル課長","answer":"とりわけ、これは、ちょっとこの表が冒頭申し上げたように中継輸送費の８５億というものは、平成１１年度と１２年度で扱いが変わっているものですから、収集運搬のほうがあまり減っていないように見えるんですが、実際には収集運搬の減が主というか。","voiceIndex":44,"id":"exchange-018"},{"speaker":"須藤委員","kind":"意見","question":"今言ったようなことになってきた、結果的にはこれだけ見ていてどうのこうのという話ではなくなっちゃうし、そうすると、もっと品川区自体で、うちの自治体としてはこういう数字になってくるよというと、そんなに大きな変動はないわけですよね。これはあくまでも２３区の平均だけを見て、一つの参考だよというふうに見ておくだけだね。そう理解していいね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":46,"id":"exchange-019"},{"speaker":"北野委員","kind":"提案","question":"これは個人的な資料、委員会に出せる資料でもあり、また区民に出される資料の中の１点としてもそういう比較ができることがいいのではないのかなということは提案なんですけれども、何か品川区としてはどうなんでしょうか。見れば、リサイクルよというのはわかるんですけれども、単価については、やっぱり出すべきじゃないかなと思うんですけれども。","respondent":"中山清掃リサイクル課長","answer":"これは総量でやればリサイクル品目のということで総額でも出せるんですけれども、そういう形で、これはほんとうに２３区でいろいろやり方が違っているものですから、各区の中で。","voiceIndex":47,"id":"exchange-020"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"さっきの須藤委員のほうの話の続きになってしまうんですが、この資料をつくったのは、清掃一部事務組合のどこでつくっている資料の一部なんですか。","respondent":"松本環境清掃事業部長","answer":"清掃協議会のほうで作成をしたものです。","voiceIndex":49,"id":"exchange-021"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"収集運搬量が。その逆の意味で、収集運搬事業が変わっているはずなのに、これが上がっているのでは何かおかしな資料になってしまう。ですから、これは資料として出すのだったら、これを処理部門の変更する前の数字を出しておいて、収集運搬したことにこれだけコストが下がったというのを出すのが区としての考え方じゃないかなと思うんですけれども、どうでしょうか。","respondent":"中山清掃リサイクル課長","answer":"これは先ほど申し上げたように、各区に中継部門が移管されたために、東京都時代と違う考え方にしたというのを注釈に書いておるんですが、確かに表としては平成１１年、１２年を、たまたまこの年度をこういうふうに比較すると誤解を招きやすいということで、補正計算してみますと。","voiceIndex":51,"id":"exchange-022"},{"speaker":"土井委員","kind":"質問・要望","question":"経済性の問題なのか、何性の問題なのかということだと思います。だから、そこら辺の選択肢がどうやって決められたのかというところが、やっぱり我々のこれからのごみの分別を含めた、要するにサーマルリサイクルをどこまで考えるかということのほうにつながるわけですけれども、その辺の発想が、だれがどんな形でいつやってこう決まったのというところを少しとりあえず聞かせていただきたい。","respondent":"中山清掃リサイクル課長、松本環境清掃事業部長","answer":"その中で炉を新しくし、自動化も図っていくという中で、現在の大井清掃工場もストーカ式ですので、そういった中で、ストーカ炉自体がある程度非常に安定的な燃焼が可能なものであるということを踏まえ、またプラント更新。プラスチックですけれども、基本的に、現在の性能基準から言えば、混焼については何ら支障はございません。","voiceIndex":58,"id":"exchange-023"},{"speaker":"土井委員","kind":"質問","question":"新しくプラントが更新をされるということですから、当然公害対策上の問題というものも出てくるでしょうけれども、今お話があったように、ごみの分別の仕方等々も含めて、逆の意味で、これがほんとうに生ごみばっかりになったときにはどうするんだということもあり得るわけですね。以上、とりあえず意見も含めて申し上げました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-024"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"１点だけ伺います。簡単な点なんですけれども、当初の計画で、この改修は３４０億ぐらい見込んでいたと思うんですけれども、これは今の状況、時点で金額的な変更はどのくらいですか。","respondent":"中山清掃リサイクル課長","answer":"実施計画の中では、一切コスト的なものは、この資料にありますように示されておりません。","voiceIndex":62,"id":"exchange-025"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"別はわかったんですけれども、契約自体は品川区ではないということにはなっているんですけれども、金額的なものとか、この実施計画、何かこれから品川区として物申すことができるのかどうか、その辺の状況はどうなんでしょうか。","respondent":"中山清掃リサイクル課長","answer":"今いろいろと地域処理の検討等しておるわけですが、そのいずれ品川区の施設になるという際に、財産も引き継ぎ、負債も引き継ぐということが十分あり得るわけですから、そういった意味では、こういう建設時から極力コストを下げて合理的にやっていくというのは。","voiceIndex":64,"id":"exchange-026"},{"speaker":"鈴木（真）副委員長","kind":"質問・要望","question":"重ねて申しわけないんですが、やっぱり品川区として、これはもう区の施設になっていくわけですから、いいものをつくってもらって負担を軽くするという考え方もあるかもしれないですけれども、ある意味品川区としてきちんとしたものを残していくといういただき方にもよろしくお願いしたいと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問","question":"環境保全のところなんですけれども、１項目から８項目ありますけれども、単純に土壌汚染のことが何でここにないのかなと率直に思っているので、その点についてと、あと最後の環境影響調査等のところに環境調査を行うと書いてありますけれども、この調査の時点とか拠点とか、その辺について教えてください。","respondent":"中山清掃リサイクル課長","answer":"今回の実施計画というのは、基本的にはせんだって当委員会等にもご説明した環境影響評価書案にかかる事項に伴う説明とは別ですので、従来環境影響評価においていろんな手順を踏んでご説明あるいはお示しした部分については、当然それに従ってやっていくということになります。","voiceIndex":67,"id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問","question":"環境調査を行う、このあたりの、いつなのか、どこの拠点で行うのかというのは決まっているんでしょうか。一番最後のところです。","respondent":"金井環境課長","answer":"前にご説明があったと思いますけれども、環境影響調査表というのが出ております。","voiceIndex":69,"id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問","question":"以前それもあったんですけれども、具体的に区内で拠点は何カ所ぐらいあるんでしょうか。特にダイオキシンの心配が強いんですが。","respondent":"金井環境課長、松本環境清掃事業部長","answer":"これは工場の影響範囲ということで、たしか数カ所やっていると思いますし、１.５キロぐらい離れた、西側のところで１.５キロぐらい離れたところで、それは随時公開しておりますからあれですけれども。それは、工場は一般的に基準を設けて、私は今ちょっと何点をやっているのかは記憶にないんですけれども、基準点を設けて年１回必ず調査を継続的にやっていますので、その辺の変化はとらえております。","voiceIndex":71,"id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問","question":"後でゆっくりそれは読むんですが、１.５キロメートルぐらいのところで１カ所、ほかには区内はないわけですか。具体的にどことどこで調査しているのかなというのがわかるとすごくありがたいなと思ったのと、あとこの実施計画に基づいて、新たに区内とか特に清掃工場の近くの八潮地域とかでこれに基づいて説明会が行われるのかどうか。その点を教えてください。","respondent":"中山清掃リサイクル課長","answer":"この更新事業の実施計画に基づいての地元説明等はございません。基本的な環境影響評価であるとか工事説明というのは別途行います。それは工事説明があるです。","voiceIndex":74,"id":"exchange-031"},{"speaker":"飯沼委員","kind":"質問","question":"炉ごとに調査がされる。すみません、区内の土壌調査の場所を知りたいんですけれども。後でもいいので、どこの場所でどう行われているのか教えてください。","respondent":"金井環境課長","answer":"環境課でやっているのは、例えば水質の調査ですとか、そういったことをやっておりますけれども、土壌というのは民間の敷地とかいろいろありますけれども、特別に公共の施設を、直接やるとすれば公共の施設になりますけれども、定期的にそういうことはやっておりません。","voiceIndex":76,"id":"exchange-032"},{"speaker":"南委員","kind":"質問","question":"やることはいいんだけれども、その後の先が進んでいかないために、どうしても途中でとんざしてしまう状況はありがちだと思うんですけれども、だから、そういう点で、例えばどこか処理した堆肥として利用できる、そういうものについて流れをつくっていくということは考えられないのですか。考えていないのかどうか。そこをちょっと伺いたいんです。","respondent":"中山清掃リサイクル課長","answer":"それで、やはりこれはごみを減らすという意味では一つそれだけでも意味はあるのかなと思うんですが、そこから先、その利用されるか否かについては、当面それぞれのご努力にゆだねたいと思っておるんですが、何年かやる中で。","voiceIndex":82,"id":"exchange-033"},{"speaker":"南委員","kind":"質問・要望","question":"やっぱりやっている人は、それなりの意識が高い方たちが多いと思うので、そういう点で、何だとまっちゃっているのかみたいなことだったら、何となくこうちょっと残念に思いますので、生ごみ処理の、この間モデルでやった、そういうあれをきちんとリサイクルのルートに乗せていくことを私も求めたいと思っているのと同時に、せっかくやっている。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-034"},{"speaker":"飯沼委員","kind":"質問","question":"電動式生ごみ処理機というようのが、半分の助成で上限２万円という、この辺の助成金額の基準というんですか、あと８０台、前回人気があったということで増えていますけれども、この辺の台数をはじき出す根拠というか、その辺と、あと裏面に行くと、コンポスト化の容器のほうの助成金額なんかも妥当なのかなといろいろ思うんですけれども、とにかくごみにしないで、ごみにならないで万歳と。","respondent":"中山清掃リサイクル課長","answer":"今年度はこのままの状況で、３年やった上で、いろいろとその後の対応について考えていきたいと思います。","voiceIndex":85,"id":"exchange-035"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私もぜひ生ごみのごみを出さない方法を、自分でも何か参加したいなと日ごろ思って、なかなか困難が多くてできないので、なるべくやりやすい方法でとは思っているんですけれども、とにかく参加者が増えるということと意識が高まる方向性を求めて考えていってほしいなと思います。そういった面では助成金額をもうちょっと上げても、すごい件数が今少ないですよね。利用されている方が。","respondent":"中山清掃リサイクル課長","answer":"利用者への意見ということにつきましては、今回も助成対象になった方については、その後、利用者の方にアンケート等をとることは考えておりますので、その中で先ほどの出口処理のことも含めたご意見等は聞いてまいりたいと考えています。","voiceIndex":87,"id":"exchange-036"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひアンケートなどで広く意見を求めていってほしいなと思いますけれども、コンポストのほうというのは、場所も問題だけれども、やり方が結構正しくやらないとなかなか難しいというのがあるので、やっぱりその辺、普及のためのご努力も必要かなと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-037"},{"speaker":"中島委員","kind":"質問・要望","question":"今は電動的はあくまでもごみを減らすという、生ごみを出さないからカラスにもやられませんので、そういった面では非常に便利で今家族も少なくなったせいか、ほんとうに毎日かけなくても十分快適な生活を送らせていただいているわけですけれども、やっぱり環境に優しいとか、そういった点では、コンポストをもっと皆さんが利用できるように工夫していただきたいなと思っているんですが、いかがでしょうか。","respondent":"中山清掃リサイクル課長","answer":"それで、コンポスト化容器について、減傾向の中で再検討の余地というのは私ども認識は持っておるんですけれども、片やおっしゃるように非常に環境負荷が少ない中でごみ減量が行われる、あるいは意識づけとしても望ましいものということはありますので。","voiceIndex":90,"id":"exchange-038"},{"speaker":"北野委員","kind":"質問","question":"そういうところの基準ですか、結局８０台以上多ければ、もし抽選であれば、既に買ってしまった方が漏れてしまったという場合もあるだろうし、それから既に購入していて、領収書もあるけれども、大体どれぐらい前までの期間のものなのかとか、やっぱりそういうのを含めて、わざわざ５番にこういうふうに入れたのかどうか。ちょっと細かいことですみませんけれどもお伺いします。","respondent":"中山清掃リサイクル課長","answer":"別に予定価格とずれたからといって、あるいはここの額の多寡で抽選を恣意的に操作する考えはございませんが、もう一つの要素として、事業用のものは別ですということがありまして、一応家庭用ですと、せいぜい安くても４万、３万何千円、購入額でいうとそれぐらいから。","voiceIndex":92,"id":"exchange-039"},{"speaker":"北野委員","kind":"質問","question":"わかりました。たしかそういうこともあったと以前報告で伺ったこともあります。いろんな会社の方が来て。だからそういう機会もとらえて、日程が合うので、要するに実際のどこのお店に行って決めようかなとか、カタログを見てというのはいろいろあるんですけれども、そういう機会もとらえて参考にいかがですかという言葉も入れていただけたらよかったなということを。","respondent":"中山清掃リサイクル課長","answer":"チラシには入らなかったことは申しわけございません。それで、後ほどご説明しようかと思ったので、環境・リサイクルフェアの中でもこの辺のご案内をして、目に見える形でご案内したいと考えています。","voiceIndex":94,"id":"exchange-040"},{"speaker":"南委員","kind":"質問・要望","question":"それと、あといろいろな内容豊かなクイズ形式というか、そういう形で積極的に認識が持てるような、そういう内容になっているので、非常にいろいろ工夫があったなということを思うんですけれども、また同時に子供たちの声だとか、そういう授業をする先生方だとか、そういう方々の声をこれからもいっぱい拾って、より豊かな内容にしていく必要があるんではないかというふうに思うんですが。","respondent":"中山清掃リサイクル課長","answer":"それで、当然作成するに当たっては、教育委員会、指導課等との連携をとってつくったわけですけれども、実際にこれの活用については、既に学校の先生方の勉強会の場面等でもご説明したところですが、使われてどうなのかという声については当然聞いてまいり、そこの中で。","voiceIndex":100,"id":"exchange-041"},{"speaker":"中島委員","kind":"質問","question":"地方に行くと、こういうごみのぱっと見たら百科事典みたいなものが出ていて、これは何はどこに捨てるとか、不燃ごみだとかリサイクルだとか、こういう仕分けができているようなものを出している自治体もあるようなので、これは非常に好評だというのをこの間も伺ったところなんですが、子供たちにもちろんこれを教えていくのは大事なんですけれども。","respondent":"中山清掃リサイクル課長","answer":"通常の分は、今お配りしている分け方、出し方を新たにつくる際には、そういうガイドを配る際の折り込み等をあわせて周知を図っていきたいと考えています。","voiceIndex":102,"id":"exchange-042"},{"speaker":"中島委員","kind":"質問","question":"ぜひお願いしたいと思います。私は今でも認識が弱いのかもわかりませんが、これを燃やしていいのかな、どうなのかなというのを迷う場合があるんですね。こういうマークがついている場合は燃やしててもいいだとか、明確に何か区民の方が覚えられるように、そういうものをある程度していただければありがたいなと思ったものですから、意見にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-043"},{"speaker":"土井委員","kind":"質問・要望","question":"それを大前提にいたしまして、これはつくられたのは、先ほどのカレンダーもそうなんですけれども、版権は当然区がお持ちだというふうに思いますが、ほかのところでそのままは使えませんけれども、アイデアは使えるものは使っていただけるんだろうと思いますので、ぜひこういうものをつくっているよという意味での、区内的なＰＲもさることながら。","respondent":"中山清掃リサイクル課長","answer":"端的に言いまして、約９５万円で１万２,０００部ということですから、税込みで約１部８０円弱の、単価になっております。","voiceIndex":105,"id":"exchange-044"},{"speaker":"北野委員","kind":"確認","question":"わりと小学生というのは、外であまり自動販売機を使って飲むとかというのはないかもしれないんですけど、中学生になると、結構行動範囲が広くて、そこでどんなものをちゃんと捨てるのか、そこにごみのところにリサイクルの缶とかボックスとかに直接捨てればいいですけれども、そういうところで。","respondent":"中山清掃リサイクル課長","answer":"いわゆる若い世代のうちにこういう環境意識、ごみ減量の意識を持つというのは、これは重要なことだということでまずねらいを絞ったのが小学生で、とりわけ先ほど申し上げたように社会科の中で、具体的に４年生にそういうごみについて考える単元がありますから。","voiceIndex":107,"id":"exchange-045"},{"speaker":"北野委員","kind":"意見","question":"そういう中では意識はされてきていると思うんですけれども、冊子ではなくても、何かこう簡単にわかるようになっているというところで、自分たちが学習の中で研究できるような材料として、何か使えるような資料としても提供があればいいんじゃないかなと思いますので、ぜひ研究をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":109,"id":"exchange-046"},{"speaker":"南委員","kind":"確認","question":"だから、表現が短いスペースで端的に物語らなきゃいけないのでこういうふうになっちゃったのかなと思うんですけれども、ちょっとこのところは性格からすると違うので、今さらあれなんですけれども、ちょっと違うのかな、訂正しておいたほうがいいのかなとちょっと思ったので確認をしていただいて、そんなことはいいや、不必要だというのであれば、それはそれでいいんですけれども。","respondent":"中山清掃リサイクル課長","answer":"ですから、そういった意味では、直接工場そのものが高温水をつくるプラントではないと言いますけれども、工場でできた電気という表現をもしするとすれば、同じように熱を燃やしたものを使って発電したり、そういう確かに水分を加えてという形になるんですけれども。","voiceIndex":110,"id":"exchange-047"},{"speaker":"南委員","kind":"質問","question":"だから、訂正する必要がないという見解であれば、それはそれで荒立てるつもりは全くないし、問題視するつもりは全くないんですけれども、だから。だから、違うんじゃないかというふうに思うんですね。お湯で来ているわけではありませんから。熱で来ているわけですから。それでいいということであれば別にいいと思いますけれども、ちょっと気になったので言いました。","respondent":"中山清掃リサイクル課長","answer":"高温水という言葉自体が難しいということは、確かにそういう面はあろうなとは、今伺って認識しました。","voiceIndex":114,"id":"exchange-048"},{"speaker":"南委員","kind":"意見","question":"仕組みはこれでいいんだろうと思うんですけれども、そういうふうな誤解というのをちょっと与えるという危惧があったので、全然問題ないよということであれば、それはそれで別にいいんですけれども、また改めてちょっと説明を要するということであれば、そういうふうに対応していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":116,"id":"exchange-049"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"学校の副読本としてお使いになるということの中で、これが継続的に使うのではなく、その中で、例えば授業の中で１時間なら１時間で終わってしまうと思うんですよね。例えば子供がやれば親はやらなきゃいけなくなってしまうという面があると思うんですよね。そういう意識づけのためにも、ぜひ教育委員会の、利用はできないのかなと。前の部長もいらっしゃいますし、その辺どうでしょうか。","respondent":"中山清掃リサイクル課長","answer":"こういう、これだけでなく、いろいろ環境清掃事業部等で用意している環境への取り組みについて、今後教育委員会にＩＳＯとの関係もあって、環境学習プログラムということで、各先生方が利用できるような資料もあわせて配っていくことになっておるんですが。","voiceIndex":117,"id":"exchange-050"},{"speaker":"鈴木（真）副委員長","kind":"質問・要望","question":"ぜひそれは利用していただきたいと思って。要望しておきます。","respondent":"高木委員長、中山清掃リサイクル課長","answer":"なければ、５番目の項は終了します。これをもちまして、報告事項は終了します。その他に移りまして二つほどご報告がありますので、１環境・リサイクルフェアの実施について、ご説明をお願いいたします。表にも例示が書いてありますが、おめくりいただきますと主な内容が記載されてございまして、清掃・リサイクル関係の品物の展示。ご説明をいただきました。ご質疑がございましたらお願いをいたします。どなたも発言がございませんか。","voiceIndex":119,"id":"exchange-051"},{"speaker":"南委員","kind":"質問・要望","question":"ですからそういう点も、今まで聞いてはいても、なかなかこういう事故になっていないから、多少もう使い切っているつもりだから大丈夫だみたいな、ちょっと安易な意識がなくもないわけですから、ちょっとその辺の周知というのかしら、その辺をどういうふうに、原因究明が先ですけれども、考えていただきたいということをちょっと改めて。ご答弁はいいんですけれども、お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":127,"id":"exchange-052"},{"speaker":"土井委員","kind":"質問・要望","question":"まさしく原因究明が必要なのは事実なんですけれども、現実問題、この種のものが起きる可能性ありということについては、前々からそのスプレー缶なども含めた、それでなくてもいろんな、漏れた油などにコンベヤーの摩擦等や油ぎれで熱を持って発火するとか、ぼろ布が発火するとか、そんなのはいろいろあるわけですから、そういうものに対する対応、対処等がもし不十分だということになると。","respondent":"松本環境清掃事業部長","answer":"それと、先ほど５億ないし６億の被害総額を申し上げましたけれども、当然これは消防庁のほうから改善命令が出るだろうと考えています。","voiceIndex":131,"id":"exchange-053"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"死傷者が出たのに申しわけない話かもしれないけれども、この改修に対して費用がかかってくる、これは火災保険みたいなものに入っていて、その分というのは負担はできるんですか。それを１点教えてください。","respondent":"中山清掃リサイクル課長","answer":"しかしながら、部長も答弁申し上げたさらなる改善、設備改善の部分等になると、この経費はまた別途清掃一部事務組合として出てくる可能性はありますが、基本的には保険で現状復帰可能というふうに我々は伺っております。","voiceIndex":133,"id":"exchange-054"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"もう１点ちょっと。大田のこれは不燃ごみをここを使っているわけですよね。大田区のほうの。今そこが使えないと、中央防波堤に持っていくというのは、東品川の中継所から持っていっているんですか。それともトンネル、新しくできた向こうから行くのか。それはどうなんですか。","respondent":"中山清掃リサイクル課長","answer":"先ほど申し上げたように、京浜島不燃ごみ処理センターには、大田区が３清掃事務所がありますが、これは直接車で運び込んでいるものが１３４トン毎日あります。","voiceIndex":135,"id":"exchange-055"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ノーレジ袋運動について、９月か１０月かぐらいから実施するというような方向だと思うんですが、いろいろ検討中だと思うんですが、その後、ここの所管かどうかちょっとはっきり。ここの所管ではない。ごみを減らすというところでリサイクルで関連しているので、そこら辺のところの状況がちょっとわかったら教えていただけるのかなというふうに思いましたんですが。","respondent":"金井環境課長","answer":"今お話がございましたように、これは所管が区民委員会ですので、まだそういう段階に至っておりませんが、区民委員会のほうに先に報告した後に、こちらがごみの減量という形で報告のようなつながりになってくるかと思います。","voiceIndex":139,"id":"exchange-056"},{"speaker":"鈴木（真）副委員長","kind":"提案","question":"本年１年間、清掃・リサイクル特別委員会の副委員長を受けさせていただきまして、ありがとうございました。１年間委員の皆様、理事者の皆様、事務局の方々に大変お世話になりまして、ありがとうございました。一言、最後に１回委員会を追加させてしまったというのが、自分のほうで提案させていただいて、２月に１回入れさせてもらっちゃいました。ありがとうございました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":143,"id":"exchange-057"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5662#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=13&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":46149,"voices":146}},{"id":"h14-20020515-14","meetingId":"h14-cm05","date":"2002年5月15日","dateIso":"2002-05-15","committee":"行財政改革特別委員会","time":"午後１時０８分～午後３時１２分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"桜井委員","kind":"質問・要望","question":"４点ほどちょっと質問しますが、一つは３ページの情報公開システムの特徴のことなんですけど、他の区はほとんど情報は無料ですよね。いろんな情報をね。最後に、こうした情報がいろいろ入るわけですから、新たに保護というのは個人保護というか、プライバシーの保護とか、そういう点なんかはどういうふうに考えられているのか、ちょっと大ざっぱなんですが、お伺いします。","respondent":"田中情報システム課長","answer":"情報公開手続の部分ですが、改善の余地があるかということなんですが、基本的に検討に当たりまして、情報公開の個々の件名の文書等を公開するわけではありませんので、現在でも情報公開の窓口ではファイル基準表というのをずっと置いておりまして。","voiceIndex":6,"id":"exchange-001"},{"speaker":"桜井委員","kind":"質問・要望","question":"だから、非常に情報公開の手続を、来て、３００円払うという、そういう取り方と、インターネットでどんどんとれるのと、すごくアンバランスというんですか、なんか全然脈略がないというのか、だから、そういう点で、私はもう一回きちっと整理をし、もっとより情報の公開を求めたいというふうに思うんですけど、そういう点での改正の余地があるんじゃないかということです。","respondent":"田中情報システム課長","answer":"先ほど言いましたように、ずっとこれをやり続けると、どうも圧迫感があって、何かどうなんだというようなことがあると思いますが、これはこれだけに限らず、仕事の部分やなんかでも、それなりに気晴らしだとか、ストレスの解消等ないとつらい部分があると思いますので。","voiceIndex":8,"id":"exchange-002"},{"speaker":"桜井委員","kind":"質問・要望","question":"もちろんそれらに基づいて情報公開するわけですから。それからもう一つは、最後の住民サービスの関係ですけども、これからの課題だと思うんですが、この部分について、直接やっぱり住民への意見を聞くというんでしょうかね、どういう点でそうしたサービスの分野で情報が欲しいかという点で、ある面では住民システムということからも出発しているんではないかというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-003"},{"speaker":"嶋委員","kind":"質問・要望","question":"すごい基本的なことなんですが、まず機械を見せていただいたんですが、富士通。全部、庁内ＬＡＮは富士通ですか。それからあと、全部質問申し上げます。それとあと、３ページの、先ほどもありましたけど、情報の共有化、キーワードじゃなくて、セキュリティを考えて、職員が閲覧した場合は、閲覧した履歴情報を記録するとありましたけど、これはどういう形で記録をされていくのか。","respondent":"田中情報システム課長","answer":"公開端末、家にインターネットやパソコンを持っていない方たちに対する対応を含めまして、２４時間、土曜日や日曜に空いている施設ですとかを含めまして、置くところを十分検討していきたいというふうに思っております。","voiceIndex":11,"id":"exchange-004"},{"speaker":"嶋委員","kind":"質問","question":"さっきのだれがというのがまだわからないことと、それと、役所の中でどこのほうに、いわゆる自由に使える場所が設置されていくのか教えてください。","respondent":"田中情報システム課長","answer":"どこに公開端末を置くんですかというところは、区民にとって利便性の高いところを検討していくという基本的な考え方で、いろいろな施設予約等を含めまして対応できるように十分検討していきたいと考えています。","voiceIndex":13,"id":"exchange-005"},{"speaker":"嶋委員","kind":"質問","question":"このＩＤ・パスワードを持っている人というのは、限定をされているということでしょうか。","respondent":"田中情報システム課長","answer":"ＩＤ・パスワードは個々人に振られています。今区役所ですと、２,２５０人程度ＩＤ・パスワードが配布されております。その人たちは自分の独自のもので入りますので、ちょっと現業系等、まだ振っていないところがあります。","voiceIndex":15,"id":"exchange-006"},{"speaker":"嶋委員","kind":"確認","question":"わかりました。じゃあ、２,２５０人の人が大体持っているということで、これは人のパスワードを知らないということを前提としているということで了解をしてよろしいんでしょうか。もし、私たち仲間は意外とわかっている場合があるじゃないですか、お部屋の中で。あの人のパスワードは幾つと。そういう場合なんかはありますよね。そういうことがあるのかないのかだけ、ちょっと確認をしておきたいと思います。","respondent":"田中情報システム課長","answer":"基本的にＩＤ・パスワードは個人を認識するものですから、これは必ず人には秘匿して、自分の、例えばキャッシュカードの暗証番号を人に教えないのと同じように、ＩＤ・パスワードは人に教えないということが前提ですので、個人を識別する手段になりますので。","voiceIndex":17,"id":"exchange-007"},{"speaker":"田中委員","kind":"質問","question":"４ページ目のシステム開発の効果と経費のところですが、効果の考え方として、財務会計で９億６,０００万円ほど、文書で４４億円、勤怠管理で５億８,０００万円ほどの減額等、それぞれ平成２２年までの合計と、短縮される時間が省力化されると載っておりますが、時間はわかるんですけど、この金額はまずどういう形ではじき出されたのか、それにかかる、それぞれの時間が省力化されて。","respondent":"田中情報システム課長","answer":"前提として、大体このシステムを利用する対象職員を事務職員と、それから技術系の職員、あわせて１,６００人程度というふうに想定しております。年間稼働日数がそれぞれ職員の２２４日として、１人当たり年間稼働時間１,５６８時間ということで計算しております。","voiceIndex":20,"id":"exchange-008"},{"speaker":"田中委員","kind":"質問","question":"そうすると、当初の初期投資の分と相殺されて、さらにそれぞれの効果が出るという考え方ではなくて、投資の部分は投資で経費として別にかかっているということで、トータルでの効果ということではないということですか。いずれ数字を出される予定とか。","respondent":"田中情報システム課長","answer":"定数減による効果と作業数、作業の工程等がなくなるとか、それから帳票等がなくなるとかというところを含めまして、最低限これぐらいが事業を実施した場合、最低限の効果はこれぐらい出るということです。システム開発の初期投資の部分は、３億円強の部分であります。","voiceIndex":22,"id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"ですから、経費としては１億２,０００万円毎年かかるけれど、それに上乗せして、この金額がかかるのではなくて、これがかかりながら、省力化によるプラスはかかるということで、切り離して考えるという、全くこれぐらいの金額がという理解でよろしいんでしょうか。","respondent":"田中情報システム課長","answer":"共同開発、共同運用の面では、一昨日に東京都と都下の市区町村で共同開発、共同運営の準備会を発足させました。これは電子調達の関係、それから電子申請、電子届出の関係、それから統合型ＧＩＳの関係を開発課題とした検討を進めるということでやっております。","voiceIndex":24,"id":"exchange-010"},{"speaker":"田中委員","kind":"質問","question":"そこのシステム等の再構築のところなんですが、先ほどのように小型のサーバーが開発されて、そういうものを利用して、あとＷｅｂを利用して再構築をしていくということでありますが、先ほど嶋委員がおっしゃられたように、富士通のシステムが、メーカーにおいては富士通のシステムなんですが、今後こういう再構築するに当たっては、既存の財産といいますか。","respondent":"田中情報システム課長","answer":"ただ、今後のことを考えますと、業者の競争環境を担保するという意味で、できるだけ標準的なものを入れて、次の世代の段階では多くに競争できるようなところに移行していけばと思うんですが。","voiceIndex":26,"id":"exchange-011"},{"speaker":"田中委員","kind":"質問","question":"ちょっと脱線してしまうんですが、これだけ区長部局と議会は車の両輪と言われておりますので、区長部局の情報といいますか、情報システム課がどんどん大きくなっていく中で、両輪である議会側の考え方というんでしょうか、それはぜひ再考し得るような構築を将来的には考えていきたいなと考えています。その辺の考え方だけちょっとお聞かせください。","respondent":"福田区議会事務局長","answer":"こちら本格的なシステムをスタートするという段階ではありますけれども、事務局として、どのような対抗が考えられるか、それは十分検討に値するというふうには考えております。","voiceIndex":28,"id":"exchange-012"},{"speaker":"辻副委員長","kind":"質問","question":"こんな字を使うの。何か違和感を感じるよね。これはその入り口を絞ればバーッと絞れるなという、そういうのでやれば、よりオープンな形の一般競争というものに対して参加を呼びかけていくというか、そういう何も研究という、まさしく私は、これから進む電子自治体という方向へ行くべきだと思うんですけど、その辺の今課題になっているというのはどの辺のことで、今後やっていくんですか。","respondent":"田中情報システム課長","answer":"２点あるかと思いますが、最初のネットワーク部分は、庁内と出先を含めて、すべての出先をネットワークで結んであります。庁内の特に第一庁舎については古い建物なので、なかなか有線のケーブルが引けないというところがありますので、無線ＬＡＮで第一庁舎はやっています。","voiceIndex":30,"id":"exchange-013"},{"speaker":"辻副委員長","kind":"質問","question":"もう一つ、先ほどから何件か出ていますけど、電子決裁での日常的な執務の内容の中なんですけど、今ワープロが入ってきたり、パソコンの時代に移ってきたわけですけど、職員の皆さん方がそれの流れの中で、要するに文書をつくって、今は事業部になるんでしょうか、前は一つ一つの部、あるいは課長単位でいろいろ集まって、いろいろやりますよね、日常的な、この事業はどうしようかとかというときに、それを。","respondent":"田中情報システム課長","answer":"執務のイメージですが、今でもイントラネットを入れまして、各課でいろいろ検討する際に共有フォルダというのがありまして、その文書の大きな保管庫みたいなものをコンピュータ上持っていまして、それで係員、課長を含めまして検討した内容を次々に入れていく。","voiceIndex":32,"id":"exchange-014"},{"speaker":"辻副委員長","kind":"質問","question":"いわゆる電子会議室というのはわかるんですよ。私もやっていないわけじゃないし。そのときに、ディスプレーを一つ持ってきて、まさしくそれは無線ＬＡＮであれば、全部８人、８人、１０人と持ってこれるわけですよ。これはこう思いますと。これを説明しながら、これはこうして文書をひょっと直そうかというのを、そういう会議室というのはあるべきじゃないんだろか。それが、どうなんですかと聞いているわけ。","respondent":"田中情報システム課長","answer":"各自のパソコンを持ってきて会議をやるという、できるように、この部分を無線ＬＡＮのときに検討したんですが、機能としてはローミングという機能で、それぞれどの階に行っても、持っていってもできるような機能があるんですが、ただそうすると、いろんな回線の容量ですとか。","voiceIndex":34,"id":"exchange-015"},{"speaker":"辻副委員長","kind":"質問・要望","question":"要望で終わりますけど、基本的には我々所管の委員会としては、行政改革の特別委員会ですので、費用対効果というのを考えなきゃいかん。今、今日ですか、有楽町でビジネスショーをやっている。そういうふうになってきたときに、民間企業から見たときに、何だと言われないようにやっていくだけの、やっぱりそういう感覚というのはぜひ持っていただきたいなと、これは要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-016"},{"speaker":"鶴委員","kind":"質問","question":"一体どうなっているんだ。４０分間ぐらいは何とか蓄電池で発電して、瞬時にデータが滅失しないように対応する。果たして４０分間で対応できるのかということもあるし、まず、危機管理というのは一体どうなっているんだ。そういう中で、果たして、その電子データというのは守られるのか、破壊工作に、破壊工作員がもし入ったとしたら、どう対処していくのか。どうなっているんですか、今の段階で。","respondent":"田中情報システム課長","answer":"すぐ地下の警備の人が飛んで来るという形になっております。その点で、最大のところでは、２４時間、その部分では入退室管理を続けているということで対応しております。","voiceIndex":37,"id":"exchange-017"},{"speaker":"鶴委員","kind":"質問","question":"それはそうだろうと思いましたが、問題は、そのセキュリティのマニュアルというのがしっかり守られているかどうかと、日常的にね。だからあえて聞いたんですね。このパスワードはだれだということがわかるけど、そういう場合は、どういうペナルティーがかかることになるわけですか。今の公務員法、地方公務員じゃなくて、あるいは国家公務員法の言うところの、どこが、何が適用されるわけですか、その人は。","respondent":"田中情報システム課長","answer":"例えば、契約の予定価格があります。これは決裁ルートの人は見ますけど、ほかの人は入札が終わるまで見てはならないし、見る必要もないわけですので、当然所属ですとか、その人の職ですとかに必要に応じてアクセス制限をするということで対応していきたい。","voiceIndex":39,"id":"exchange-018"},{"speaker":"金高委員","kind":"意見","question":"先ほどの設定の中で、ウイルスのチェックをざっと言われましたけども、これは今までそういうウイルスが侵入したということがあったのかどうか。それから、これからどんどん技術が発展していきます。そういったところから侵入経路が複雑になっているということですので、技術がこれから進歩していけば、それに対するウイルスのチェックをもっともっと厳しくしなけりゃいけない。見通しをお聞かせください。","respondent":"田中情報システム課長","answer":"システムの侵入の部分ですが、今まで、例えば１月に１０件ぐらいウイルスをはじいている履歴録があります。ですから、外から来るものはファイアーウォールで全部はじいて、その記録は残っています。","voiceIndex":41,"id":"exchange-019"},{"speaker":"辻副委員長","kind":"質問・要望","question":"どうも、この１年間ありがとうございました。今後とも、また行財政改革、さまざまな課題に取り組んでいただきたいし、また、我々もやっていきたいと思います。ほんとうに１年間ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5706#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":25545,"voices":47}},{"id":"h14-20020515-16","meetingId":"h14-cm05","date":"2002年5月15日","dateIso":"2002-05-15","committee":"街づくり特別委員会","time":"午後１時０４分～午後３時３８分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"上山委員","kind":"質問・要望","question":"ちょっと二、三、最初に基本的なことをお尋ねしたいんですけれども、前回もちょっと伺ったかと思うんですが、４街区全体にかかる区の方針区域という言葉を使っているわけですが、それから整備計画区域、中地区で言えば、今度は何というのか、いろいろな言葉が錯綜しているようなんです。それを最初に、ちょっとお願いいたします。","respondent":"南雲都市開発課長","answer":"再開発の地区計画というのは２段階になっておりまして、まず、土地利用の方針ということで、今後、こういう区域の土地利用をどういう方向に誘導していくのかということで、用途ですとか、どのような機能を持ってくるのか、こういう方針をまずある程度の広い範囲で定めます。","voiceIndex":6,"id":"exchange-001"},{"speaker":"上山委員","kind":"質問","question":"何せいろいろな名前がついていてよくわからない、違いなどがよくわからなくなりまして、失礼いたしました。それで、最初に二つお尋ねをしたいんですが、あまり長くはなりませんので。それから、もう一つなんですけれども、遠いところに一番最初に網をかけるというんですか、実際に進めていく上で、妥当性というか、整合性というんですか、そこら辺はどうなんでしょうか。ちょっと２点、お願いしたいんですが。","respondent":"南雲都市開発課長","answer":"先ほどありましたように、ここはやはり幹線道路、１６３号線の奥まったところにありますので、奥にある中地区だけ先行しても駅にアクセスすることができませんので、こういう周辺の基盤の整備についてめどが立ちませんと、中地区だけでは整備が進められないということで。","voiceIndex":8,"id":"exchange-002"},{"speaker":"上山委員","kind":"質問","question":"これで終わりにいたしますけれども、以前、これも一度伺ったことがあるんですが、再開発を進めていく上では、大きなネックとして保留床の問題があると、課長がどこかでのあいさつの中で一度触れたことがあるかと思うんです。私どもも一度質問したことがあるんですが、特に中地区の保留床について、買い手が決まったのかどうか。これで質問を終わりにいたします。","respondent":"南雲都市開発課長","answer":"そのうち、準備組合に加入てしておりますのが７６権利者でございまして、未加入が８権利者ということで、約９割の権利者が準備組合に加入しているという状況です。","voiceIndex":10,"id":"exchange-003"},{"speaker":"藤田委員","kind":"質問","question":"以前から西口につきましては話がありまして、ようやくここまで来たなという感があるんです。やっぱりまちをつくるには、人が集まって来なければあまり意味がないまちになってしまうんではないかということで、この地域の個性、特性は一体どういう。その辺を、まずちょっとお伺いしたい。交通広場の機能について、ご説明いただければと思います。","respondent":"南雲都市開発課長","answer":"バスにつきましては、具体的にどのような路線が入るかはまだ協議をおりませんが、機能としましては、バス、タクシーを対象にした施設を考えているです。","voiceIndex":12,"id":"exchange-004"},{"speaker":"藤田委員","kind":"質問","question":"だた単なる広場をつくって、人を集めて何かイベントをやるということだけはなくて、そういうのがあるかどうかという質問なんです。それにしたがって、例えば夜、イルミネーションをどんと張るとか、周辺に彫刻の小道にして、いろいろところから大崎に集まってくるというような、そういう人の集まり方の計画があるのかとお聞きしているんです。","respondent":"南雲都市開発課長","answer":"西口につきましても、単なるオフィスだけではなくて、ショールーム的なもの、人を呼ぶような施設ということも考えられるのではないかということで、具体的には、今後、各事業者と協議していきたいと考えております。","voiceIndex":14,"id":"exchange-005"},{"speaker":"藤田委員","kind":"質問","question":"目黒のアトレが、つい先日、完成しましたね。ですから、こういうまちづくり、再開発というのは、業務棟、住宅棟は確かに必要ですけれども、いろいろなところからまちに呼ぶという、レジャー施設も含めて、若者がすっと集まって来れるようなまちづくりを目指さなければ、今回はほんとうに概略の都市計画の話ですけれども、今のうちからそういう検討、話し合いをぜひお願いしたいなと思っているんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-006"},{"speaker":"上山委員","kind":"質問・要望","question":"１点だけなんですけれども、今度、東口第３地区ということですが、１ページを見ると、相当あちこち色がかかって大変驚くというか、この前、一つ説明がありましたが、大変大きな計画もあるんだなと思うんですが、これは置いておいて、今後、進めるべきお願い、要望みたいなものがあるんです。そこら辺の思いといいましょうか、一言あれば、何かお返事していただければありがたいんですけれども。","respondent":"南雲都市開発課長","answer":"今後も、細かく話をお聞きして、その方の意向がそういうことであれば、その意向がかないますように、十分な対応をしていくように、組合に対しても、区のほうから、今後も十分な指導をしていきたいと考えております。","voiceIndex":21,"id":"exchange-007"},{"speaker":"本田委員","kind":"質問・要望","question":"人の流れも、最近では大変多くなっているんです。当然、自動車や人の流れ、トリップ調査などをやっていると思うんですけれども、どんなふうに変化していくのか、あの商店街の交通渋滞などをどういうふうに緩和を図っていくのかなど、そういうことを含めて、本開発にあわせて、近隣との調和がどういうふうに検討され、今、進められようとしているのか、もしわかれば教えていただきたいと思います。","respondent":"南雲都市開発課長","answer":"青物横丁の駅からこのシーサイドフォレストまでの歩行者のルートというものを魅力あるものにしていこう、それから、シーサイドフォレストと青物横丁の間にあります接続点の部分には広場に設けて、人のたまり場になる、人を集客するような施設をつくるということで。","voiceIndex":27,"id":"exchange-008"},{"speaker":"本田委員","kind":"質問・要望","question":"もしそういう調査をやっているのであれば、教えていただきたいと思うんです。その努力の成果も、具体的な形であらわれつつあるということも聞いております。地域では高齢化が進むなど、やっぱり地元、地域の商店街というのは、一方ではその必要性が増しているわけです。ですから、人の流れがどう変化するのか、具体的にそういう数字を示していただきたいと思うんですが、出ているのか、出ていないのか。","respondent":"南雲都市開発課長","answer":"この開発に先立ちまして、車、それから人、それぞれ開発に伴ってどのような発生、集中の増があるのかにつきましては、調査をいたしておりますが、ちょっと整理させていただきたいと思いますので、次回、ご説明します。","voiceIndex":29,"id":"exchange-009"},{"speaker":"本田委員","kind":"質問・要望","question":"個別といいますか、今回、委員になっている皆さんにも、個別に示していただきたいということを、とりあえず要望しておきたいと思います。そういうことを含めまして、乖離した形の開発ではなくて、いかに地元の努力が実る、調和がとれたまちがこの一帯にできるかということを、行政サイドとしても、相当努力していただきたいということを要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-010"},{"speaker":"築舘委員","kind":"質問","question":"そんなことで、この駅ができることによって、交通広場があるわけですから、品川駅に行くバス、また大井町駅に行くバス、大井競馬場と品川の海岸通りのバスもありますけれども、それは一たん交通広場のバスの停留場にとまって、そして行くということだと思うんです。その辺の都のバス路線の計画というのは、いつごろ、どういうふうな形で、またどういう連絡が来ているかどうか、そこがわかれば教えてください。","respondent":"伊佐都市計画課長","answer":"交通局はその方向で検討しているですが、どういう形で出てくるかという具体的なことは時期とか、流れについては、ちょっと詳しい情報は来ておりません。いずれにしても、品川シーサイドの広場に八潮から乗り入れるバスについては必ず実現する。","voiceIndex":33,"id":"exchange-011"},{"speaker":"築舘委員","kind":"質問・要望","question":"単に、需要がないからと減らしたということなんですが、その後の推移ということで考えれば、需要が増えれば、またバス路線も増やすということも可能になってくるわけですから、そこのところをよく、品川区としての要望といいますか、この地域の思いというのを伝えておいていただきたいということで、要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-012"},{"speaker":"上山委員","kind":"質問","question":"今回の二期工事に直接でないんで、それとの係わりで幾つかお尋ねしたいんです。最初にこちらを伺いたいんですけれども、前に説明があったかもしれませんし、私が聞き漏らしていたら申しわけないんですけれども、整備の計画、例えば駐輪場などを含めてどんな感じなのか、わかれば教えていただければと思ったんです。わからなければ、直接きょうのあれじゃないんで、後でも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-013"},{"speaker":"上山委員","kind":"意見","question":"もう一つだけ。それで、ちょっとお尋ねなんですけれども、これもきょう直接の議題じゃありませんから、ここで論議するつもりもないんですけれども、戸数はわかりますけれども、例えば子育て世帯かどのぐらいがよくわかりませんけれども、学校だとか、保育園だとか、そういう施設を含めて、そういうことも現状から見ればぐっと増えて、大丈夫なのかなと思ったりするんです。","respondent":"南雲都市開発課長、岩田管理工事課長","answer":"その推計値でいきますと、周辺の隣接する小学校、中学校で十分に対応できるであろうという推計をしていると聞いてあります。やはり同じ戸数でも、これまでに比べますと、子どもが発生する数は減っている。駐輪場につきましては、四角く点線で囲ってあるのが品川シーサイド駅になるんですが、このちょうど真下の部分の交通広場部分に、約７００台の規模の駐輪施設を持つ。再開発事業で生み出す計画になって、現在、工事中です。","voiceIndex":38,"id":"exchange-014"},{"speaker":"上山委員","kind":"質問・要望","question":"江東区もそういうことで、何か要望だとか、変えるような話も伺いましたけれども、単純に品川区もそうしろとは、私は申し上げる気もありませんけれども、今度、そういう狭い、今まであまりなかったところにどんどん増えちゃうと、やっぱり人口の問題だとか、インフラの整備の問題も、区が担当を全部やるということではないと思うんですけれども、そういう問題も発生してくるんじゃないかと思いましたので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-015"},{"speaker":"石田委員","kind":"質問・要望","question":"１点だけ、ちょっと確認をしたいんですけれども、再開発地区にいろいろな工事をかけている中で、たまたまここに不幸にして火災が起こって、１人亡くなるという事故というか、そういうことが起こったんです。こういうことが起きた場合、区としてどのような対応をして、施工業者でも、開発業者でもどこでもいいけれども、そういうところにどういう対応を求めるのか、どこまで事情説明を求めるのか。","respondent":"南雲都市開発課長","answer":"今後の指名などについても、場合によってはなくなるというようなこともありますが、今回の場合には、都市計画を定める中で、どのような施設をつくるかについては行政としてもかかわっておりますが、その後の工事につきましては、民間の事業者が工事を発注しておりまして、直接。","voiceIndex":42,"id":"exchange-016"},{"speaker":"石田委員","kind":"質問","question":"そうすると、個別の契約はもちろんわかりますけれども、こういう場合についての説明というのは、必ず来ることになっているんでしょうか。今のお話だと、説明責任というのか、こういう事故があったときの報告義務というのか、それは相手に任されていて、品川区に来るのか、来ないのかというのが明快じゃなかったような気がするんです。そこら辺のところはあるのか、ないのか、ちょっと明解に教えてください。","respondent":"南雲都市開発課長","answer":"提携にもよりまして、生命にかかわるようなこういう大きな事故の場合には、その都度、事業者から報告は受けております。","voiceIndex":44,"id":"exchange-017"},{"speaker":"石田委員","kind":"質問・要望","question":"都市計画はこれからいろいろなところがあると思うんですが、申し合わせ事項でも何でもいいんだけれども、そういう形の中で、そういう報告を受ける体制を、ある程度明解にしていただいて、ぜひ、それについて、区としても、それに対してものを申せるんであれば、ものを申していけるようなものが、もちろん法的には別なんだけれども、申し合わせ事項みたいな形の中で要望ができれば。","respondent":"南雲都市開発課長","answer":"やはり、労働災害を減らすという点からも、仮に事故が起きた場合には、現場の管理体制をさらに向上させるように、行政としても、各事業者にその辺の要請を行っていきたいと考えております。事故の内容によりましては、委員会でも報告をさせていただきたいと考えております。","voiceIndex":46,"id":"exchange-018"},{"speaker":"川西委員","kind":"質問・要望","question":"簡単なことです。そういうことがありますから、さっきのご質問の中でいただいた答弁では、今後、もう少し調整をしてみて働きかけるようなことですから、そういう答弁なのかと思うんですけれども、お答えができなければ、要望にとどめます。だから、そういう点では、住民の声としてお考えいただきたい。さっき、路線については細かいものを示されるということなんでしょうから、それでも結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-019"},{"speaker":"横山委員","kind":"質問・要望","question":"直接これに関係ないんですけれども、これまでの３件、大崎駅西口、東口、それにこれに係わる内容で、再開発で道路提供というか、道路の定義をちょっと教えてほしいんです。そういった整備の中で、８ｍだとか、１０ｍ、１２ｍと、いろいろと幅員の求め方が違ってくる。そして１２ｍを求めるときには、片側２車線、４車線を取ろうとして求めているのか。幅員に対して、車線をどう考えているのか。","respondent":"岩田管理工事課長","answer":"ですから、委員のおっしゃるような、ほんとうに望ましい道路というのは、東品川四丁目の中央に走っている区画街路がいわゆる１５ｍ。当時は、最低幅員１５ｍが都市計画の定めでありましたので、１５ｍ取っているのが一番望ましいものです。","voiceIndex":53,"id":"exchange-020"},{"speaker":"横山委員","kind":"質問","question":"今、お答えをいただいたように、それぞれの地域で提供していただくというか、整備している道路幅がみんなまちまちなんで、どうしてかなというと、それぞれのまちの環境というか、実情がそこに反映されているんだと思うんです。それだったら、３本走っている、Ａ、Ｂ、Ｃ、Ｄだったか、何度も聞くけど、１２ｍ取っているんだけれども、これは全部車道ですか。それでいいですから。","respondent":"南雲都市開発課長","answer":"西口の道路でいきすと、１２ｍの道路というのは、歩道も含めたものでございまして、車の通る車道部分は８ｍございまして、両側に２ｍずつの歩道です。","voiceIndex":55,"id":"exchange-021"},{"speaker":"横山委員","kind":"質問","question":"それに平行して、歩行者通路２号というのが、８ｍの１８０ｍ走っていますよね。前に戻っちゃって悪いんだけれども、これも、今言うように、そういう考え方でよろしいんですかね。","respondent":"南雲都市開発課長","answer":"歩行者通路２号といいますのは、これはペデストリアンデッキでございまして。","voiceIndex":57,"id":"exchange-022"},{"speaker":"横山委員","kind":"質問","question":"直接関係ないんで、結構です。道路の定義をちょっとお聞きしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-023"},{"speaker":"石田委員","kind":"確認","question":"私もこういう数字のことはわからないので、今の横山委員のお話の中で、確認だけしたいんですが、公開空地を利用するというお話があったですよね。例えば東五反田で、今度民間でやるとかいろいろあると思うんですが、これは完全にお願いをしていく話になると、できるできないという場合が出てくる可能性もあるのですか。そこら辺の点を、法律的なことはわからないので、ちょっと教えてください。","respondent":"南雲都市開発課長","answer":"そういう場合には、セットバックするというか、後退することが物理的に不可能な場合もありますので、そういうものも含めて全部というわけにはいきませんが、計画的にされる規模の大きいものについては、最大限、地元のほうと協議を行いまして。","voiceIndex":64,"id":"exchange-024"},{"speaker":"本田委員","kind":"質問","question":"今の東品川四丁目について言えば、四丁目でも、新しく真ん中に道路をつくりますよね。それを、何％出しなさいというようなきつい言い方をするのかどうかわからないけれども、協議の中で、どういう道路づけがこの開発の形状としてどういう道路幅員がいいのか、それが減歩率に合っているのかどうなのかというようなことが、根拠としてあるんじゃないですか。そこはどうなんでしょうか。","respondent":"岩田管理工事課長","answer":"したがって、再開発地区計画で大もとに考えるのは、まず都市基盤整備をどういうふうに考えるのか。それだけ都市基盤整備ができれば、その土地に見合った容積としてはどれぐらいになりますよというのがまず第一の見直し容積になるわけです。","voiceIndex":66,"id":"exchange-025"},{"speaker":"本田委員","kind":"質問","question":"先ほど、横山委員の質問を聞いていながら、１２ｍとか、１５ｍとか、それぞれの置かれている地域の状況に応じて、原則的なものからその状況に合ったものを検討されてきたんだなということを理解するんですが、その法的な根拠として、行政が指導する際に、お願いしますじゃなくて、最低線、減歩というものの考え方があるならば、それだけ土地の価値が上がるんだから。","respondent":"南雲都市開発課長","answer":"これは、区画整備の減歩とは中身は違うんですけれども、考え方としては同じようなものでございまして、再開発地区計画の中では、道路ですとか、公園をどれだけ出したかに応じて、容積率をアップさせるということでバランスを取るということです。","voiceIndex":68,"id":"exchange-026"},{"speaker":"本田委員","kind":"質問","question":"減歩率何％というのは、区画整理でやるような決まり事とは違って、開発については、ものの考え方としては、道路確保をするについても、減歩的な考えはあるけれども、状況に応じてボーナスをどういうふうにつけるかを含めて、空地、道路の確保を協議の中で検討すると理解してよろしいんですか。","respondent":"南雲都市開発課長","answer":"それに基づいて計算して、容積を上積みしていくというやり方をとっております。","voiceIndex":70,"id":"exchange-027"},{"speaker":"宮崎委員","kind":"質問","question":"先ほどの上山委員の質問に関連して、ちょっと聞きたいんです。住宅棟が２棟できて、住宅が８００戸できるということで、それに関連して、公共施設への影響がどうなのかという質問だったんですけれども、それは影響ないという結論は、先ほどのご答弁であったんですけれども、その調査の概要といいますか、どういう感じの内容だったのか、ちょっと教えていただければと思います。","respondent":"岩田管理工事課長、南雲都市開発課長","answer":"ただし、具体的に２ＬＤＫがどのぐらい占めるか、１ＬＤＫがどれぐらい占めるかといういわゆる間取りの規模によっても大きく左右されてまいりますので、これについては、現在の建築計画の中で、公団側がかなり詳細に発生率を出して。ただいま、都市整備公団ではいろいろ管理しておりまして、この近辺に、天王洲ビュータワーというのが平成７年にオープンしております。","voiceIndex":72,"id":"exchange-028"},{"speaker":"宮崎委員","kind":"質問","question":"今、想定するに当たって、例えば小学生だと、２ＤＫで０.０４人とか、そういう係数があるということなんですけれども、先ほど、学校、保育園等で聞いたんですけれども、小学生、中学生、保育園児、ここら辺で具体的何人というのは出ているんですか。","respondent":"南雲都市開発課長","answer":"シーサイドフォレストで何人というのは、ちょっとはっきりしておりませんが、例として二丁目第１地区の場合、小学生で、分譲、賃貸を合わせまして２８人ということを推計して、周辺の小学生でこのぐらいの児童が増えるだろうということで、事前に計画の中に盛り込んでおります。","voiceIndex":75,"id":"exchange-029"},{"speaker":"宮崎委員","kind":"質問・要望","question":"今のご答弁で、小学生２８人ですか。８００戸で２８人ですか。〔「二丁目第１地区」と呼ぶ者あり〕わかりました。では、先ほど、保育園の考えが公団のほうであるとかないとかおっしゃったんですが、その後、どういう中身なのか、わかっていたら教えていただきたい。区はどういうふうに考えているか。そこのところを、区の考え方というのをちょっと聞かせていただければと思います。","respondent":"南雲都市開発課長","answer":"これにつきましては、ほかの周辺も含めまして、公団で相当な戸数の賃貸住宅を管理しておりますので、過去の公団の例からの推計で、大きく数字が違うということはございませんので、おおむね公団の推計した数字ぐらいの生徒が発生するということで。","voiceIndex":77,"id":"exchange-030"},{"speaker":"宮崎委員","kind":"質問","question":"わかりました。先ほどの、もし具体的に何人というのがわかったら、後で教えていただければと思います。保育園のほうのことで、その後のことがわかったら。それから、住宅のことで、先ほど、２ＤＫの例が言われましたけれども、今の時点で、どういう内容で住宅が計画されているのか。広さとか、家賃とか、ポイントをちょっと教えていただければと思います。","respondent":"岩田管理工事課長","answer":"申しわけございません。ちょっと手元に資料がすぐに出てきませんので、今、取りにまいりますので、後ほどご報告します。","voiceIndex":79,"id":"exchange-031"},{"speaker":"伊藤副委員長","kind":"質問","question":"二つお伺いします。先ほど、議論が出ましたけれども、青物横丁駅付近の交通量を調査したということは聞きました。それからどうするのかということのほうが、むしろ関心がありますので、調査の交通量の結果が数字として出ますでしょ、その結果をもとに、これからどうしていくのかということをお聞かせくださいということが一つ。二つほど、お願いします。","respondent":"南雲都市開発課長","answer":"先ほど、ありましたように、大崎駅周辺に比べますと、品川シーサイド駅周辺につきましては、広幅員の道路が網の目のように走っているということで、片側２車線以上ある道路が相当あるということで、交通をさばける容量としては、相当深い能力を持っている地域です。","voiceIndex":81,"id":"exchange-032"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"推計では渋滞が出ない。実際に、ここにまちができて、交通アクセスとか、いろいろなことに対して非常に快適なものを求めていくわけですし、各委員がおっしゃったように、交通アクセスの問題もそうです、バスのアクセス、それから人とか自転車とか、当然、小さなまちができるわけですから、そういうことに関して、数字の上だけでつかんで、それでいいですよって、私はちょっと違うような気がするんです。","respondent":"中谷まちづくり事業部長","answer":"残りの現実的な問題としては、土日に集中するというようなことがありますから、こういうものについては、例えばジャスコのオープンのときなどを控えては、周辺のソフト対応、先ほど委員のお話もありましたように、例えばガードマン、あるいは臨時看板みたいなものを出すとか。","voiceIndex":83,"id":"exchange-033"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"だから、そのことを繰り込んで、今、部長がおっしゃったような、お金をかけない対策ができるわけですから、看板をつけるとか、誘導の工夫をするとか、ジャスコにお願いして店内でもそういうＰＲをしていただくとか、簡単な発想でいろいろな効果ができるはずなんですよ。そういうことを含めて、ぜひ、このまちづくりに関しては進めていっていただきますように要望しておきますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-034"},{"speaker":"宮崎委員","kind":"意見","question":"保育所のほうは、協議中だということなので、早く結論が出るように願いたいと思います。教育とか、そういうものを含めてのまちづくりだと思っていますので、ちょっとそこのところだけ一言言っておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":89,"id":"exchange-035"},{"speaker":"三上委員","kind":"質問","question":"２月１２、１３日に出席された方は、どれぐらいいらっしゃるんでしょうか。このアンケート調査に基づいた区の考え方はこうですということを住民に周知するという部分、そういったことについてはどういうふうに考えていらっしゃるのか、このあたりを聞かせてほしい。","respondent":"浜脇住環境整備課長","answer":"それが４月２４日で２０名です。２５日が２５名です。計４日間、やらせていただきました。周知につきましては、当然、まちづくりニュース等でやって、こういうご意見があったというようなことも含めて、１,７００部ですけれども、ニュースを全戸配布しています。","voiceIndex":97,"id":"exchange-036"},{"speaker":"三上委員","kind":"質問・要望","question":"４月にやったというので、少しは安心したんです。最初の説明のとき、２月１２、１３日に何名出席したかという数字も言わないし、これは悲惨な状況だったんだなというような感じがしたんです。こういった防火不燃に対してのまちづくりの考え方ですから、全戸配布ということを、これ１回限りということではなくて、いろいろな状況を利用して徹底していっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-037"},{"speaker":"宮崎委員","kind":"意見","question":"先ほどもちょっと言ったんですけれども、本来、ここだと学区はどこになるんでしたっけ。小学生で８６名だと、単純に言うと３クラスになるわけですね。そこで、教育委員会の発想が、ブロックとしてキャパシティがあるということなのか、どうなのか。そこら辺のところは、街づくり事業部としては、どういうふうに受けとめておられるのか。","respondent":"岩野まちづくり事業部次長","answer":"この計画協議をしていたときには、ブロック以前でございまして、ここの学区の学校の余裕人員と発生の人員ということでやって、大丈夫という結論を出したと考えています。","voiceIndex":109,"id":"exchange-038"},{"speaker":"上山委員","kind":"質問・要望","question":"あちこち増えちゃって、もうわからないぐらいに多くなっているような感じがしまして、そのあたり含めてもしあれば、もうちょっとわかりよくまとめていただけないかと、要望しておりますので、よろしくお願いいたします。","respondent":"南雲都市開発課長","answer":"各地区で相当いろいろ開発をしていますので、各地区の概要をまとめたあらましというものをつくっております。まちづくりマップということで、実際の地図上でどの場所をというのがありますので、そちらの資料をごらんいただきたいと思います。必要でしたら、お持ちいたします。","voiceIndex":113,"id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6230#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":43487,"voices":118}},{"id":"h14-20020521-5","meetingId":"h14-cm05","date":"2002年5月21日","dateIso":"2002-05-21","committee":"総務委員会","time":"午前１１時０３分～午後 ３時２５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"林（宏）委員","kind":"意見","question":"今の説明を、非常にさっぱりした感じを受けながらききました。この反対に品川区としてどういう思いを持っているのかというのがほとんど伝わらない説明で、よその話を聞いているような感じを受けたんですけれども、実際に品川区として移転問題にどういうふうに思いをはせているのか、その辺の品川区としての気持ち、考え方をお聞かせ願いたい。","respondent":"小野（孝）政策担当課長","answer":"説明が事実経過だけに限らせていただきましたけれども、品川区は区民憲章でも言っておりますように、東京の東海道一の地区ということで、東京都の中では非常に伝統のある地区ですし、京浜工業地帯の発祥の地、近代日本の産業の発祥の地ということで。","voiceIndex":5,"id":"exchange-001"},{"speaker":"林（宏）委員","kind":"意見","question":"やっぱり、国が決めることにすべて従うということではなくて、今は地方分権、地方主権とまで言われている時代に入ってきたのなら、首都というものを支えている地方自治体としては、もっと鮮明に打ち出していっていいんじゃないのかなという思いがするんですけれども、すぐに何をというと、パンフレットをつくったらどうのというわけではないんだけれども。","respondent":"中尾根企画部長","answer":"しかし、国会レベルの法律的な段階の中では、思った以上に進展してきておりましたので、そういう意味では第三次長期計画の中での位置づけが自治権拡充の一本の中に出てきましたので。","voiceIndex":7,"id":"exchange-002"},{"speaker":"林（宏）委員","kind":"意見","question":"我々が行政視察でたまたま候補地にエリアに行って実際の職員に聞いてみると、「上のほうで何かやっているみたいですね」とか、「何々先生は一生懸命のようですけれども、我々にはどうも」という答えが返ってくる。真実はどうかわからないけれども、我々を東京ということでお世辞的に言っているのかもわからないけれども。地方の自治体はそんなに一生懸命に見えない。","respondent":"濱野助役","answer":"この時点に来て、やはり現実のことを目の前にしながら、実際にそうなったらどうなるのかということを考えると、地方自治法自体も大分いじらなければならないような事態だと思いますし。","voiceIndex":9,"id":"exchange-003"},{"speaker":"林（宏）委員","kind":"質問","question":"移転しなくても危機回避みたいな部分があるわけですから、そういうところをどんどん言っていくべくだし、２３区あるいは三多摩のほうも含めた東京都の市町村が、それこそ手を結んで東京都と連携を取って声を出していく、あるいは首都圏の市町村も含めた連帯を、今助役が言われた向こうの市町村が最初は気合を入れていたのが、今はそれが削がれてきているんだけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-004"},{"speaker":"土井副委員長","kind":"提案","question":"よその区市町村も含めた方々ですから、１ページ目をあけたら、そこに「品川区は反対です」という場面が流れてくるようなものを早速始めていただきたいと思うんです。これだったら、次の何かの改定のときにちょっとそこに入れることはできるでしょう。ぜひ、それぐらいから始めましょうということで提案をするんですが、お考えをお伺いします。","respondent":"中尾根企画部長","answer":"実際上、そういうことについて今まで何も取り上げてきていなかったということですから、できるところから始めたいということで考えておりましたので、そのことは十分受け止めさせていただきたいと思います。","voiceIndex":12,"id":"exchange-005"},{"speaker":"宮崎委員","kind":"確認","question":"確認しておきたいんですけれども、資料１の最初に経過があって、国が主張する移転の意義があってその次に新都市の規模、４番として移転反対の理由とあるんですけれども、移転反対の理由というのはどこが言っている理由なのかよくわからないので、資料の説明をお願いしたいと思います。","respondent":"小野（孝）政策担当課長","answer":"これは東京都が全体の事務局になっているということもありますけれども、東京都、２３区を含めて、こういう視点で反対をしているです。","voiceIndex":14,"id":"exchange-006"},{"speaker":"塚本委員","kind":"質問","question":"その張本人が権力を失って亡くなってしまいましたが、ほかのところへまた話が飛んでいったというような理解をしておりましたけれども、そういうレベルの話が一つとしてあるのは間違いない。少なくとも、東京都のパンフレットの中に多少書いてありますけれども、それがないと何だか感情論に、あるいは既得権益を守るだけの話になってしまうというような気がするんですけれども、どうですか。","respondent":"濱野助役","answer":"そういう論点を絡め合わせて、補強しながら構築していくべきかなということで、政経の場所一致だけでは論点としては弱いのかなという感じは持っております。","voiceIndex":18,"id":"exchange-007"},{"speaker":"塚本委員","kind":"意見","question":"政経の場所が一致しているということ、中央集権でなおかつ経済もひっくるめて圧倒的な一極であったということに対する反省というものが、一方で必要である。バブルの泡がしぼんでいるのを、だれを後始末をしなかったというだけの話になってしまうという気がしますので、そこのところを私のほうは留意したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":20,"id":"exchange-008"},{"speaker":"田中委員","kind":"質問","question":"部長もおっしゃられた熱き思い、あるいはいろいろな形での部分を論理的に組み立てて反対運動を展開するということなんですが、ぜひそれをお願いしたいと思うんです。行政の立場に立ったときの質問なんですが、マイナスがいっぱいあるというのは認識していますが、行政面において首都が現在の都庁なり永田町から国会が離れてしまうことの弊害というのは、どういうふうに認識をされていらっしゃいますか。","respondent":"中尾根企画部長","answer":"単に弊害という部分ですけれども、今の日本の政治経済の構造の中で、実際上は首都ないしは地方という関係から見ると、それがほかのところに行ったら、ほかのところが首都圏の機能をやるとすると、東京が地方になったという関係ですけれど、本質的な問題とすれは。","voiceIndex":21,"id":"exchange-009"},{"speaker":"林（宏）委員","kind":"意見","question":"みずほの関係なんですけれども、一連のみずほの混乱がどうにかおさまっているというふうに聞いていますけれども、東京都は来週あたりに金融の検討委員会か調査委員会か開いて、指定金融機関も含めて検討するということを発表しているんだけれども、品川区としてはみずほに対して何をするべきかというか、何かするという考えがあるのかどうか聞かせてください。","respondent":"小野（弘）副収入役","answer":"支店のほうでは、やはり具体的な原因については把握している状況ではございませんので、ある程度落ち着いた状況になりましてから、もう一度臨時検査という形で、検査といいましても新銀行になってからのいろいろな処理の仕方。","voiceIndex":25,"id":"exchange-010"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"それにみずほがどう対応してくるのかという問題もひきずっていると思うんです。だったら、やっぱり今日みずほの件に関しては、現段階までの報告をすべきだったと思うので、委員会に何を報告していくことが行政としての役目かというのを考えながら報告を尽くしていってほしいなと思うので、お願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-011"},{"speaker":"土井副委員長","kind":"意見","question":"この１年間、総務委員会の副委員長を務めさせていただきました。委員の皆さん、あるいは理事者の皆さん、また事務局の皆さんに大変なご理解とご協力をいただいて進めてこれたと思いますし、委員長の采配よろしきもございまして、あまり副委員長の出場所がなかったんじゃないかなということで、その意味で感謝を申し上げておきたいというふうに思います。そんな意味で、あいさつに代えします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":30,"id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1580#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":12810,"voices":31}}]);
